/**
 * Formats Date into MM-DD format
 * @param {Date} date date that needs to be formatted
 * @returns date string in MM-DD format
 */
const getFormattedMonthDay = (date) => {
  const month = (date.getMonth() + 1).toString().padStart(2, '0');
  const day = date.getDate().toString().padStart(2, '0');
  return `${month}-${day}`;
};

/**
 * Takes in date string and checks whether the date is of today, tomorrow or yesterday
 * @param {string} dateString
 * @returns string that indicates whether the date is of today, tomorrow or yesterday
 */
const checkDate = (dateString, ignoreCurrentYear) => {
  const inputDate = new Date(dateString);
  const currentDate = new Date();

  // Set the time of both dates to midnight to compare only the dates
  inputDate.setHours(0, 0, 0, 0);
  currentDate.setHours(0, 0, 0, 0);

  let timeDifference;
  if (ignoreCurrentYear) {
    if (currentDate.getFullYear() === inputDate.getFullYear())
      timeDifference = 2;
    else {
      inputDate.setFullYear(currentDate.getFullYear());
      timeDifference = (inputDate - currentDate) / (1000 * 60 * 60 * 24); // Difference in days
    }
  } else {
    inputDate.setFullYear(currentDate.getFullYear());
    timeDifference = (inputDate - currentDate) / (1000 * 60 * 60 * 24); // Difference in days
  }

  switch (timeDifference) {
    case 0:
      return 'Today';
    case 1:
      return 'Tomorrow';
    case -1:
      return 'Yesterday';
    default:
      return 'None of Today, Tomorrow, or Yesterday';
  }
};

function daysInMonth(month, year) {
  return new Date(year, month, 0).getDate();
}

function isFirstNthDayOfMonth(date, day, n) {
  const targetDate = new Date(date);
  const targetDay = targetDate.getDay(); // Get the day index (0 = Sunday, 1 = Monday, ..., 6 = Saturday)
  const targetMonth = targetDate.getMonth(); // Get the month index (0-based)

  let count = 0;

  // Loop through the days of the month until the target date is reached
  for (let i = 1; i <= 31; i++) {
    const tempDate = new Date(targetDate.getFullYear(), targetMonth, i);
    if (tempDate.getMonth() !== targetMonth) {
      break; // Stop when the next month is reached
    }
    if (tempDate.getDay() === getDayIndex(day)) {
      count++;
      if (count == n) {
        // Check if the current day is the target date
        return tempDate.getDate() === targetDate.getDate();
      }
    }
  }

  return false; // If the nth day of the week is not found in the month
}

// Helper function to get the index of the day of the week
function getDayIndex(day) {
  return [
    'sunday',
    'monday',
    'tuesday',
    'wednesday',
    'thursday',
    'friday',
    'saturday',
  ].indexOf(day.toLowerCase());
}

function getNthDayOfMonthDates(start_date, end_date, day_of_week, nth) {
  const startDate = new Date(start_date);
  const endDate = new Date(end_date);
  const resultDates = [];

  let currentDate = new Date(startDate);

  while (currentDate <= endDate) {
    if (currentDate.getDay() === getDayIndex(day_of_week)) {
      const result = isFirstNthDayOfMonth(currentDate, day_of_week, nth);
      if (result) resultDates.push(currentDate.toISOString().slice(0, 10));
    }
    // Move to the next day
    currentDate.setDate(currentDate.getDate() + 1);
  }

  return resultDates;
}

// Helper function to get the index of the day of the week
function getDayIndex(day) {
  return [
    'sunday',
    'monday',
    'tuesday',
    'wednesday',
    'thursday',
    'friday',
    'saturday',
  ].indexOf(day.toLowerCase());
}

async function getWeekoffDates(
  weekoffid,
  startdate,
  enddate,
  UserMasterID,
  transaction,
) {
  try {
    let alldata = [];
    alldata = await WeekoffOptions.findAll({
      where: {
        weekOffPolicyID: weekoffid,
      },
      include: [{ model: weekOffPolicy }],
      transaction,
    });
    function Value(option) {
      if (option.slice(0, 4) == 'full') {
        return 1;
      } else {
        return 0.5;
      }
    }

    function dayType(option) {
      if (option.slice(0, 4) == 'full') {
        return 'FD';
      } else if (option.slice(0, 5) == 'first') {
        return 'FH';
      } else {
        return 'SH';
      }
    }

    function getDate(start_date, end_date, day0) {
      let startYear = parseInt(start_date.slice(0, 4));
      let startMonth = parseInt(start_date.slice(5, 7)) - 1; // Adjust month to 0-based index
      let startDay = parseInt(start_date.slice(8, 10));

      let endYear = parseInt(end_date.slice(0, 4));
      let endMonth = parseInt(end_date.slice(5, 7)) - 1; // Adjust month to 0-based index
      let endDay = parseInt(end_date.slice(8, 10));

      let currentDate = new Date(startYear, startMonth, startDay);
      let endDate = new Date(endYear, endMonth, endDay);

      let day_val;

      if (day0 == 'sunday') {
        day_val = 0;
      } else if (day0 == 'monday') {
        day_val = 1;
      } else if (day0 == 'tuesday') {
        day_val = 2;
      } else if (day0 == 'wednesday') {
        day_val = 3;
      } else if (day0 == 'thursday') {
        day_val = 4;
      } else if (day0 == 'friday') {
        day_val = 5;
      } else {
        day_val = 6;
      }

      let day_date = [];

      // Loop through all days between start_date and end_date
      while (currentDate <= endDate) {
        if ((currentDate.getDay() + 7) % 7 === day_val) {
          day_date.push(moment(currentDate).format('YYYY-MM-DD'));
        }

        currentDate.setDate(currentDate.getDate() + 1); // Move to the next day
      }
      day_date = day_date.filter(
        (date) => date >= start_date && date <= end_date,
      );

      return day_date;
    }
    let arr = [];
    for (let i = 0; i < alldata.length; i++) {
      for (j = 0; j < alldata[i].dataValues.options.length; j++) {
        let value = Value(alldata[i].dataValues.options[j].option);
        let temp_date = [];
        let day = alldata[i].day;
        let year = String(startdate).slice(0, 4);
        let month = String(startdate).slice(5, 7);
        let yearMonth = year + month;
        let day_option = alldata[i].dataValues.options[j].name.slice(0, 3);
        let WHDayType = dayType(alldata[i].dataValues.options[j].option);
        if (day_option != 'all') {
          const firstLetter = day_option.trim().charAt(0);
          temp_date = getNthDayOfMonthDates(
            startdate,
            enddate,
            day,
            firstLetter,
          );
          for (let item of temp_date) {
            let Year = item.slice(0, 4);
            let Month = item.slice(5, 7);
            let monthyear = Year + Month;
            let temp = {
              companyMasterID:
                alldata[i].weekOffPolicy.dataValues.companyMasterID,
              userMasterID: UserMasterID,
              yearMonth: monthyear,
              date: asiaKolkataDateTime(new Date(item)).slice(0, 10),
              dayName: alldata[i].day,
              value: value,
              WHDayType: WHDayType,
              tableName: 'weekoff',
            };
            arr.push(temp);
          }
        } else {
          for (k = 0; getDate(startdate, enddate, day)[k] != null; k++) {
            temp_date = getDate(startdate, enddate, day)[k];
            let Year = temp_date.slice(0, 4);
            let Month = temp_date.slice(5, 7);
            let monthyear = Year + Month;
            let temp = {
              companyMasterID:
                alldata[i].weekOffPolicy.dataValues.companyMasterID,
              userMasterID: UserMasterID,
              yearMonth: monthyear,
              date: asiaKolkataDateTime(new Date(temp_date)).slice(0, 10),
              dayName: alldata[i].day,
              value: value,
              WHDayType: WHDayType,
              tableName: 'weekoff',
            };
            arr.push(temp);
          }
        }
      }
    }

    return arr;
  } catch (error) {
    throw new Error('Error in Get Weekoff Dates: ' + error.message);
  }
}

async function getHolidayDates(
  holidayid,
  startdate,
  enddate,
  UserMasterID,
  transaction,
) {
  try {
    let alldata = [];
    alldata = await holidayList.findAll({
      where: {
        holidayPolicyID: holidayid,
      },
      include: [{ model: holidayPolicy }],
      transaction,
    });
    function get_day(date) {
      temp = date.getDay();
      days = [
        'sunday',
        'monday',
        'tuesday',
        'wednesday',
        'thursday',
        'friday',
        'saturday',
      ];
      return days[temp];
    }
    let arr = [];
    for (let j = 0; j < alldata.length; j++) {
      for (let i = 0; i < alldata[j].holidayDate.length; i++) {
        let holidayday_date = moment(alldata[j].holidayDate[i])
          .tz('Asia/Kolkata')
          .format('YYYY-MM-DD');
        if (
          new Date(startdate) <= new Date(holidayday_date) &&
          new Date(enddate) >= new Date(holidayday_date)
        ) {
          let temp = {
            companyMasterID:
              alldata[j].holidayPolicy.dataValues.companyMasterID,
            userMasterID: UserMasterID,
            yearMonth: Number(
              new Date(alldata[j].holidayDate[i].getTime() + 1000 * (60 * 330))
                .toISOString()
                .slice(0, 10)
                .slice(0, 4) +
                new Date(
                  alldata[j].holidayDate[i].getTime() + 1000 * (60 * 330),
                )
                  .toISOString()
                  .slice(0, 10)
                  .slice(5, 7),
            ),
            date: new Date(
              alldata[j].holidayDate[i].getTime() + 1000 * (60 * 330),
            )
              .toISOString()
              .slice(0, 10),
            dayName: get_day(alldata[j].holidayDate[i]),
            value: 1,
            tableName: 'holiday',
            optionalHoliday: alldata[j].optionalHoliday[i],
          };
          arr.push(temp);
        }
      }
    }

    return arr;
  } catch (error) {
    throw new Error('Error in Get Holiday Dates: ' + error.message);
  }
}

// For Time Format
function formatAMPM(date) {
  var hours = date.getHours();
  var minutes = date.getMinutes();
  var ampm = hours >= 12 ? 'PM' : 'AM';
  hours = hours % 12;
  hours = hours ? hours : 12; // the hour '0' should be '12'
  minutes = minutes < 10 ? '0' + minutes : minutes;
  var strTime = hours + ':' + minutes + ' ' + ampm;
  return strTime;
}

async function checkHoliday(userMasterID, date) {
  let returnvalue = 0;

  let Isholiday = await weekoffHolidayTran.findOne({
    where: {
      userMasterID: userMasterID,
      date: date,
      [Sequelize.Op.or]: [
        { optionalHoliday: false },
        { optionalHoliday: null },
      ],
    },
  });

  if (Isholiday) {
    returnvalue = 1;
  }

  return returnvalue;
}

async function deleteOvertimeForAttendance(userMasterID, AttendanceDate) {
  let overtimedata = await overTimeCalculation.findAll({
    where: {
      UserMasterID: userMasterID,
      OverTimeDate: AttendanceDate,
    },
    attributes: ['OverTimeID'],
  });

  if (overtimedata.length) {
    await OvertimeAuthorizationRequest.destroy({
      where: {
        ReferenceID: overtimedata.map((e) => e.OverTimeID),
      },
    });

    await overTimeCalculation.destroy({
      where: {
        OverTimeID: overtimedata.map((e) => e.OverTimeID),
      },
    });
  }
}

async function delete_Overtime_Attendance_Manual(
  userMasterID,
  AttendanceDate,
  transaction,
  otRequestType = null,
) {
  try {
    const condition = {
      UserMasterID: userMasterID,
      OverTimeDate: AttendanceDate,
    };

    if (otRequestType === OvertimeRequestTypeEnum.POST_SHIFT) {
      condition[Sequelize.Op.or] = [
        {
          otRequestType: OvertimeRequestTypeEnum.POST_SHIFT,
        },
        {
          otRequestType: {
            [Sequelize.Op.is]: null,
          },
        },
      ];
    } else if (otRequestType) {
      condition.otRequestType = otRequestType;
    }

    const options = transaction ? { transaction } : {};

    const overtimedata = await overTimeCalculation.findAll({
      where: condition,
      ...options,
      attributes: ['OverTimeID'],
    });

    if (overtimedata.length) {
      await OvertimeAuthorizationRequest.destroy({
        where: {
          ReferenceID: {
            [Sequelize.Op.in]: overtimedata.map((e) => e.OverTimeID),
          },
        },
        ...options,
      });

      await overTimeCalculation.destroy({
        where: {
          OverTimeID: overtimedata.map((e) => e.OverTimeID),
        },
        ...options,
      });
    }
  } catch (error) {
    throw new Error('Error in deleteOvertimeForAttendance: ' + error.message);
  }
}

