async function addCoff(
  userMasterID,
  date,
  LeaveAddNew,
  createBy,
  createByIp,
  autoApproveCoff = false,
  otAdded,
  monthlyOtCalType,
) {
  let company = await UserMaster.findOne({
    where: {
      userMasterID: userMasterID,
    },
  });

  let trans = await HrLeaveTypes.findOne({
    where: {
      LeaveID: 6,
      companyMasterID: company.companyMasterId,
    },
  });
  if (trans) {
    let LeaveTranId = trans.LeaveTranId;

    let YearMM = date.substring(0, 7);
    YearMM = YearMM.replace('-', '');

    const coff = await coffMaster.findOne({
      where: {
        userMasterID: userMasterID,
        LeaveCreatedDate: date,
        [Sequelize.Op.or]: [
          { From: { [Sequelize.Op.is]: null } },
          { From: '' },
        ],
      },
      include: [
        { model: HrLeaveBalance, include: [{ model: UsedCoffTransaction }] },
      ],
    });

    if (coff) {
      const usedCoff = coff.hrLeaveBalance?.usedCoffTransactions || [];

      if (usedCoff.length) return;

      if (coff.LeaveBalTranId) {
        await HrLeaveBalance.destroy({
          where: {
            LeaveBalTranId: coff.LeaveBalTranId,
          },
        });
      }

      if (coff.authorizationStatus != 0) {
        const authData = await CompensatoryOffAuthorization.findAll({
          where: {
            coffMasterID: coff.coffMasterID,
          },
        });

        const allIds = authData.map((e) => e.CompensatoryOffAuthorizationID);

        await UserInbox.destroy({
          where: {
            activityTable: CompensatoryOffAuthorization.getTableName(),
            activityTablePK: allIds,
          },
        });

        await CompensatoryOffAuthorization.destroy({
          where: {
            coffMasterID: coff.coffMasterID,
          },
        });

        await coffMaster.destroy({
          where: {
            userMasterID: userMasterID,
            LeaveCreatedDate: date,
          },
        });
      }
    }

    // if coff set auto Approved
    if (autoApproveCoff) {
      return await autoApprove_Coff_On_WH(
        userMasterID,
        date,
        LeaveAddNew,
        YearMM,
        LeaveTranId,
        createBy,
        createByIp,
      );
    }

    await coffAuthorization(
      userMasterID,
      date,
      LeaveAddNew,
      YearMM,
      LeaveTranId,
      createBy,
      createByIp,
    );
  }
}

