// auto approve coff on weekoff/holiday
async function autoApprove_Coff_On_WH(
  userMasterID,
  date,
  LeaveAddNew,
  YearMM,
  LeaveTranId,
  createBy,
  createByIp,
  transaction = null,
) {
  if (
    !userMasterID ||
    !date ||
    !LeaveAddNew ||
    !YearMM ||
    !LeaveTranId ||
    !createBy
  )
    return false;

  const t = transaction || (await sequelize.transaction());

  try {
    const emp_LeavePolicy = await empLeavePolicy.findOne({
      where: {
        userMasterID,
        status: 1,
        applicableDate: { [Sequelize.Op.lte]: new Date(date) },
        [Sequelize.Op.or]: [
          { endDate: { [Sequelize.Op.gte]: new Date(date) } },
          { endDate: null },
        ],
      },
      transaction: t,
    });

    let expiryDate = null;

    if (emp_LeavePolicy) {
      const coffPolicy = await employeeLeavePolicy.findOne({
        where: {
          id: emp_LeavePolicy.employeeLeavePolicyID,
          leaveId: 6, // COFF
        },
        attributes: ['expiryDays'],
        transaction: t,
      });

      if (coffPolicy?.expiryDays) {
        expiryDate = getDateByAddingDays(date, coffPolicy.expiryDays);
      }
    }

    const addLeaveBalance = await HrLeaveBalance.create(
      {
        LeaveTranId,
        userMasterID,
        YearMM,
        LeaveAddNew,
        createBy,
        expiryDate,
        availBal: LeaveAddNew,
      },
      { transaction: t },
    );

    await coffMaster.create(
      {
        LeaveTranId,
        LeaveBalTranId: addLeaveBalance.LeaveBalTranId,
        userMasterID,
        LeaveCreatedDate: date,
        YearMM,
        LeaveAddNew,
        authorizationStatus: 3,
        expiryDate,
        createBy,
        createByIp,
        isAutoApproved: true,
      },
      { transaction: t },
    );

    if (!transaction) await t.commit();
    return true;
  } catch (err) {
    if (!transaction) await t.rollback();
    throw err;
  }
}

