async function addExtraDaysMobile(
  attendancePolicy,
  attendanceData,
  total_In_Hrs,
  userMasterID = null,
  AttendanceDate = null,
  otAdded,
  monthlyOtCalType,
  minutesData = null,
  weekoffType = offDayCategoryEnum.WEEKOFF,
) {
  try {
    if (!minutesData) {
      minutesData = {
        halfDayMinutes: attendancePolicy?.coffhalfday,
        fullDayMinutes: attendancePolicy?.cofffullday,
        oneHalfDayminutes: attendancePolicy?.coffOneAndHalfDay,
        twoDayMinutes: attendancePolicy?.coffTwoFullDay,
      };
    }

    let otAddedMinutes = 0;
    if (minutesData?.halfDayMinutes && minutesData?.fullDayMinutes) {
      const extraHrsOTonWH = attendancePolicy.extraHrsOTonWH || false;
      const lastSlabMinutes = minutesData?.twoDayMinutes
        ? minutesData?.twoDayMinutes
        : minutesData?.oneHalfDayminutes
          ? minutesData?.oneHalfDayminutes
          : minutesData?.fullDayMinutes;
      const extraMinutes = +total_In_Hrs - +lastSlabMinutes;

      let extraDaysValue = 0;

      if (
        total_In_Hrs >= Number(minutesData.halfDayMinutes) &&
        total_In_Hrs < Number(minutesData?.fullDayMinutes)
      ) {
        extraDaysValue = 0.5;
      } else if (
        total_In_Hrs >= Number(minutesData?.fullDayMinutes) &&
        (!minutesData?.oneHalfDayminutes ||
          total_In_Hrs < Number(minutesData?.oneHalfDayminutes))
      ) {
        extraDaysValue = 1;
      } else if (
        minutesData?.oneHalfDayminutes &&
        total_In_Hrs >= Number(minutesData?.oneHalfDayminutes) &&
        (!minutesData?.twoDayMinutes ||
          total_In_Hrs < Number(minutesData?.twoDayMinutes))
      ) {
        extraDaysValue = 1.5;
      } else if (
        minutesData?.twoDayMinutes &&
        total_In_Hrs >= Number(minutesData?.twoDayMinutes)
      ) {
        extraDaysValue = 2;
      }

      if (extraDaysValue > 0) {
        // Auto Approve Extra Days on weekoff/Holiday
        if (attendancePolicy.autoApproveCoff) {
          await autoApprove_ExtraDay_On_WH(
            attendanceData?.userMasterID || userMasterID,
            attendanceData?.AttendanceDate || AttendanceDate,
            extraDaysValue,
            attendanceData?.userMasterID || userMasterID,
            '',
          );
        } else {
          await addExtraDaysAuthMobile(
            attendanceData?.userMasterID || userMasterID,
            attendanceData?.AttendanceDate || AttendanceDate,
            extraDaysValue,
            attendanceData?.userMasterID || userMasterID, //Create By
            '',
          );
        }

        // if set extra hrs as ot
        if (extraHrsOTonWH && extraMinutes > 0 && attendanceData) {
          otAddedMinutes = await coff_extraHrs_As_Overtime(
            attendanceData,
            attendancePolicy,
            extraMinutes,
            attendanceData.userMasterID,
            null,
            null,
            otAdded,
            monthlyOtCalType,
            weekoffType,
          );
        }
      }
    }

    return otAddedMinutes;
  } catch (error) {
    throw new Error('Error in add Extra Days_Weekoff: ' + error.message);
  }
}

async function addExtraDaysAuthMobile(
  userMasterID,
  date,
  extraDaysValue,
  createBy,
  createByIp,
) {
  try {
    const promiseArray = [];
    const authorizationdetails = await FormAuthorizationDetails.findOne({
      where: {
        AuthorizationMasterID: authorizationMasterTypes.compensatoryOff, // Compensatory Off
        userMasterID,
        status: 1,
      },
      include: [
        {
          model: AuthorizationCriteriaMaster,
          attributes: ['AuthorizationCriteria'],
        },
      ],
    });

    const authorizationStatus =
      authorizationdetails && authorizationdetails.AuthorizationCriteriaMaster
        ? authorizationdetails.AuthorizationCriteriaMaster
            .AuthorizationCriteria == 'Sequeance No'
          ? 2
          : 1
        : 0;

    const requestData = await ExtraDays.create(
      {
        userMasterID: userMasterID,
        date: date,
        days: extraDaysValue,
        authorizationStatus,
        createBy,
        createByIp,
      },
      { hooks: false },
    );

    if (authorizationStatus != 0) {
      // user Details
      const userDetails = await UserMaster.findOne({
        raw: true,
        where: {
          userMasterID,
        },
      });

      if (!userDetails) throw new Error('User not found!');

      // For Sequence No
      if (authorizationStatus == 2) {
        const authorizationData = await ExtraDaysAuthorization.create(
          {
            extraDaysID: requestData.extraDaysID,
            userMasterID: authorizationdetails.AuthorizedByUserMasterId[0],
            authstatus: 2,
            createBy,
            createByIp,
          },
          { hooks: false },
        );

        // Create UserInbox
        promiseArray.push(
          UserInbox.create({
            activityTable: ExtraDaysAuthorization.getTableName(),
            activityTablePK:
              authorizationData.toJSON().extraDaysAuthorizationID,
            message: `${
              userDetails.displayName
            } has requested a Extra days for ${moment(date).format(
              'DD/MM/YYYY',
            )}.`,
            assignedTo: authorizationdetails.AuthorizedByUserMasterId[0],
            assignedBy: userMasterID,
            createBy,
            createByIp,
          }),
        );

        const notification = {
          title: 'Extra Days',
          body: userDetails.displayName + ' requested for a Extra Days.',
        };
        const data = {
          screen: 'extradaysauth',
          isScheduled: 'true',
          scheduledTime: new Date().toISOString(),
        };

        // send Notification
        promiseArray.push(
          sendNotification(authorizationData.userMasterID, notification, data),
        );
      } else {
        // For Any
        for (
          let j = 0;
          j < authorizationdetails.AuthorizedByUserMasterId.length;
          j++
        ) {
          const authorizationData = await ExtraDaysAuthorization.create(
            {
              extraDaysID: requestData.extraDaysID,
              userMasterID: authorizationdetails.AuthorizedByUserMasterId[j],
              authstatus: 2,
              createBy,
              createByIp,
            },
            { hooks: false },
          );

          // Create UserInbox
          promiseArray.push(
            UserInbox.create({
              activityTable: ExtraDaysAuthorization.getTableName(),
              activityTablePK:
                authorizationData.toJSON().extraDaysAuthorizationID,
              message: `${
                userDetails.displayName
              } has requested a Extra Days for ${moment(date).format(
                'DD/MM/YYYY',
              )}.`,
              assignedTo: authorizationdetails.AuthorizedByUserMasterId[j],
              assignedBy: userMasterID,
              createBy,
              createByIp,
            }),
          );

          const notification = {
            title: 'Extra Day',
            body: userDetails.displayName + ' requested for a Extra Days.',
          };
          const data = {
            screen: 'extradaysauth',
            isScheduled: 'true',
            scheduledTime: new Date().toISOString(),
          };
          // send Notification
          promiseArray.push(
            sendNotification(
              authorizationData.userMasterID,
              notification,
              data,
            ),
          );
        }
      }

      await Promise.all(promiseArray);
    }
  } catch (error) {
    throw new Error('Error in Extra Days Auth: ' + error);
  }
}

async function coffAuthorization(
  userMasterID,
  date,
  LeaveAddNew,
  YearMM,
  LeaveTranId,
  createBy,
  createByIp,
) {
  const transaction = await sequelize.transaction();
  try {
    const authorizationdetails = await FormAuthorizationDetails.findOne(
      {
        where: {
          AuthorizationMasterID: authorizationMasterTypes.compensatoryOff, // Compensatory Off
          userMasterID,
          status: 1,
        },
        include: [
          {
            model: AuthorizationCriteriaMaster,
            attributes: ['AuthorizationCriteria'],
          },
        ],
      },
      { transaction },
    );

    const authorizationStatus =
      authorizationdetails && authorizationdetails.AuthorizationCriteriaMaster
        ? authorizationdetails.AuthorizationCriteriaMaster
            .AuthorizationCriteria == 'Sequeance No'
          ? 2
          : 1
        : 0;

    const emp_LeavePolicy = await empLeavePolicy.findOne({
      where: {
        userMasterID,
        status: 1,
        applicableDate: { [Sequelize.Op.lte]: new Date(date) },
        [Sequelize.Op.or]: [
          {
            endDate: { [Sequelize.Op.gte]: new Date(date) },
          },
          {
            endDate: { [Sequelize.Op.eq]: null },
          },
        ],
      },
    });

    let expiryDate = null;

    if (emp_LeavePolicy) {
      const coffPolicy = await employeeLeavePolicy.findOne({
        where: {
          id: emp_LeavePolicy.employeeLeavePolicyID,
          leaveId: 6,
        },
        attributes: ['expiryDays'],
      });

      if (coffPolicy?.expiryDays)
        expiryDate = getDateByAddingDays(date, coffPolicy?.expiryDays || 0);
    }

    const requestData = await coffMaster.create(
      {
        LeaveTranId: LeaveTranId,
        userMasterID: userMasterID,
        LeaveCreatedDate: date,
        YearMM: YearMM,
        LeaveAddNew: LeaveAddNew,
        authorizationStatus,
        expiryDate,
        createBy,
        createByIp,
      },
      { transaction },
    );

    if (authorizationStatus != 0) {
      // user Details
      const userDetails = await UserMaster.findOne({
        raw: true,
        where: {
          userMasterID,
        },
      });

      if (!userDetails) throw new Error('User not found!');

      // For Sequence No
      if (authorizationStatus == 2) {
        const authorizationData = await CompensatoryOffAuthorization.create(
          {
            TableName: 'Compensatory Off',
            coffMasterID: requestData.coffMasterID,
            userMasterID: authorizationdetails.AuthorizedByUserMasterId[0],
            authstatus: 2,
            createBy,
            createByIp,
          },
          { hooks: false, transaction },
        );

        // Create UserInbox
        await UserInbox.create(
          {
            activityTable: CompensatoryOffAuthorization.getTableName(),
            activityTablePK:
              authorizationData.toJSON().CompensatoryOffAuthorizationID,
            message: `${
              userDetails.displayName
            } has requested a Compensatory Off for ${moment(date).format(
              'DD/MM/YYYY',
            )}.`,
            assignedTo: authorizationdetails.AuthorizedByUserMasterId[0],
            assignedBy: userMasterID,
            createBy,
            createByIp,
          },
          { transaction },
        );

        const notification = {
          title: 'Compensatory Off',
          body: userDetails.displayName + ' requested for a Compensatory Off.',
        };
        const data = {
          screen: 'coffauth',
          isScheduled: 'true',
          scheduledTime: new Date().toISOString(),
        };

        // send Notification
        await sendNotification(
          authorizationData.userMasterID,
          notification,
          data,
        );
      } else {
        // For Any
        for (
          let j = 0;
          j < authorizationdetails.AuthorizedByUserMasterId.length;
          j++
        ) {
          const authorizationData = await CompensatoryOffAuthorization.create(
            {
              TableName: 'Compensatory Off',
              coffMasterID: requestData.coffMasterID,
              userMasterID: authorizationdetails.AuthorizedByUserMasterId[j],
              authstatus: 2,
              createBy,
              createByIp,
            },
            { hooks: false, transaction },
          );

          // Create UserInbox
          await UserInbox.create(
            {
              activityTable: CompensatoryOffAuthorization.getTableName(),
              activityTablePK:
                authorizationData.toJSON().CompensatoryOffAuthorizationID,
              message: `${
                userDetails.displayName
              } has requested a Compensatory Off for ${moment(date).format(
                'DD/MM/YYYY',
              )}.`,
              assignedTo: authorizationdetails.AuthorizedByUserMasterId[j],
              assignedBy: userMasterID,
              createBy,
              createByIp,
            },
            { transaction },
          );

          const notification = {
            title: 'Compensatory Off',
            body:
              userDetails.displayName + ' requested for a Compensatory Off.',
          };
          const data = {
            screen: 'coffauth',
            isScheduled: 'true',
            scheduledTime: new Date().toISOString(),
          };
          // send Notification
          await sendNotification(
            authorizationData.userMasterID,
            notification,
            data,
          );
        }
      }
    }

    await transaction.commit();
  } catch (err) {
    await transaction.rollback();
  }
}

