async function getDatesFromDateRange(from, to) {
  const dates = [];
  for (let date = from; date <= to; date.setDate(date.getDate() + 1)) {
    const cloned = new Date(date.valueOf());
    dates.push(cloned);
  }
  return dates;
}
function toHoursAndMinutes(totalMinutes) {
  const minutes = Number(totalMinutes ?? 0);

  const hours = Math.floor(minutes / 60);
  const remainingMinutes = minutes % 60;

  return (
    String(hours).padStart(2, '0') +
    ':' +
    String(remainingMinutes).padStart(2, '0')
  );
}

function toHoursAndMinutesNumber(totalMinutes) {
  const hours = Math.floor(totalMinutes / 60);
  const minutes = totalMinutes % 60;
  return hours + '.' + minutes;
}

const notification_options = {
  priority: 'high',
  timeToLive: 60 * 60 * 24,
};
async function sendNotification(
  id,
  notification = {},
  body = {},
  options = {},
) {
  try {
    const { isSilent = false } = options;

    let get_user = await UserMaster.findOne({
      raw: true,
      where: {
        userMasterID: id,
        status: 1,
      },
    });

    if (!get_user?.firebaseToken) return;

    const firebase_token = get_user.firebaseToken;

    // Common message structure
    const message_notification = {
      token: firebase_token,

      // Convert all data values to string (FCM requirement)
      data: Object.entries(body || {}).reduce((acc, [key, value]) => {
        acc[key] = String(value);
        return acc;
      }, {}),
    };

    // Add notification only if NOT silent
    if (!isSilent) {
      message_notification.notification = notification;
    }

    // iOS Configuration
    if (get_user.deviceType && get_user.deviceType.toLowerCase() === 'ios') {
      if (isSilent) {
        // Silent iOS notification
        message_notification.apns = {
          payload: {
            aps: {
              'content-available': 1,
            },
          },
          headers: {
            'apns-push-type': 'background',
            'apns-priority': '5',
            // 'apns-topic': 'YOUR_BUNDLE_ID', // optional if configured
          },
        };
      } else {
        // Normal iOS notification
        message_notification.apns = {
          payload: {
            aps: {
              alert: {
                title: notification.title,
                body: notification.body,
              },
              sound: 'default', // Enable sound for iOS notifications
              badge: 1, // Badge count for iOS
            },
          },
          headers: {
            'apns-priority': '10', // High priority for iOS
            'apns-expiration': (
              Math.floor(Date.now() / 1000) +
              60 * 60 * 24
            ).toString(), // Expiration for 24 hours as a string
          },
        };
      }
    } else {
      // Android-specific options
      message_notification.android = {
        priority: 'high', // High priority for Android
        ttl: 60 * 60 * 24 * 1000, // 24 hours in milliseconds for TTL
      };
    }

    // Send notification through the appropriate admin (iosFirebaseAdmin or androidFirebaseAdmin)
    const Notification_ =
      get_user.deviceType && get_user.deviceType.toLowerCase() === 'ios'
        ? iosFirebaseAdmin
        : androidFirebaseAdmin;

    Notification_.messaging()
      .send(message_notification)
      .then((response) => {})
      .catch((error) => {});
  } catch (error) {}
}

function precedence(opr) {
  switch (opr) {
    case '+':
    case '-':
      return 1;
    case '*':
    case '/':
      return 2;
    default:
      return -1;
  }
}

async function isOperator(ch) {
  if (ch == '+' || ch == '-' || ch == '*' || ch == '/') {
    return true;
  } else {
    return false;
  }
}

function infixtopostfix(formula, grade_salary_structure_data) {
  let str = '';
  let stack = [];
  let postfix = '';
  let top = -1;

  for (let i = 0; i < formula.length; i++) {
    let ch = formula.charAt(i);
    str = '';
    if (
      ch == '(' ||
      ch == ')' ||
      ch == '+' ||
      ch == '-' ||
      ch == '*' ||
      ch == '/'
    ) {
      str = ch;
      if (str == '(') {
        top++;
        stack.push(str);
      } else if (str == ')') {
        while (top > -1 && stack[top] != '(') {
          postfix = postfix + stack[top] + ',';
          stack.pop();
          top--;
        }
        stack.pop();
        top--;
      } else {
        let x = precedence(stack[top]);
        let y = precedence(str);

        while (top > -1 && x >= y) {
          postfix = postfix + stack[top] + ',';
          top--;
          stack.pop();
          x = precedence(stack[top]);
          y = precedence(str);
        }
        top++;
        stack.push(str);
      }
    } else {
      for (let j = i; j < formula.length; j++, i++) {
        ch = formula.charAt(j);
        if (
          ch == '(' ||
          ch == ')' ||
          ch == '+' ||
          ch == '-' ||
          ch == '*' ||
          ch == '/'
        ) {
          i--;
          break;
        } else {
          str = str + ch;
        }
      }
      postfix = postfix + str + ',';
    }
  }

  while (top > -1) {
    postfix = postfix + stack[top] + ',';
    stack.pop();
    top--;
  }

  return formulaCalculation(postfix, grade_salary_structure_data);
}

function isNumeric(str) {
  if (typeof str != 'string') return false; // we only process strings!
  return (
    !isNaN(str) && // use type coercion to parse the _entirety_ of the string (`parseFloat` alone does not do this)...
    !isNaN(parseFloat(str))
  ); // ...and ensure strings of whitespace fail
}

