async function getAllUserByCompany(companyMasterID, status, page, limit) {
  const condition = {
    companyMasterId: companyMasterID,
    status: status,
  };

  const paginateCondition = {};
  if (page && limit) {
    paginateCondition.offset = (page - 1) * limit;
    paginateCondition.limit = limit;
  }

  const companyUser = await UserMaster.findAndCountAll({
    where: condition,
    ...paginateCondition,
  });
  return companyUser;
}

async function getAllUserByCompanyDateWise(companyMasterID, page, limit, date) {
  if (!date) {
    date = new Date().toISOString().slice(0, 10);
  }

  const condition = {
    joiningDate: {
      [Sequelize.Op.lte]: date,
    },
    [Sequelize.Op.or]: [
      {
        leavingDate: { [Sequelize.Op.gte]: date },
      },
      {
        leavingDate: { [Sequelize.Op.eq]: null },
        [Sequelize.Op.or]: [
          {
            '$userMaster.deactiveDate$': { [Sequelize.Op.gte]: date },
          },
          {
            '$userMaster.deactiveDate$': { [Sequelize.Op.eq]: null },
          },
        ],
      },
    ],
    '$userMaster.companyMasterId$': companyMasterID,
    '$userMaster.status$': [0, 1],
  };

  const paginateCondition = {};
  if (page && limit) {
    paginateCondition.offset = (page - 1) * limit;
    paginateCondition.limit = limit;
  }

  const companyUser = await EmployeeJoiningDetails.findAndCountAll({
    raw: true,
    where: condition,
    ...paginateCondition,
    include: [{ model: UserMaster }],
    order: [[{ model: UserMaster }, 'displayName', 'ASC']],
  });
  return companyUser;
}

async function getAllUserByBranchDateWise(branchMasterID, page, limit, date) {
  if (!date) {
    date = new Date().toISOString().slice(0, 10);
  }

  const condition = {
    branchID: branchMasterID,
    applicableDate: {
      [Sequelize.Op.lte]: new Date(date),
    },
    [Sequelize.Op.or]: [
      {
        endDate: {
          [Sequelize.Op.gte]: new Date(date),
        },
      },
      {
        endDate: null,
      },
    ],
    status: 1,
  };

  const get_branch_users = await EmployeeBranch.findAndCountAll({
    raw: true,
    where: condition,
  });
  let allActiveUsersID = [];
  for (let userID of get_branch_users.rows) {
    allActiveUsersID.push(userID.userMasterID);
  }

  const condition1 = {
    joiningDate: {
      [Sequelize.Op.lte]: new Date(date),
    },
    [Sequelize.Op.or]: [
      {
        leavingDate: { [Sequelize.Op.gte]: new Date(date) },
      },
      {
        leavingDate: { [Sequelize.Op.eq]: null },
        [Sequelize.Op.or]: [
          {
            '$userMaster.deactiveDate$': { [Sequelize.Op.gte]: new Date(date) },
          },
          {
            '$userMaster.deactiveDate$': { [Sequelize.Op.eq]: null },
          },
        ],
      },
    ],
    userMasterID: allActiveUsersID,
    '$userMaster.status$': [0, 1],
  };

  const paginateCondition = {};

  if (page && limit) {
    paginateCondition.offset = (page - 1) * limit;
    paginateCondition.limit = limit;
  }

  const branchUser = await EmployeeJoiningDetails.findAndCountAll({
    raw: true,
    where: condition1,
    ...paginateCondition,
    include: [{ model: UserMaster }],
    order: [[{ model: UserMaster }, 'displayName', 'ASC']],
  });

  return branchUser;
}

