async function employeePendingLeaveBalance(
  userId,
  startdate,
  enddate,
  leaveTranId,
) {
  const condition = {
    userMasterID: userId,

    authorizationStatus: {
      [Sequelize.Op.notIn]: [3, 4],
    },
    status: 1,
  };

  if (leaveTranId) condition.LeaveTranId = leaveTranId;

  if (startdate && enddate) {
    condition[Op.or] = [
      {
        [Op.and]: {
          FromDate: { [Op.gte]: new Date(startdate) },
          FromDate: { [Op.lte]: new Date(enddate) },
        },
      },
      {
        [Op.and]: {
          ToDate: { [Op.gte]: new Date(startdate) },
          ToDate: { [Op.lte]: new Date(enddate) },
        },
      },
    ];
  } else if (enddate && !startdate) {
    condition[Op.or] = [
      { FromDate: { [Op.lte]: new Date(enddate) } },
      { ToDate: { [Op.lte]: new Date(enddate) } },
    ];
  } else if (!enddate && startdate) {
    condition[Op.or] = [
      { FromDate: { [Op.gte]: new Date(startdate) } },
      { ToDate: { [Op.gte]: new Date(startdate) } },
    ];
  }

  const pendingLeave = await UserLeave.findAll({
    raw: true,
    where: condition,
    include: [
      {
        model: HrLeaveTypes,
        attributes: [],
        where: {
          LeaveID: {
            [Sequelize.Op.notIn]: [5, 18],
          },
        },
        include: [{ model: HrLeaveMaster, as: 'LeaveMaster', attributes: [] }],
      },
    ],
    group: [
      'userMasterID',
      'hrLeaveType.LeaveTranId',
      'hrLeaveType.LeaveMaster.LeaveName',
    ],
    attributes: [
      [Sequelize.col('userMasterID'), 'userMasterID'],
      [Sequelize.col('hrLeaveType.LeaveMaster.LeaveName'), 'LeaveName'],
      [Sequelize.col('hrLeaveType.LeaveTranId'), 'LeaveTranId'],
      [
        Sequelize.literal('coalesce(sum(cast("LeaveDays" as numeric)),0)'),
        'totalDays',
      ],
    ],
  });

  return pendingLeave;
}

async function checkUserLeaveBalance(leavedata, type) {
  const { companyMasterID, userMasterID } = leavedata[0];
  let currentLeaveDays = 0;

  if (type === 'update') {
    const currentLeave = await UserLeave.findOne({
      raw: true,
      where: { UserLeaveApplicationID: leavedata[0].UserLeaveApplicationID },
    });
    currentLeaveDays = currentLeave ? +currentLeave.LeaveDays : 0;
  }

  // Get user leave balance once
  const userleaveBalance = await employeeeLeaveBalance(
    +companyMasterID,
    +userMasterID,
  );

  // Merge all leave days by TranId
  const leaveSum = leavedata.reduce((acc, { LeaveTranId, LeaveDays }) => {
    acc[LeaveTranId] = (acc[LeaveTranId] || 0) + LeaveDays;
    return acc;
  }, {});

  const mergedLeaves = Object.entries(leaveSum).map(
    ([LeaveTranId, LeaveDays]) => ({
      LeaveTranId: +LeaveTranId,
      LeaveDays,
    }),
  );

  const insufficient = [];
  const insufficientPending = [];
  const insufficientBackDatedCoff = [];

  // Process each leave
  for (const leave of mergedLeaves) {
    const balanceEntry = userleaveBalance.find(
      (f) => f.LeaveTranId === leave.LeaveTranId,
    );
    if (!balanceEntry) continue;

    let userBalance = +balanceEntry.Balance;
    let leaveDays = +leave.LeaveDays;

    // Normal leave pending balance
    const pending = await employeePendingLeaveBalance(
      +userMasterID,
      '',
      '',
      leave.LeaveTranId,
    );
    const pendingLeaveDays = pending?.[0]?.totalDays || 0;

    // Special handling for COFF (LeaveID = 6)
    if (balanceEntry.LeaveID == 6) {
      await checkCoffBalance(
        leavedata.filter((l) => l.LeaveTranId === leave.LeaveTranId),
        pendingLeaveDays,
        userMasterID,
        type,
        currentLeaveDays,
        balanceEntry.leaveName,
        insufficient,
        insufficientPending,
        insufficientBackDatedCoff,
      );
      continue;
    }

    // Check balance
    if (+userBalance < +leaveDays) {
      insufficient.push(balanceEntry.leaveName);
    } else if (
      type === 'add' &&
      +userBalance < +leaveDays + +pendingLeaveDays
    ) {
      insufficientPending.push(balanceEntry.leaveName);
    } else if (
      type === 'update' &&
      +userBalance < +leaveDays + +pendingLeaveDays - +currentLeaveDays
    ) {
      insufficientPending.push(balanceEntry.leaveName);
    }
  }

  if (insufficientBackDatedCoff.length > 0) {
    return `You don't have sufficient leave balance of COFF for the selected date.`;
  }

  if (insufficient.length > 0) {
    return `You don't have sufficient leave balance of ${insufficient[0]}.`;
  }

  if (insufficientPending.length > 0) {
    return `You don't have sufficient leave balance of ${insufficientPending[0]}. It is already used in leaves which are in pending state.`;
  }

  return '';
}

// -------------- Separate COFF handler -----------------

async function checkCoffBalance(
  coffLeaves,
  pendingLeaveDays = 0,
  userMasterID,
  type,
  currentLeaveDays = 0,
  leaveName,
  insufficient,
  insufficientPending,
  insufficientBackDatedCoff,
) {
  let allBalanceData = [];

  let pendingUsed = false;

  // find coff leave Policy

  const date = moment().format('YYYY-MM-DD');

  const empleavePolicy = await empLeavePolicy.findOne({
    where: {
      userMasterID,
      applicableDate: {
        [Sequelize.Op.lte]: date,
      },
      [Sequelize.Op.or]: [
        {
          endDate: {
            [Sequelize.Op.gte]: date,
          },
        },
        {
          endDate: {
            [Sequelize.Op.is]: null,
          },
        },
      ],
      status: 1,
    },
  });

  let isbackDatedCoffAllowed = true;

  if (empleavePolicy) {
    const leavePolicyIds = empleavePolicy?.employeeLeavePolicyID || [];

    const leavePolicy = await EmployeeLeavePolicy.findOne({
      where: {
        leaveId: 6,
        id: {
          [Sequelize.Op.in]: leavePolicyIds,
        },
      },
      attributes: ['allowCoffBackdate'],
    });

    if (leavePolicy) {
      isbackDatedCoffAllowed = leavePolicy.allowCoffBackdate;
    }
  }

  // Loop through all COFF leave applications
  for (const e of coffLeaves) {
    const fromDate = new Date(e.FromDate);
    const toDate = new Date(e.ToDate);

    // Iterate through each date in the leave range
    for (let d = new Date(fromDate); d <= toDate; d.setDate(d.getDate() + 1)) {
      const dateStr = d.toISOString().split('T')[0];
      let leaveDays = e.LeaveDays >= 1 ? 1 : 0.5; // Full or half day leave

      // Use pending leave adjustment (only once per loop)
      if (!pendingUsed) {
        pendingUsed = true;
        leaveDays += +pendingLeaveDays - +currentLeaveDays;
      }

      // check coff balance process
      const {
        allBalanceData: allBalanceDataTemp,
        remaining,
        isBackDatedCoffReason,
      } = await checkCoffBalanceProcess(
        allBalanceData,
        userMasterID,
        dateStr,
        leaveDays,
        isbackDatedCoffAllowed,
      );

      // restore to allBalanceData
      allBalanceData = [...allBalanceDataTemp];

      // If leave still not covered
      if (+remaining > 0 && isBackDatedCoffReason) {
        insufficientBackDatedCoff.push(leaveName);
      } else if (+remaining > 0 && +pendingLeaveDays == 0) {
        insufficient.push(leaveName); // No balance at all
      } else if (
        ['add', 'update'].includes(type) &&
        +remaining > 0 &&
        +pendingLeaveDays > 0
      ) {
        insufficientPending.push(leaveName); // Not enough due to pending leaves
      }
    }
  }
}

// check coff balance process

async function checkCoffBalanceProcess(
  allBalanceData = [],
  userMasterID,
  balanceDate,
  leaveDays = 0,
  isbackDatedCoffAllowed = true,
) {
  // const usedTransactionLog = [];

  // Collect already known BalanceTranIds
  const ids = allBalanceData.map((e) => +e.LeaveBalTranId);

  // Fetch COFF balance data for the given date
  const balanceData = await getCoffBalanceData(userMasterID, balanceDate);

  // Add only new balance transactions (avoid duplicates)
  const notAddedData = balanceData.filter(
    (e) => !ids.includes(+e.LeaveBalTranId),
  );
  if (notAddedData) allBalanceData = [...allBalanceData, ...notAddedData];

  // Filter expired balances & sort balances by expiry (nulls last)
  allBalanceData = allBalanceData
    .filter(
      (e) => new Date(e.expiryDate) >= new Date(balanceDate) || !e.expiryDate,
    )
    .sort((a, b) => {
      const da = a.expiryDate ? new Date(a.expiryDate) : null;
      const db = b.expiryDate ? new Date(b.expiryDate) : null;
      if (!da && !db) return 0;
      if (!da) return 1; // null last
      if (!db) return -1; // null last
      const aCoff = a.coffCreatedDate
        ? new Date(a.coffCreatedDate).getTime()
        : Infinity;
      const bCoff = b.coffCreatedDate
        ? new Date(b.coffCreatedDate).getTime()
        : Infinity;
      return aCoff - bCoff; // ASC
    });

  let remaining = +leaveDays;

  // Consume leave balance from available transactions
  return consumeLeaveBalance(
    allBalanceData,
    remaining,
    balanceDate,
    CoffUsedTypeEnum.USED,
    isbackDatedCoffAllowed,
  );
}

// for coff
function consumeLeaveBalance(
  allBalanceData,
  remaining,
  balanceDate,
  type,
  isbackDatedCoffAllowed = true,
) {
  const usedTransactionLog = [];
  let isBackDatedCoffReason = false;

  for (let bal of allBalanceData) {
    if (remaining <= 0) break; // stop if leave fully covered

    if (bal.availBal > 0) {
      // continue if backdated coff is not allowed
      if (
        isbackDatedCoffAllowed == false &&
        bal.coffCreatedDate >= balanceDate
      ) {
        isBackDatedCoffReason = true;
        continue;
      }

      // Consume minimum of available balance or required leave
      let consume = Math.min(bal.availBal, remaining);

      // Ensure fixed precision if fractional
      consume = consume % 1 !== 0 ? +consume.toFixed(2) : consume;

      if (consume > 0) {
        bal.availBal -= consume;
        remaining -= consume;

        // Round off available balance if fractional
        bal.availBal =
          bal.availBal % 1 !== 0 ? +bal.availBal.toFixed(2) : bal.availBal;

        // Log the transaction
        usedTransactionLog.push({
          LeaveBalTranId: bal.LeaveBalTranId,
          date: balanceDate,
          days: consume,
          type,
        });
      }
    }
  }

  return {
    remaining,
    allBalanceData,
    usedTransactionLog,
    isBackDatedCoffReason,
  };
}

function asiaKolkataDateTime(date) {
  if ([envType.STAGE].includes(process.env.NODE_ENV)) {
    if (date) return new Date(date).toISOString().slice(0, 10);
    return new Date().toISOString().slice(0, 10);
  } else {
    if (date) {
      const options = {
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
        hour: 'numeric',
        minute: 'numeric',
        second: 'numeric',
        timeZone: 'Asia/Kolkata',
      };
      return new Date(date)
        .toLocaleString(undefined, options)
        .replace(
          /([0-9]+)\/([0-9]+)\/([0-9]+), ([0-9]+):([0-9]+):([0-9]+) ([APapMm]{2})/,
          '$3-$1-$2, $4:$5:$6 $7',
        );
    } else {
      return '';
    }
  }
}

