function isInFinancialYear(dateRangeStart, dateRangeEnd) {
  const startDate = new Date(dateRangeStart);
  const endDate = new Date(dateRangeEnd);
  // Extract year from start date
  let startYear = startDate.getFullYear();
  // Determine the financial year based on the start date

  if (startDate.getMonth() < 3) startYear--;

  const financialStartDate = new Date(
    moment(`${startYear}-04-01`).format('YYYY-MM-DD'),
  );
  const financialEndDate = new Date(
    moment(`${startYear + 1}-03-31`).format('YYYY-MM-DD'),
  );

  // Check if the end date falls within the financial year
  return endDate >= financialStartDate && endDate <= financialEndDate;
}

const isInCalendarYear = (startDate, endDate) => {
  const startYear = new Date(startDate).getFullYear();
  const endYear = new Date(endDate).getFullYear();

  // const startYear = startDate.getFullYear();
  // const endYear = endDate.getFullYear();

  return startYear === endYear;
};

async function addAsopalavBreakTime(trans, continueIN) {
  if (!trans.lunchBreak) {
    const diff =
      (new Date(continueIN).getTime() - new Date(trans.OutDateTime).getTime()) /
      60 /
      1000;
    const LunchBreak = {
      diff: Math.round(diff),
      starttime: trans.OutDateTime,
      endtime: continueIN,
      type: 'lunchBreak',
    };

    return LunchBreak;
  } else if (!trans.teaBreak) {
    const diff =
      (new Date(continueIN).getTime() - new Date(trans.OutDateTime).getTime()) /
      60 /
      1000;
    const TeaBreak = {
      diff: Math.round(diff),
      starttime: trans.OutDateTime,
      endtime: continueIN,
      type: 'teaBreak',
    };

    return TeaBreak;
  } else {
    const EmptyBreak = {
      diff: null,
      starttime: null,
      endtime: null,
      type: null,
    };
    return EmptyBreak;
  }
}

async function getAsopalavBreakTime_Manual(trans, continueIN, LastOutLog) {
  if (!trans.lunchBreak) {
    const diff =
      (new Date(continueIN).getTime() - new Date(LastOutLog).getTime()) /
      60 /
      1000;
    const LunchBreak = {
      diff: Math.round(diff),
      starttime: LastOutLog,
      endtime: continueIN,
      type: 'lunchBreak',
    };

    return LunchBreak;
  } else if (!trans.teaBreak) {
    const diff =
      (new Date(continueIN).getTime() - new Date(LastOutLog).getTime()) /
      60 /
      1000;
    const TeaBreak = {
      diff: Math.round(diff),
      starttime: LastOutLog,
      endtime: continueIN,
      type: 'teaBreak',
    };

    return TeaBreak;
  } else {
    const EmptyBreak = {
      diff: null,
      starttime: null,
      endtime: null,
      type: null,
    };
    return EmptyBreak;
  }
}

async function addAsopalavBreakTimePenalty(userid, date, penaltyID) {
  const findPenalty = await Penalty.findOne({
    raw: true,
    where: {
      penaltyID: penaltyID,
    },
  });

  if (!findPenalty) return;

  const findUserPenalty = await EmployeePenalties.findOne({
    where: {
      userMasterID: userid,
      penaltyDate: date,
      penaltyID: penaltyID,
    },
  });

  if (findUserPenalty) return;

  await EmployeePenalties.create({
    userMasterID: userid,
    penaltyID: penaltyID,
    penaltyAmount: findPenalty.penaltyAmount,
    description: findPenalty.penaltyName,
    createBy: userid,
    penaltyDate: date,
  });
}

async function addAsopalavBreakTimePenalty_Manual(
  findPenalty,
  userid,
  date,
  penaltyID,
  transaction,
) {
  const findUserPenalty = await EmployeePenalties.findOne({
    where: {
      userMasterID: userid,
      penaltyDate: date,
      penaltyID: penaltyID,
    },
    transaction,
  });

  if (findUserPenalty) return;

  await EmployeePenalties.create(
    {
      userMasterID: userid,
      penaltyID: penaltyID,
      penaltyAmount: findPenalty.penaltyAmount,
      description: findPenalty.penaltyName,
      createBy: userid,
      penaltyDate: date,
    },
    { transaction },
  );
}

async function getLeave(userMasterID, date) {
  const approvedLeave = await executeQuery(
    `SELECT hlm."LeaveName",hlm."LeaveID" from "userLeaves" as ul INNER join "userLeaveTransactions" as ult on ul."UserLeaveApplicationID"=ult."ReferenceID" INNER join "hrLeaveTypes" as hlt on ult."LeaveTranId"=hlt."LeaveTranId" inner join "hrLeaveMasters" as hlm on hlm."LeaveID"=hlt."LeaveID" WHERE ul."authorizationStatus" not in (4) and ul."status"=1 and ul."userMasterID"=` +
      ':userMasterID' +
      ` and ult."status"=1 and (ult."date" >= :FromDate AND ult."date" <= :ToDate)`,
    {
      replacements: {
        userMasterID: userMasterID,
        FromDate: date,
        ToDate: date,
      },
    },
  );

  if (approvedLeave.length > 0) {
    if (approvedLeave[0].LeaveID == 18) {
      return 'L.W.P';
    } else {
      return approvedLeave[0].LeaveName;
    }
  } else {
    const findLeave = await UserLeave.findOne({
      raw: true,
      where: {
        status: 1,
        userMasterID: userMasterID,
        [Sequelize.Op.or]: [
          {
            FromDate: {
              [Sequelize.Op.between]: [date, date],
            },
          },
          {
            ToDate: {
              [Sequelize.Op.between]: [date, date],
            },
          },
          {
            FromDate: {
              [Sequelize.Op.lte]: date,
            },
            ToDate: {
              [Sequelize.Op.gte]: date,
            },
          },
        ],
        authorizationStatus: [0, 1, 2],
      },
    });

    if (findLeave) {
      return 'Leave';
    } else {
      return null;
    }
  }
}

async function getUserSalaryMasterByMonth(
  id,
  month,
  payrollFrequency = PayrollFrequencyType.MONTHLY,
  startDate = null,
  endDate = null,
) {
  let salaryMasterdata = [];

  let selectMax = 'hsm."salaryFromYYYYMM"';
  let compare = month;

  if (
    [PayrollFrequencyType.FORTNIGHTLY, PayrollFrequencyType.WEEKLY].includes(
      payrollFrequency,
    )
  ) {
    selectMax = 'hsm."startDate"';
    compare = `'${startDate}'`;
  }

  const gradestructure = await executeQuery(
    `   
        select gss."gradeStructureID",hsm."endDate", MAX(${selectMax}) from "hrSalaryMasters" as hsm left OUTER join "gradeSalaryStructures" as gss on hsm."gradeSalaryStructureID" = gss."gradeSalaryStructureID" where hsm."userMasterID"=` +
      ':userMasterID' +
      ` and ${selectMax} <=` +
      compare +
      ` GROUP BY gss."gradeStructureID",hsm."endDate",${selectMax} ORDER by ${selectMax} DESC limit 1 
        
        `,
    {
      replacements: {
        userMasterID: id,
      },
    },
  );

  if (gradestructure.length > 0) {
    const condition = {
      userMasterID: id,
      payrollFrequency,
      '$gradeSalaryStructure.hrSalaryField.payheadMasterId$': {
        [Sequelize.Op.notIn]: [
          16, 17, 9, 24, 34, 43, 78, 83, 96, 97, 99, 67, 101, 102, 103, 104,
          107, 112, 135, 123, 125, 126, 127, 133, 130, 122, 147, 116, 148, 151,
          152,
        ],
      },
    };

    if (
      [PayrollFrequencyType.FORTNIGHTLY, PayrollFrequencyType.WEEKLY].includes(
        payrollFrequency,
      )
    ) {
      Object.assign(condition, {
        startDate: gradestructure[0].max,
        endDate: gradestructure[0].endDate,
      });
    } else {
      condition.salaryFromYYYYMM = gradestructure[0].max;
    }

    salaryMasterdata = await HRSalaryMaster.findAll({
      raw: true,
      where: condition,
      include: [
        {
          model: GradeSalaryStructure,
          include: [
            { model: GradeStructure, attributes: [] },
            {
              model: HRSalaryFields,
              include: [
                {
                  model: Payheadmaster,

                  attributes: [],
                },
              ],
              attributes: [],
            },
          ],
          attributes: [],
          order: [
            // Order by salaryfieldindex in GradeSalaryStructure
            ['salaryfieldindex', 'ASC'],

            // Order by payheadName in Payheadmaster
            [
              { model: HRSalaryFields, model: Payheadmaster },
              'payheadName',
              'ASC',
            ],
          ],
        },
      ],
      attributes: [
        [
          Sequelize.col(
            'gradeSalaryStructure.hrSalaryField.Payheadmaster.payheadName',
          ),
          'payheadName',
        ],
        [
          Sequelize.col(
            'gradeSalaryStructure.hrSalaryField.payheadDisplayName',
          ),
          'payheadDisplayName',
        ],
        [
          Sequelize.col('gradeSalaryStructure.hrSalaryField.payheadMasterId'),
          'payheadMasterId',
        ],
        'EmployeeSalaryAmount',
        'salaryFromYYYYMM',
        'userMasterID',
        'salaryMasterID',
        'createBy',
        'stateid',
        'corporationId',
        'skillCategory',
        'gradeSalaryStructureID',
        'AmountIn',
        'ActualEmployeeSalaryAmount',
        'payrollFrequency',
        'startDate',
        'endDate',
        [
          Sequelize.col(
            'gradeSalaryStructure.gradeStructure.baseOnCalculation',
          ),
          'baseOnCalculation',
        ],
        [
          Sequelize.col('gradeSalaryStructure.gradeStructure.gradeName'),
          'gradeName',
        ],
        [Sequelize.col('gradeSalaryStructure.formula'), 'formula'],
        [Sequelize.col('gradeSalaryStructure.formula1'), 'formula1'],
        [
          Sequelize.col('gradeSalaryStructure.fieldFixAmount'),
          'fieldFixAmount',
        ],
        [
          Sequelize.col('gradeSalaryStructure.fieldFixAmount1'),
          'fieldFixAmount1',
        ],
        [
          Sequelize.col('gradeSalaryStructure.formulaPreference'),
          'formulaPreference',
        ],
        [
          Sequelize.col('gradeSalaryStructure.gradeStructureID'),
          'gradeStructureID',
        ],
        [
          Sequelize.col('gradeSalaryStructure.hrSalaryField.salaryFieldSrNo'),
          'salaryFieldSrNo',
        ],
        [
          Sequelize.col(
            'gradeSalaryStructure.hrSalaryField.salaryFieldWhenMonth',
          ),
          'salaryFieldWhenMonth',
        ],
        [
          Sequelize.col('gradeSalaryStructure.hrSalaryField.salaryFieldSide'),
          'salaryFieldSide',
        ],
        [
          Sequelize.col('gradeSalaryStructure.hrSalaryField.salaryFieldShow'),
          'salaryFieldShow',
        ],
        [
          Sequelize.col('gradeSalaryStructure.hrSalaryField.considerIn'),
          'considerIn',
        ],
        [
          Sequelize.col('gradeSalaryStructure.hrSalaryField.assignSalaryRound'),
          'assignSalaryRound',
        ],
        [
          Sequelize.col(
            'gradeSalaryStructure.hrSalaryField.assignSalaryRoundNo',
          ),
          'assignSalaryRoundNo',
        ],
        [
          Sequelize.col(
            'gradeSalaryStructure.hrSalaryField.assignSalaryRoundOffType',
          ),
          'assignSalaryRoundOffType',
        ],
      ],
    });
  }

  return salaryMasterdata;
}

async function getSalaryData(userId, month) {
  const salarydata = await HRSalaryTrasaction.findAll({
    raw: true,
    where: {
      userMasterID: userId,
      salaryYYYYMM: month,
    },
    include: [
      {
        model: HRSalaryMaster,
        include: [
          {
            model: GradeSalaryStructure,
            include: [
              { model: GradeStructure, attributes: [] },
              {
                model: HRSalaryFields,
                include: [
                  {
                    model: Payheadmaster,
                    attributes: [],
                  },
                ],
                attributes: [],
              },
            ],
            attributes: [],
          },
        ],
        attributes: [],
      },
      {
        model: UserMaster,
        as: 'createByUser',
        attributes: ['displayName'],
      },
    ],

    attributes: [
      [
        Sequelize.col(
          'hrSalaryMaster.gradeSalaryStructure.hrSalaryField.payheadMasterId',
        ),
        'payheadMasterId',
      ],
      [
        Sequelize.col(
          'hrSalaryMaster.gradeSalaryStructure.hrSalaryField.Payheadmaster.payheadName',
        ),
        'payheadName',
      ],
      [
        Sequelize.col(
          'hrSalaryMaster.gradeSalaryStructure.hrSalaryField.payheadDisplayName',
        ),
        'payheadDisplayName',
      ],
      [Sequelize.col('hrSalaryMaster.EmployeeSalaryAmount'), 'actualAmount'],
      'EmployeeSalaryAmount',
      'salaryYYYYMM',
      'userMasterID',
      'SalaryCalcOnDays',
      'createBy',
      'calculatedOn',
      'createdAt',
      [Sequelize.col('createByUser.displayName'), 'createByUserName'],
      [
        Sequelize.col(
          'hrSalaryMaster.gradeSalaryStructure.gradeStructure.baseOnCalculation',
        ),
        'baseOnCalculation',
      ],
      [Sequelize.col('hrSalaryMaster.gradeSalaryStructure.formula'), 'formula'],
      [
        Sequelize.col(
          'hrSalaryMaster.gradeSalaryStructure.hrSalaryField.salaryFieldSrNo',
        ),
        'salaryFieldSrNo',
      ],
      [
        Sequelize.col(
          'hrSalaryMaster.gradeSalaryStructure.hrSalaryField.salaryFieldSide',
        ),
        'salaryFieldSide',
      ],
      [
        Sequelize.col(
          'hrSalaryMaster.gradeSalaryStructure.hrSalaryField.considerIn',
        ),
        'considerIn',
      ],
    ],

    order: [
      // Order by salaryfieldindex in GradeSalaryStructure
      [
        { model: HRSalaryMaster, as: 'hrSalaryMaster' },
        { model: GradeSalaryStructure, as: 'gradeSalaryStructure' },
        'salaryfieldindex',
        'ASC',
      ],

      // Order by payheadName in Payheadmaster
      [
        { model: HRSalaryMaster, as: 'hrSalaryMaster' },
        { model: GradeSalaryStructure, as: 'gradeSalaryStructure' },
        { model: HRSalaryFields, as: 'hrSalaryField' },
        { model: Payheadmaster, as: 'Payheadmaster' },
        'payheadName',
        'ASC',
      ],
    ],
  });

  const depositCondition = {
    userMasterID: userId,
    status: 1,
    [Sequelize.Op.or]: [
      {
        salaryMonth: month,
        ReferenceId: {
          [Sequelize.Op.not]: null,
        },
      },
      {
        salaryMonthToPay: month,
        payReferenceId: {
          [Sequelize.Op.not]: null,
        },
      },
    ],
  };

  const depositData = await deposit.findAll({
    where: depositCondition,
    include: [{ model: depositcategory, attributes: ['depositcategoryname'] }],
  });

  let startdate =
    month.toString().slice(0, 4) +
    '-' +
    month.toString().slice(4, 6) +
    '-' +
    '01';
  let enddate =
    month.toString().slice(0, 4) +
    '-' +
    month.toString().slice(4, 6) +
    '-' +
    daysInMonth(month.toString().slice(4, 6), month.toString().slice(0, 4));

  const findDate = await HrLeaveMonthlyTrans.findOne({
    raw: true,
    where: {
      userMasterID: userId,
      AttnYearMon: month,
    },
  });

  if (findDate) {
    if (findDate.monthstartdate) startdate = findDate.monthstartdate;
    if (findDate.monthenddate) enddate = findDate.monthenddate;
  }

  let finaldata = [];

  const attendancePolicy = await employeeAttendancePolicy(userId, enddate);

  await Promise.all(
    salarydata.map(async (e) => {
      if (e.payheadMasterId == 24) {
        const incentive = await Employeeincentive.findAll({
          where: {
            userMasterID: userId,
            status: 1,
            incentiveDate: {
              [Sequelize.Op.between]: [startdate, enddate],
            },
            ReferenceId: {
              [Sequelize.Op.not]: null,
            },
          },
          include: [
            {
              model: Incentivetype,
              attributes: [
                'IncentivetypeID',
                'incentivetypename',
                'inc_type_displayName',
                'consider',
              ],
            },
            {
              model: ExtraDays,
              attributes: ['days'],
            },
          ],
          attributes: ['amount', 'IncentivetypeID', 'employeeincentiveID'],
        });

        // Group by IncentivetypeID
        const grouped = {};

        for (const inst of incentive) {
          const row = inst.get({ plain: true });
          const type = row.incentivetype || {};
          const key = +row.IncentivetypeID;

          if (!grouped[key]) {
            grouped[key] = {
              IncentivetypeID: key,
              // display name if present (and not blank), else the type name
              name:
                (type.inc_type_displayName || '').trim() ||
                type.incentivetypename,
              consider: type.consider,
              totalAmount: 0,
              totalExtraDays: 0,
            };
          }

          grouped[key].totalAmount += Number(row.amount) || 0;

          grouped[key].totalExtraDays += (row.extraDays || []).reduce(
            (s, e) => s + (Number(e.days) || 0),
            0,
          );
        }

        const result = Object.values(grouped).map((r) => ({
          ...r,
          totalAmount: Math.round(r.totalAmount * 100) / 100,
        }));

        result.forEach((data) => {
          finaldata.push({
            payheadMasterId: e.payheadMasterId,
            payheadName: data.name,
            actualAmount: e.actualAmount,
            EmployeeSalaryAmount: data.totalAmount,
            totalExtraDays: data.totalExtraDays,
            salaryYYYYMM: e.salaryYYYYMM,
            userMasterID: e.userMasterID,
            baseOnCalculation: e.baseOnCalculation,
            formula: e.formula,
            salaryFieldSrNo: e.salaryFieldSrNo,
            salaryFieldSide: e.salaryFieldSide,
            consider: data.consider,
          });
        });
      } else if (e.payheadMasterId == 34) {
        const penaltydata = await EmployeePenalties.findAll({
          raw: true,
          where: {
            userMasterID: userId,
            status: 1,
            penaltyDate: {
              [Sequelize.Op.between]: [startdate, enddate],
            },
            RefrenceId: {
              [Sequelize.Op.not]: null,
            },
          },
          group: ['penalty.penaltyID', 'penalty.penaltyName'],
          include: [
            {
              model: Penalty,
              as: 'penalty',
              // where: { deductionFromSalary: true },
              attributes: [],
            },
          ],
          attributes: [
            [Sequelize.col('penalty.penaltyID'), 'penaltyID'],
            [
              Sequelize.literal(
                `coalesce(sum(NULLIF("employeePenalty"."penaltyAmount", null)), 0)`,
              ),
              'amount',
            ],
            [Sequelize.col('penalty.penaltyName'), 'penaltyName'],
          ],
        });

        penaltydata.map((data) => {
          finaldata.push({
            payheadMasterId: e.payheadMasterId,
            payheadName: data.penaltyName,
            actualAmount: e.actualAmount,
            EmployeeSalaryAmount: Math.round(data.amount),
            salaryYYYYMM: e.salaryYYYYMM,
            userMasterID: e.userMasterID,
            baseOnCalculation: e.baseOnCalculation,
            formula: e.formula,
            salaryFieldSrNo: e.salaryFieldSrNo,
            salaryFieldSide: e.salaryFieldSide,
          });
        });
      } else if (e.payheadMasterId == 43) {
        if (attendancePolicy && +e.EmployeeSalaryAmount > 0) {
          finaldata.push({ ...e, consider: attendancePolicy.consider });
        }
      } else if (e.payheadMasterId == 96) {
        const depositToDeduction = depositData.length
          ? [...depositData].filter(
              (e) => e.depositReceiveAs == 'salary' && e.salaryMonth == month,
            )
          : [];
        const result = Object.values(
          depositToDeduction.reduce((acc, curr) => {
            if (!acc[curr.depositcategory.depositcategoryname]) {
              acc[curr.depositcategory.depositcategoryname] = {
                payheadMasterId: e.payheadMasterId,
                payheadDisplayName: '',
                payheadName: curr.depositcategory.depositcategoryname,
                actualAmount: 0,
                EmployeeSalaryAmount: 0,
                salaryYYYYMM: e.salaryYYYYMM,
                userMasterID: e.userMasterID,
                baseOnCalculation: e.baseOnCalculation,
                formula: e.formula,
                salaryFieldSrNo: e.salaryFieldSrNo,
                salaryFieldSide: e.salaryFieldSide,
              };
            }
            acc[
              curr.depositcategory.depositcategoryname
            ].EmployeeSalaryAmount += curr.amount; // Sum the amount
            return acc;
          }, {}),
        );
        finaldata = [...finaldata, ...result];
      } else if (e.payheadMasterId == 97) {
        const depositToPay = depositData.length
          ? [...depositData].filter((e) => e.salaryMonthToPay == month)
          : [];
        const result = Object.values(
          depositToPay.reduce((acc, curr) => {
            if (!acc[curr.depositcategory.depositcategoryname]) {
              acc[curr.depositcategory.depositcategoryname] = {
                payheadMasterId: e.payheadMasterId,
                payheadDisplayName: '',
                payheadName: curr.depositcategory.depositcategoryname,
                actualAmount: 0,
                EmployeeSalaryAmount: 0,
                salaryYYYYMM: e.salaryYYYYMM,
                userMasterID: e.userMasterID,
                baseOnCalculation: e.baseOnCalculation,
                formula: e.formula,
                salaryFieldSrNo: e.salaryFieldSrNo,
                salaryFieldSide: e.salaryFieldSide,
                considerIn: e.considerIn,
              };
            }
            acc[
              curr.depositcategory.depositcategoryname
            ].EmployeeSalaryAmount += curr.amount; // Sum the amount
            return acc;
          }, {}),
        );
        finaldata = [...finaldata, ...result];
      } else if (e.payheadMasterId == 67) {
        if (+e.EmployeeSalaryAmount > 0) {
          finaldata.push({ ...e });
        }
      } else if (
        [101, 102, 103, 104, 147, 116, 148, 151].includes(+e.payheadMasterId)
      ) {
        if (+e.EmployeeSalaryAmount > 0) {
          finaldata.push({ ...e });
        }
      } else {
        // for Gratuity
        if (e.payheadMasterId == 83) {
          if (+e.EmployeeSalaryAmount > 0) finaldata.push(e);
        } else {
          finaldata.push(e);
        }
      }
    }),
  );

  return finaldata;
}

async function getSalaryDataPNG(
  userId,
  month,
  payrollFrequency,
  payrollStartDate,
  payrollEndDate,
  attendancePolicy,
) {
  const condition = { userMasterID: userId, payrollFrequency };

  if (payrollFrequency == PayrollFrequencyType.MONTHLY) {
    condition.salaryYYYYMM = month;
  } else {
    condition.startDate = payrollStartDate;
    condition.endDate = payrollEndDate;
  }

  const salarydata = await HRSalaryTrasaction.findAll({
    where: condition,
    include: [
      {
        model: HRSalaryMaster,
        as: 'HSM',
        include: [
          {
            model: GradeSalaryStructure,
            as: 'GSS',
            include: [
              { model: GradeStructure },
              {
                model: HRSalaryFields,
                as: 'HSF',
                include: [
                  {
                    model: Payheadmaster,
                    as: 'PHM',
                  },
                ],
              },
            ],
          },
        ],
      },
      {
        model: UserMaster,
        as: 'createByUser',
        attributes: ['displayName'],
      },
      {
        required: false,
        model: EmployeePenalty,
        include: [
          { model: Penalty, as: 'penalty', attributes: ['penaltyName'] },
        ],
      },
      {
        required: false,
        model: Employeeincentive,
        include: [
          {
            model: Incentivetype,
            as: 'IncType',
            attributes: [
              ['incentivetypename', 'name'],
              ['inc_type_displayName', 'displayName'],
              ['IncentivetypeID', 'id'],
              'consider',
            ],
          },
        ],
      },
      {
        required: false,
        model: LeaveEncashment,
        attributes: ['LeaveTranId', 'days'],
        include: [
          {
            required: false,
            model: HrLeaveTypes,
            // where: {
            //   LeaveID: {
            //     [Sequelize.Op.ne]: HrLeaveTypesIds.LONG_SERVICE_LEAVE,
            //   },
            // },
            attributes: [],
          },
        ],
      },
      {
        model: Designation,
        as: 'designation',
        attributes: ['designationName'],
      },
      {
        model: Department,
        as: 'department',
        attributes: ['departmentName'],
      },
      {
        model: BranchMaster,
        as: 'branchMaster',
        attributes: ['branchName', 'branchAddress'],
      },
    ],

    order: [
      // Order by salaryfieldindex in GradeSalaryStructure
      [
        { model: HRSalaryMaster, as: 'HSM' },
        { model: GradeSalaryStructure, as: 'GSS' },
        'salaryfieldindex',
        'ASC',
      ],

      // Order by payheadName in Payheadmaster
      [
        { model: HRSalaryMaster, as: 'HSM' },
        { model: GradeSalaryStructure, as: 'GSS' },
        { model: HRSalaryFields, as: 'HSF' },
        { model: Payheadmaster, as: 'PHM' },
        'payheadName',
        'ASC',
      ],
    ],
  });

  const depositData =
    payrollFrequency == PayrollFrequencyType.MONTHLY
      ? await deposit.findAll({
          where: {
            depositReceiveAs: 'salary',
            salaryMonth: month,
            ReferenceId: {
              [Sequelize.Op.not]: null,
            },
            userMasterID: userId,
            status: 1,
          },
          include: [
            { model: depositcategory, attributes: ['depositcategoryname'] },
          ],
        })
      : [];

  let finaldata = [];

  await Promise.all(
    salarydata.map(async (e) => {
      const payheadMasterId = e.HSM?.GSS?.HSF?.payheadMasterId;

      const obj = {
        payheadMasterId,
        payheadName: e.HSM?.GSS?.HSF?.PHM?.payheadName,
        payheadDisplayName: e.HSM?.GSS?.HSF?.payheadDisplayName,
        actualAmount: e.HSM?.EmployeeSalaryAmount,
        EmployeeSalaryAmount: e.EmployeeSalaryAmount,
        salaryYYYYMM: e.salaryYYYYMM,
        userMasterID: e.userMasterID,
        SalaryCalcOnDays: e.SalaryCalcOnDays,
        createBy: e.createBy,
        calculatedOn: e.calculatedOn,
        createByUserName: e.createByUser.displayName,
        baseOnCalculation: e.HSM?.GSS?.gradeStructure?.baseOnCalculation,
        formula: e.HSM?.GSS?.formula,
        salaryFieldSrNo: e.HSM?.GSS?.HSF?.salaryFieldSrNo,
        salaryFieldSide: e.HSM?.GSS?.HSF?.salaryFieldSide,
        considerIn: e.HSM?.GSS?.HSF?.considerIn,
        payrollFrequency: e.payrollFrequency,
        startDate: e.startDate,
        endDate: e.endDate,
        branch: e.branchMaster?.branchName || '',
        branchAddress: e.branchMaster?.branchAddress || '',
        department: e.department?.departmentName || '',
        designation: e.designation?.designationName || '',
        taxApplicability: e.HSM?.GSS?.HSF?.PHM?.taxApplicability || '',
        days: 0,
      };

      if (payheadMasterId == 24) {
        const incentive = Object.values(
          (e.employeeincentives || []).reduce((acc, curr) => {
            if (!acc[curr.IncentivetypeID]) {
              acc[curr.IncentivetypeID] = {
                IncentivetypeID: curr.IncentivetypeID,
                amount: curr.amount,
                name:
                  curr.IncType?.dataValues.displayName ||
                  curr.IncType?.dataValues.name,
                consider: curr.IncType?.consider,
              }; // Clone the object
            } else {
              acc[curr.IncentivetypeID].amount += curr.amount; // Sum the amount
            }
            return acc;
          }, {}),
        );

        incentive.forEach((data) => {
          finaldata.push({
            payheadMasterId: payheadMasterId,
            payheadName: data.name,
            actualAmount: e.HSM?.EmployeeSalaryAmount || 0,
            EmployeeSalaryAmount: data.amount,
            salaryYYYYMM: e.salaryYYYYMM,
            userMasterID: e.userMasterID,
            baseOnCalculation: e.HSM?.GSS?.gradeStructure?.baseOnCalculation,
            formula: e.HSM?.GSS?.formula,
            salaryFieldSrNo: e.HSM?.GSS?.HSF?.salaryFieldSrNo,
            salaryFieldSide: e.HSM?.GSS?.HSF?.salaryFieldSide,
            consider: data.consider,
            payrollFrequency: e.payrollFrequency,
            startDate: e.startDate,
            endDate: e.endDate,
            taxApplicability: e.HSM?.GSS?.HSF?.PHM?.taxApplicability || '',
          });
        });
      } else if (payheadMasterId == 34) {
        const penaltydata = Object.values(
          (e.employeePenalties || []).reduce((acc, curr) => {
            if (!acc[curr.penaltyID]) {
              acc[curr.penaltyID] = {
                penaltyID: curr.penaltyID,
                penaltyAmount: curr.penaltyAmount,
                penaltyName: curr.penalty?.penaltyName || '',
              }; // Clone the object
            } else {
              acc[curr.penaltyID].penaltyAmount += curr.penaltyAmount; // Sum the amount
            }
            return acc;
          }, {}),
        );

        penaltydata.map((data) => {
          finaldata.push({
            payheadMasterId: payheadMasterId,
            payheadName: data.penaltyName,
            actualAmount: e.HSM?.EmployeeSalaryAmount || 0,
            EmployeeSalaryAmount: data.penaltyAmount,
            salaryYYYYMM: e.salaryYYYYMM,
            userMasterID: e.userMasterID,
            baseOnCalculation: e.HSM?.GSS?.gradeStructure?.baseOnCalculation,
            formula: e.HSM?.GSS?.formula,
            salaryFieldSrNo: e.HSM?.GSS?.HSF?.salaryFieldSrNo,
            salaryFieldSide: e.HSM?.GSS?.HSF?.salaryFieldSide,
            payrollFrequency: e.payrollFrequency,
            startDate: e.startDate,
            endDate: e.endDate,
          });
        });
      } else if (payheadMasterId == 43) {
        if (attendancePolicy && +e.EmployeeSalaryAmount > 0) {
          finaldata.push({ ...obj, consider: attendancePolicy.consider });
        }
      } else if (payheadMasterId == 96) {
        const depositToDeduction = depositData.length
          ? [...depositData].filter(
              (d) => d.depositReceiveAs == 'salary' && d.salaryMonth == month,
            )
          : [];
        const result = Object.values(
          depositToDeduction.reduce((acc, curr) => {
            if (!acc[curr.depositcategory.depositcategoryname]) {
              acc[curr.depositcategory.depositcategoryname] = {
                payheadMasterId: payheadMasterId,
                payheadDisplayName: '',
                payheadName: curr.depositcategory.depositcategoryname,
                actualAmount: 0,
                EmployeeSalaryAmount: 0,
                salaryYYYYMM: e.salaryYYYYMM,
                userMasterID: e.userMasterID,
                baseOnCalculation: obj.baseOnCalculation,
                formula: obj.formula,
                salaryFieldSrNo: obj.salaryFieldSrNo,
                salaryFieldSide: obj.salaryFieldSide,
                payrollFrequency: e.payrollFrequency,
                startDate: e.startDate,
                endDate: e.endDate,
              };
            }
            acc[
              curr.depositcategory.depositcategoryname
            ].EmployeeSalaryAmount += curr.amount; // Sum the amount
            return acc;
          }, {}),
        );
        finaldata = [...finaldata, ...result];
      } else if (payheadMasterId == 97) {
        const depositToPay = depositData.length
          ? [...depositData].filter(
              (d) => d.depositPayAs == 'salary' && d.salaryMonthToPay == month,
            )
          : [];
        const result = Object.values(
          depositToPay.reduce((acc, curr) => {
            if (!acc[curr.depositcategory.depositcategoryname]) {
              acc[curr.depositcategory.depositcategoryname] = {
                payheadMasterId: e.payheadMasterId,
                payheadDisplayName: '',
                payheadName: curr.depositcategory.depositcategoryname,
                actualAmount: 0,
                EmployeeSalaryAmount: 0,
                salaryYYYYMM: e.salaryYYYYMM,
                userMasterID: e.userMasterID,
                baseOnCalculation: obj.baseOnCalculation,
                formula: obj.formula,
                salaryFieldSrNo: obj.salaryFieldSrNo,
                salaryFieldSide: obj.salaryFieldSide,
                considerIn: obj.considerIn,
                payrollFrequency: e.payrollFrequency,
                startDate: e.startDate,
                endDate: e.endDate,
              };
            }
            acc[
              curr.depositcategory.depositcategoryname
            ].EmployeeSalaryAmount += curr.amount; // Sum the amount
            return acc;
          }, {}),
        );
        finaldata = [...finaldata, ...result];
      } else if (
        [67, 101, 147, 116, 148, 151, 152].includes(+payheadMasterId)
      ) {
        if (+e.EmployeeSalaryAmount > 0) {
          if ([payheadMasterIdsMapping.LEAVE_ENCASHMENT,payheadMasterIdsMapping.LONG_SERVICE_LEAVE_PAY].includes(+payheadMasterId)) {
            const encashDays = (e.leaveEncashments || []).reduce(
              (acc, obj) => acc + +obj.days,
              0,
            );
            obj.days = encashDays;
          }

          finaldata.push({ ...obj });
        }
      } else {
        // for Gratuity
        if (payheadMasterId == 83) {
          if (+e.EmployeeSalaryAmount > 0) finaldata.push(obj);
        } else {
          finaldata.push(obj);
        }
      }
    }),
  );

  return finaldata;
}

// Get PNG salary data with YTD

async function getSalaryDataPNGWithYTD(
  userId,
  month,
  payrollFrequency,
  payrollStartDate,
  payrollEndDate,
  attendancePolicy,
) {
  const condition = { userMasterID: userId, payrollFrequency };

  if (payrollFrequency == PayrollFrequencyType.MONTHLY) {
    const startMonth = String(month).slice(0, 4) + '01';
    condition.salaryYYYYMM = {
      [Sequelize.Op.between]: [+startMonth, +month],
    };
  } else {
    const startDate =
      String(payrollEndDate).slice(0, 4) + '-' + '01' + '-' + '01';
    condition.endDate = {
      [Sequelize.Op.between]: [startDate, payrollEndDate],
    };
  }

  const AllSalarydata = await HRSalaryTrasaction.findAll({
    where: condition,
    include: [
      {
        model: HRSalaryMaster,
        as: 'HSM',
        include: [
          {
            model: GradeSalaryStructure,
            as: 'GSS',
            include: [
              { model: GradeStructure },
              {
                model: HRSalaryFields,
                as: 'HSF',
                include: [
                  {
                    model: Payheadmaster,
                    as: 'PHM',
                  },
                ],
              },
            ],
          },
        ],
      },
      {
        model: UserMaster,
        as: 'createByUser',
        attributes: ['displayName'],
      },
      {
        required: false,
        model: EmployeePenalty,
        include: [
          { model: Penalty, as: 'penalty', attributes: ['penaltyName'] },
        ],
      },
      {
        required: false,
        model: Employeeincentive,
        include: [
          {
            model: Incentivetype,
            as: 'IncType',
            attributes: [
              ['incentivetypename', 'name'],
              ['inc_type_displayName', 'displayName'],
              ['IncentivetypeID', 'id'],
              'consider',
            ],
          },
        ],
      },
      {
        model: Designation,
        as: 'designation',
        attributes: ['designationName'],
      },
      {
        model: Department,
        as: 'department',
        attributes: ['departmentName'],
      },
      {
        model: BranchMaster,
        as: 'branchMaster',
        attributes: ['branchName', 'branchAddress'],
      },
    ],

    order: [
      // Order by salaryfieldindex in GradeSalaryStructure
      [
        { model: HRSalaryMaster, as: 'HSM' },
        { model: GradeSalaryStructure, as: 'GSS' },
        'salaryfieldindex',
        'ASC',
      ],

      // Order by payheadName in Payheadmaster
      [
        { model: HRSalaryMaster, as: 'HSM' },
        { model: GradeSalaryStructure, as: 'GSS' },
        { model: HRSalaryFields, as: 'HSF' },
        { model: Payheadmaster, as: 'PHM' },
        'payheadName',
        'ASC',
      ],
    ],
  });

  const depositData =
    payrollFrequency == PayrollFrequencyType.MONTHLY
      ? await deposit.findAll({
          where: {
            depositReceiveAs: 'salary',
            salaryMonth: month,
            ReferenceId: {
              [Sequelize.Op.not]: null,
            },
            userMasterID: userId,
            status: 1,
          },
          include: [
            { model: depositcategory, attributes: ['depositcategoryname'] },
          ],
        })
      : [];

  const salarydata = AllSalarydata.filter((e) =>
    payrollFrequency == PayrollFrequencyType.MONTHLY
      ? e.salaryYYYYMM == month
      : e.startDate == payrollStartDate && e.endDate == payrollEndDate,
  );
  const previousSalaryData = AllSalarydata.filter((e) =>
    payrollFrequency == PayrollFrequencyType.MONTHLY
      ? e.salaryYYYYMM != month
      : e.startDate != payrollStartDate && e.endDate != payrollEndDate,
  );

  let finaldata = [];

  await Promise.all(
    salarydata.map(async (e) => {
      const payheadMasterId = e.HSM?.GSS?.HSF?.payheadMasterId;

      const YTD = previousSalaryData
        .filter((p) => p.HSM?.GSS?.HSF?.payheadMasterId == payheadMasterId)
        .reduce((acc, obj) => acc + +obj.EmployeeSalaryAmount, 0);

      const obj = {
        payheadMasterId,
        payheadName: e.HSM?.GSS?.HSF?.PHM?.payheadName,
        payheadDisplayName: e.HSM?.GSS?.HSF?.payheadDisplayName,
        actualAmount: e.HSM?.EmployeeSalaryAmount,
        EmployeeSalaryAmount: e.EmployeeSalaryAmount,
        salaryYYYYMM: e.salaryYYYYMM,
        userMasterID: e.userMasterID,
        SalaryCalcOnDays: e.SalaryCalcOnDays,
        createBy: e.createBy,
        calculatedOn: e.calculatedOn,
        createByUserName: e.createByUser.displayName,
        baseOnCalculation: e.HSM?.GSS?.gradeStructure?.baseOnCalculation,
        formula: e.HSM?.GSS?.formula,
        salaryFieldSrNo: e.HSM?.GSS?.HSF?.salaryFieldSrNo,
        salaryFieldSide: e.HSM?.GSS?.HSF?.salaryFieldSide,
        considerIn: e.HSM?.GSS?.HSF?.considerIn,
        payrollFrequency: e.payrollFrequency,
        startDate: e.startDate,
        endDate: e.endDate,
        branch: e.branchMaster?.branchName || '',
        branchAddress: e.branchMaster?.branchAddress || '',
        department: e.department?.departmentName || '',
        designation: e.designation?.designationName || '',
        taxApplicability: e.HSM?.GSS?.HSF?.PHM?.taxApplicability || '',
        YTD: YTD ? +YTD.toFixed(2) : 0.0,
      };

      if (payheadMasterId == 24) {
        // previous incentive sum
        const previousIncentiveData = previousSalaryData.flatMap(
          (item) => item.employeeincentives,
        );

        const previousIncentive = Object.values(
          previousIncentiveData.reduce((acc, curr) => {
            if (!acc[curr.IncentivetypeID]) {
              acc[curr.IncentivetypeID] = {
                IncentivetypeID: curr.IncentivetypeID,
                amount: curr.amount,
                name:
                  curr.IncType?.dataValues.displayName ||
                  curr.IncType?.dataValues.name,
                consider: curr.IncType?.consider,
              }; // Clone the object
            } else {
              acc[curr.IncentivetypeID].amount += curr.amount; // Sum the amount
            }
            return acc;
          }, {}),
        );

        const incentive = Object.values(
          (e.employeeincentives || []).reduce((acc, curr) => {
            if (!acc[curr.IncentivetypeID]) {
              acc[curr.IncentivetypeID] = {
                IncentivetypeID: curr.IncentivetypeID,
                amount: curr.amount,
                name:
                  curr.IncType?.dataValues.displayName ||
                  curr.IncType?.dataValues.name,
                consider: curr.IncType?.consider,
              }; // Clone the object
            } else {
              acc[curr.IncentivetypeID].amount += curr.amount; // Sum the amount
            }
            return acc;
          }, {}),
        );

        incentive.forEach((data) => {
          const YTD = previousIncentive.find(
            (y) => y.IncentivetypeID == data.IncentivetypeID,
          );

          finaldata.push({
            payheadMasterId: payheadMasterId,
            payheadName: data.name,
            actualAmount: e.HSM?.EmployeeSalaryAmount || 0,
            EmployeeSalaryAmount: data.amount,
            salaryYYYYMM: e.salaryYYYYMM,
            userMasterID: e.userMasterID,
            baseOnCalculation: e.HSM?.GSS?.gradeStructure?.baseOnCalculation,
            formula: e.HSM?.GSS?.formula,
            salaryFieldSrNo: e.HSM?.GSS?.HSF?.salaryFieldSrNo,
            salaryFieldSide: e.HSM?.GSS?.HSF?.salaryFieldSide,
            consider: data.consider,
            payrollFrequency: e.payrollFrequency,
            startDate: e.startDate,
            endDate: e.endDate,
            branchAddress: obj.branch,
            department: obj.department,
            designation: obj.designation,
            taxApplicability: obj.taxApplicability,
            YTD: YTD ? (+YTD.amount).toFixed(2) : 0.0,
          });
        });
      } else if (payheadMasterId == 34) {
        // previous incentive sum
        const previousPenaltyData = previousSalaryData.flatMap(
          (item) => item.employeePenalties,
        );

        const previousPenalty = Object.values(
          previousPenaltyData.reduce((acc, curr) => {
            if (!acc[curr.penaltyID]) {
              acc[curr.penaltyID] = {
                penaltyID: curr.penaltyID,
                penaltyAmount: curr.penaltyAmount,
                penaltyName: curr.penalty?.penaltyName || '',
              }; // Clone the object
            } else {
              acc[curr.penaltyID].penaltyAmount += curr.penaltyAmount; // Sum the amount
            }
            return acc;
          }, {}),
        );
        const penaltydata = Object.values(
          (e.employeePenalties || []).reduce((acc, curr) => {
            if (!acc[curr.penaltyID]) {
              acc[curr.penaltyID] = {
                penaltyID: curr.penaltyID,
                penaltyAmount: curr.penaltyAmount,
                penaltyName: curr.penalty?.penaltyName || '',
              }; // Clone the object
            } else {
              acc[curr.penaltyID].penaltyAmount += curr.penaltyAmount; // Sum the amount
            }
            return acc;
          }, {}),
        );

        penaltydata.forEach((data) => {
          const YTD = previousPenalty.find(
            (y) => y.penaltyID == data.penaltyID,
          );

          finaldata.push({
            payheadMasterId: payheadMasterId,
            payheadName: data.penaltyName,
            actualAmount: e.HSM?.EmployeeSalaryAmount || 0,
            EmployeeSalaryAmount: data.penaltyAmount,
            salaryYYYYMM: e.salaryYYYYMM,
            userMasterID: e.userMasterID,
            baseOnCalculation: e.HSM?.GSS?.gradeStructure?.baseOnCalculation,
            formula: e.HSM?.GSS?.formula,
            salaryFieldSrNo: e.HSM?.GSS?.HSF?.salaryFieldSrNo,
            salaryFieldSide: e.HSM?.GSS?.HSF?.salaryFieldSide,
            payrollFrequency: e.payrollFrequency,
            startDate: e.startDate,
            endDate: e.endDate,
            branchAddress: obj.branch,
            department: obj.department,
            designation: obj.designation,
            taxApplicability: obj.taxApplicability,
            YTD: YTD ? (+YTD.penaltyAmount).toFixed(2) : 0.0,
          });
        });
      } else if (payheadMasterId == 43) {
        if (attendancePolicy && +e.EmployeeSalaryAmount > 0) {
          finaldata.push({ ...obj, consider: attendancePolicy.consider });
        }
      } else if (payheadMasterId == 96) {
        const depositToDeduction = depositData.length
          ? [...depositData].filter(
              (d) => d.depositReceiveAs == 'salary' && d.salaryMonth == month,
            )
          : [];
        const result = Object.values(
          depositToDeduction.reduce((acc, curr) => {
            if (!acc[curr.depositcategory.depositcategoryname]) {
              acc[curr.depositcategory.depositcategoryname] = {
                payheadMasterId: payheadMasterId,
                payheadDisplayName: '',
                payheadName: curr.depositcategory.depositcategoryname,
                actualAmount: 0,
                EmployeeSalaryAmount: 0,
                salaryYYYYMM: e.salaryYYYYMM,
                userMasterID: e.userMasterID,
                baseOnCalculation: obj.baseOnCalculation,
                formula: obj.formula,
                salaryFieldSrNo: obj.salaryFieldSrNo,
                salaryFieldSide: obj.salaryFieldSide,
                payrollFrequency: e.payrollFrequency,
                startDate: e.startDate,
                endDate: e.endDate,
                branchAddress: obj.branch,
                department: obj.department,
                designation: obj.designation,
                taxApplicability: obj.taxApplicability,
                YTD: obj.YTD,
              };
            }
            acc[
              curr.depositcategory.depositcategoryname
            ].EmployeeSalaryAmount += curr.amount; // Sum the amount
            return acc;
          }, {}),
        );
        finaldata = [...finaldata, ...result];
      } else if (payheadMasterId == 97) {
        const depositToPay = depositData.length
          ? [...depositData].filter(
              (d) => d.depositPayAs == 'salary' && d.salaryMonthToPay == month,
            )
          : [];
        const result = Object.values(
          depositToPay.reduce((acc, curr) => {
            if (!acc[curr.depositcategory.depositcategoryname]) {
              acc[curr.depositcategory.depositcategoryname] = {
                payheadMasterId: e.payheadMasterId,
                payheadDisplayName: '',
                payheadName: curr.depositcategory.depositcategoryname,
                actualAmount: 0,
                EmployeeSalaryAmount: 0,
                salaryYYYYMM: e.salaryYYYYMM,
                userMasterID: e.userMasterID,
                baseOnCalculation: obj.baseOnCalculation,
                formula: obj.formula,
                salaryFieldSrNo: obj.salaryFieldSrNo,
                salaryFieldSide: obj.salaryFieldSide,
                considerIn: obj.considerIn,
                payrollFrequency: e.payrollFrequency,
                startDate: e.startDate,
                endDate: e.endDate,
                branchAddress: obj.branch,
                department: obj.department,
                designation: obj.designation,
                taxApplicability: obj.taxApplicability,
                YTD: obj.YTD,
              };
            }
            acc[
              curr.depositcategory.depositcategoryname
            ].EmployeeSalaryAmount += curr.amount; // Sum the amount
            return acc;
          }, {}),
        );
        finaldata = [...finaldata, ...result];
      } else if (payheadMasterId == 67) {
        if (+e.EmployeeSalaryAmount > 0) {
          finaldata.push({ ...obj });
        }
      } else if (payheadMasterId == 101) {
        if (+e.EmployeeSalaryAmount > 0) {
          finaldata.push({ ...obj });
        }
      } else {
        // for Gratuity
        if (payheadMasterId == 83) {
          if (+e.EmployeeSalaryAmount > 0) finaldata.push(obj);
        } else {
          finaldata.push(obj);
        }
      }
    }),
  );

  return finaldata;
}

async function getSundaysBetweenDates(startDate, endDate) {
  const sundays = [];
  let currentDate = new Date(startDate);
  let enddate = new Date(endDate);

  while (currentDate <= enddate) {
    if (currentDate.getDay() === 0) {
      sundays.push(new Date(currentDate).toISOString().slice(0, 10));
    }
    currentDate.setDate(currentDate.getDate() + 1);
  }

  return sundays;
}

