async function addCanteenLogPenalty(log) {
  const date = asiaKolkataDateTime(log.logDateTime).slice(0, 10);
  const dateTime = asiaKolkataDateTime(log.logDateTime);

  if (new Date(log.logDateTime) < new Date(date + ' ' + '05:00 PM')) {
    await EmployeePenalties.create({
      userMasterID: log.userMasterID,
      penaltyID: 124, // penalty id
      penaltyAmount: 15,
      penaltyDate: date,
      description: 'Lunch took at ' + dateTime,
      createBy: log.createBy,
      createByIp: log.createByIp,
    });
  } else {
    await EmployeePenalties.create({
      userMasterID: log.userMasterID,
      penaltyID: 125, // penalty id
      penaltyAmount: 15,
      penaltyDate: date,
      description: 'Dinner took at ' + dateTime,
      createBy: log.createBy,
      createByIp: log.createByIp,
    });
  }
}

const financialMonths = [
  'Apr',
  'May',
  'Jun',
  'Jul',
  'Aug',
  'Sep',
  'Oct',
  'Nov',
  'Dec',
  'Jan',
  'Feb',
  'Mar',
];

async function getYearMonthByRange(startYearMonth, endYearMonth) {
  let startYear = Math.floor(+startYearMonth / 100);
  let startMonth = +startYearMonth % 100;

  let endYear = Math.floor(+endYearMonth / 100);
  let endMonth = +endYearMonth % 100;

  let data = [];

  for (let year = startYear; year <= endYear; year++) {
    let start = year === startYear ? startMonth : 1;
    let end = year === endYear ? endMonth : 12;

    for (let month = start; month <= end; month++) {
      let yearmonth = year * 100 + month;
      data.push(yearmonth);
    }
  }

  return data;
}

async function getAllSalaryMasterByRange(userId, startYearMonth, endYearMonth) {
  // Get the range of months
  const range = await getYearMonthByRange(startYearMonth, endYearMonth);

  // Fetch salary data for each month concurrently
  const promises = range.map((month) => {
    return getUserSalaryMasterByMonth(userId, month).then((salaryData) => ({
      month: month,
      salaryData,
    }));
  });

  // Wait for all promises to resolve
  const finalSalaryMasterData = await Promise.all(promises);

  return finalSalaryMasterData;
}

async function getAllSalaryDataByRange(userId, startYearMonth, endYearMonth) {
  const range = await getYearMonthByRange(startYearMonth, endYearMonth);

  const promises = range.map((month) => {
    return getSalaryData(userId, month).then((salaryData) => ({
      month: month,
      salaryData,
    }));
  });

  const finalSalaryData = await Promise.all(promises);

  return finalSalaryData;
}

async function getCurrentFinancialYear(date) {
  date = date || new Date();
  const year = date.getFullYear();
  const month = date.getMonth() + 1; // Adding 1 because getMonth() returns zero-based month index
  const financialYearStartMonth = 4; // Assuming financial year starts from April (4th month)

  if (month >= financialYearStartMonth) {
    // If the month is April or later, it belongs to the next financial year
    return year + '-' + (year + 1).toString().substring(0);
  } else {
    // Otherwise, it belongs to the current financial year
    return year - 1 + '-' + year.toString().substring(0);
  }
}

async function getPreviousMonthSalaryCycleDate(todayDate, salaryPolicy) {
  let currentDate = new Date(todayDate);

  currentDate.setMonth(currentDate.getMonth() - 1);
  let month = currentDate.getMonth() + 1; // Adding 1 because getMonth() returns zero-based month (0 for January)
  let day = currentDate.getDate();

  month = (month < 10 ? '0' : '') + month;
  day = (day < 10 ? '0' : '') + day;

  // Format the date
  const previousMonthDate = currentDate.getFullYear() + '-' + month + '-' + day;
  const previousMonthDays = daysInMonth(
    previousMonthDate.slice(5, 7),
    previousMonthDate.slice(0, 4),
  );

  let previousSalaryCycleStartDate, previousSalaryCycleEndDate;
  if (salaryPolicy) {
    const date2 = salaryPolicy['salaryPolicy.salaryCycleDate'];

    const salary_startdate = date2 < 10 ? '0' + date2 : date2;

    previousSalaryCycleStartDate =
      previousMonthDate.slice(0, 8) + salary_startdate;

    let date1 = new Date(previousSalaryCycleStartDate);
    date1.setDate(date1.getDate() + (previousMonthDays - 1));

    previousSalaryCycleEndDate =
      date1.getFullYear() +
      '-' +
      String(date1.getMonth() + 1).padStart(2, '0') +
      '-' +
      String(date1.getDate()).padStart(2, '0');
  } else {
    previousSalaryCycleStartDate = previousMonthDate.slice(0, 8) + '01';
    previousSalaryCycleEndDate =
      previousMonthDate.slice(0, 8) + previousMonthDays;
  }

  if (new Date(previousSalaryCycleStartDate) > new Date(previousMonthDate)) {
    let date1 = new Date(previousSalaryCycleStartDate);
    date1.setMonth(date1.getMonth() - 1);

    previousSalaryCycleStartDate =
      date1.getFullYear() +
      '-' +
      String(date1.getMonth() + 1).padStart(2, '0') +
      '-' +
      String(date1.getDate()).padStart(2, '0');

    const monthDays = daysInMonth(
      previousSalaryCycleStartDate.slice(5, 7),
      previousSalaryCycleStartDate.slice(0, 4),
    );

    let date2 = new Date(previousSalaryCycleStartDate);
    date2.setDate(date1.getDate() + (monthDays - 1));

    previousSalaryCycleEndDate =
      date2.getFullYear() +
      '-' +
      String(date2.getMonth() + 1).padStart(2, '0') +
      '-' +
      String(date2.getDate()).padStart(2, '0');
  }

  return {
    previousSalaryCycleStartDate: previousSalaryCycleStartDate,
    previousSalaryCycleEndDate: previousSalaryCycleEndDate,
  };
}

async function getFinancialYearByMonth(yearMonth) {
  yearMonth = +yearMonth;

  const year = Math.floor(yearMonth / 100);
  const month = Math.floor(yearMonth % 100);

  if (month >= 4 && month <= 12) {
    return `${year}-${year + 1}`;
  } else if (month >= 1 && month <= 3) {
    return `${year - 1}-${year}`;
  } else {
    return 'Invalid month';
  }
}

function getTaxableIncome(ranges = [], rebateAmount = 0) {
  // Calculate the taxable income required to reach a given tax amount (rebateAmount)

  // Calculate the taxable income required to reach a given tax amount (rebateAmount)

  let taxableIncome = 0;
  let taxSoFar = 0;

  for (let i = 0; i < ranges.length; i++) {
    const { fromAmount, toAmount, percentage } = ranges[i];
    const slabRange = toAmount - fromAmount + (fromAmount === 0 ? 0 : 1);
    const slabTax = slabRange * (percentage / 100);

    // Check if the rebateAmount falls within this slab
    if (taxSoFar + slabTax >= rebateAmount) {
      const remainingTax = rebateAmount - taxSoFar;
      const extraIncomeInSlab = remainingTax / (percentage / 100);
      taxableIncome = fromAmount + extraIncomeInSlab;
      break;
    } else {
      taxSoFar += slabTax;
    }
  }

  return Math.round(taxableIncome - 1);
}

function calculateIncomeTaxByRange(
  amount,
  ranges,
  rebateAmount = 0,
  marginalReliefFlag = false,
) {
  let incomeTaxAmount = 0;
  let remainingAmount = amount;

  for (let i = 0; i < ranges.length; i++) {
    const { fromAmount, toAmount, percentage } = ranges[i];

    if (remainingAmount <= 0) break;

    const rangeAmount = Math.min(
      remainingAmount,
      toAmount - fromAmount + (fromAmount == 0 ? 0 : 1),
    );
    const deductionAmount = (rangeAmount * percentage) / 100;

    incomeTaxAmount += deductionAmount;
    remainingAmount -= rangeAmount;
  }

  // get taxable income from rebate
  const taxableIncome = marginalReliefFlag
    ? getTaxableIncome(ranges, rebateAmount)
    : 0;

  return { incomeTaxAmount, marginalReliefAmt: taxableIncome };
}

function calculateIncomeTaxByRangeAndReturnWithAmount(
  amount,
  ranges,
  rebateAmount = 0,
  marginalReliefFlag = false,
) {
  let incomeTaxAmount = 0;
  let remainingAmount = amount;

  const amountWithRanges = [];

  for (let i = 0; i < ranges.length; i++) {
    const { fromAmount, toAmount, percentage } = ranges[i];

    if (remainingAmount <= 0) {
      amountWithRanges.push({
        fromAmount,
        toAmount,
        percentage,
        amount: 0,
      });
      continue;
    }

    const rangeAmount = Math.min(
      remainingAmount,
      toAmount - fromAmount + (fromAmount == 0 ? 0 : 1),
    );
    const deductionAmount = (rangeAmount * percentage) / 100;

    amountWithRanges.push({
      fromAmount,
      toAmount,
      percentage,
      amount: deductionAmount,
    });

    incomeTaxAmount += deductionAmount;
    remainingAmount -= rangeAmount;
  }

  // get taxable income from rebate
  const taxableIncome = marginalReliefFlag
    ? getTaxableIncome(ranges, rebateAmount)
    : 0;

  return {
    amountWithRanges,
    incomeTaxAmount,
    marginalReliefAmt: taxableIncome,
  };
}

async function incomeTaxCalculationByRegime(
  netAmount,
  gender,
  financialYear,
  regime,
  type,
  rebateAmount,
) {
  gender = gender == 'female' ? gender.toLowerCase().trim() : 'male';

  const FindIncomeTaxSlabs = await incomeTaxSlabs.findAll({
    raw: true,
    where: Sequelize.and(
      Sequelize.where(
        sequelize.fn(
          'TRIM',
          sequelize.fn('LOWER', sequelize.col('incomeTaxSlabMaster.gender')),
        ),
        gender,
      ),
      Sequelize.where(
        sequelize.col('incomeTaxSlabMaster.assessmentYear'),
        financialYear,
      ),
      Sequelize.where(sequelize.col('incomeTaxSlabMaster.regime'), regime),
      Sequelize.where(sequelize.col('incomeTaxSlabs.status'), 1),
    ),
    include: [{ model: incomeTaxSlabMaster, attributes: [] }],
    attributes: ['fromAmount', 'toAmount', 'percentage'],
    order: [['fromAmount', 'ASC']],
  });

  // --------------------- marginalRelief applicable from 2025-2026 ------------------------------

  const marginalReliefFlag =
    +String(financialYear).slice(0, 4) >= 2025 && regime == 'New Regime';

  if (type == 'cal') {
    const { incomeTaxAmount, marginalReliefAmt } = calculateIncomeTaxByRange(
      netAmount,
      FindIncomeTaxSlabs,
      rebateAmount,
      marginalReliefFlag,
    );

    return { incomeTaxAmount, marginalReliefAmt };
  } else {
    return calculateIncomeTaxByRangeAndReturnWithAmount(
      netAmount,
      FindIncomeTaxSlabs,
      rebateAmount,
      marginalReliefFlag,
    );
  }
}

async function getFinancialYears(date) {
  date = date || new Date();
  const fiscalYears = [];

  const currentDateYear = date.getFullYear();
  let previousYear, nextYear, currentYear;

  if (date.getMonth() < 3) {
    // If current month is January, February, or March
    previousYear = currentDateYear - 2;
    currentYear = currentDateYear - 1;
    nextYear = currentDateYear;
  } else {
    previousYear = currentDateYear - 1;
    currentYear = currentDateYear;
    nextYear = currentDateYear + 1;
  }

  // Get previous financial year
  fiscalYears.push(`${previousYear}-${previousYear + 1}`);

  // Get current financial year
  fiscalYears.push(`${currentYear}-${currentYear + 1}`);

  // Get next financial year
  fiscalYears.push(`${nextYear}-${nextYear + 1}`);

  return fiscalYears;
}

async function getEmployeeDeclarationAmount(
  userId,
  financialYear,
  totalLeaveEncash,
  totalLTA,
  regime = RegimeType.NEW_REGIME,
) {
  const years = String(financialYear).split('-');
  const applicableYYYYMM = years[1] + '03';

  const sub_condition = {};

  if (regime == RegimeType.NEW_REGIME) {
    sub_condition.tdsSectionID = newRegimeInclude_Sub_Section_Ids;
  }

  const allEmployeeDeclarationData = await employeeDeclaration.findAll({
    where: {
      assessmentYear: financialYear,
      userMasterID: userId,
      // authStatus: 1, // get only Accepted declaration
    },
    include: [
      {
        model: tdsSubSection,
        where: {
          ...sub_condition,
        },
        attributes: [
          'tdsSubSectionCategoryID',
          'tdsSubSectionID',
          'tdsSectionID',
        ],
        include: [
          {
            model: TdsSubSectionCategory, // <-- added
            attributes: ['categoryName'], // <-- added
          },

          {
            model: TdsSubSectionLimit,
            where: {
              applicableYYYYMM: { [Sequelize.Op.lte]: +applicableYYYYMM },
            },
            attributes: ['maxLimit'],
            separate: true, // fetch in a separate query
            order: [['applicableYYYYMM', 'DESC']],
            limit: 1, // only the latest,
            required: false,
          },
        ],
      },
    ],
  });

  const employeeDeclarationData = allEmployeeDeclarationData.filter(
    (e) => e.authStatus == 1,
  );

  // find 1.5 lakhs category data

  const amount = employeeDeclarationData
    .filter((e) => e.tdsSubSection.tdsSubSectionCategoryID == 1)
    .reduce((acc, obj) => acc + +obj.declarationAmount, 0);
  // find other data
  const otherDeclaration = employeeDeclarationData.filter(
    (e) =>
      e.tdsSubSection.tdsSubSectionCategoryID != 1 &&
      ![28, 30].includes(+e.tdsSubSection.tdsSectionID),
  );

  // for Leave Encashment and LTA

  const declaredLeaveEncashment =
    employeeDeclarationData.find((e) => +e.tdsSubSection.tdsSectionID == 30)
      ?.declarationAmount || 0;
  const declaredLeaveLTA =
    employeeDeclarationData.find((e) => +e.tdsSubSection.tdsSectionID == 28)
      ?.declarationAmount || 0;

  let finalLeaveEncash = 0,
    finalLTA = 0;

  if (+totalLeaveEncash > 0 && +declaredLeaveEncashment > 0)
    finalLeaveEncash = Math.min(declaredLeaveEncashment, totalLeaveEncash);
  if (+totalLTA > 0 && +declaredLeaveLTA > 0)
    finalLTA = Math.min(declaredLeaveLTA, totalLTA);

  let otherAmount = +finalLeaveEncash + +finalLTA;

  otherDeclaration.map((e) => {
    otherAmount += e.tdsSubSection.tdsSubSectionLimits?.[0]?.maxLimit
      ? +e.declarationAmount >
        +e.tdsSubSection.tdsSubSectionLimits?.[0]?.maxLimit
        ? +e.tdsSubSection.tdsSubSectionLimits?.[0]?.maxLimit
        : +e.declarationAmount
      : +e.declarationAmount;
  });

  const finalAmount = (+amount > 150000 ? 150000 : +amount) + otherAmount;

  /* -------- CATEGORY WISE DATA -------- */

  // get all categories
  const allCategories = await TdsSubSectionCategory.findAll({
    attributes: ['tdsSubSectionCategoryID', 'categoryName'],
    order: [['tdsSubSectionCategoryID', 'ASC']],
  });

  // const categoryMap = new Map();

  // // initialize categories with 0 amount
  // allCategories.forEach((c) => {
  //   categoryMap.set(+c.tdsSubSectionCategoryID, {
  //     categoryId: +c.tdsSubSectionCategoryID,
  //     categoryName: c.categoryName,
  //     amount: 0,
  //   });
  // });

  // // add declared values
  // employeeDeclarationData.forEach((e) => {
  //   const categoryId = +e.tdsSubSection.tdsSubSectionCategoryID;

  //   let amt = +e.declarationAmount || 0;

  //   const maxLimit = e.tdsSubSection.tdsSubSectionLimits?.[0]?.maxLimit;

  //   if (maxLimit) {
  //     amt = amt > +maxLimit ? +maxLimit : amt;
  //   }

  //   if (categoryMap.has(categoryId)) {
  //     categoryMap.get(categoryId).amount += amt;
  //   }
  // });

  // const tdsCategoryWiseData = [...categoryMap.values()];

  /* -------- CATEGORY WISE DATA (OPTIMIZED) -------- */

  // group declarations by category
  const categoryDeclarationMap = new Map();

  allEmployeeDeclarationData.forEach((e) => {
    const categoryId = +e.tdsSubSection.tdsSubSectionCategoryID;

    if (!categoryDeclarationMap.has(categoryId)) {
      categoryDeclarationMap.set(categoryId, []);
    }

    categoryDeclarationMap.get(categoryId).push(e);
  });

  const tdsCategoryWiseData = allCategories.map((c) => {
    const categoryId = +c.tdsSubSectionCategoryID;
    const filterData = categoryDeclarationMap.get(categoryId) || [];

    let proof = 0,
      amountDeclared = 0,
      amountRejected = 0,
      amountAccepted = 0,
      actualApprovedAmount = 0;

    filterData.forEach((obj) => {
      const amt = +obj.declarationAmount || 0;

      amountDeclared += amt;

      proof += obj.attachments?.length || 0;

      if (obj.authStatus == 2) {
        amountRejected += amt;
      }

      if (obj.authStatus == 1) {
        amountAccepted += amt;

        if (categoryId == 1) {
          // 80C handled later
          actualApprovedAmount += amt;
        } else {
          const maxLimit =
            obj.tdsSubSection?.tdsSubSectionLimits?.[0]?.maxLimit;

          actualApprovedAmount += maxLimit
            ? amt > +maxLimit
              ? +maxLimit
              : amt
            : amt;
        }
      }
    });

    // apply 80C limit
    if (categoryId == 1) {
      actualApprovedAmount =
        actualApprovedAmount > 150000 ? 150000 : actualApprovedAmount;
    }

    return {
      categoryId,
      categoryName: c.categoryName,
      noOfDeclaration: filterData.length,
      amountDeclared,
      proof,
      amountRejected,
      amountAccepted,
      actualApprovedAmount,
    };
  });

  return {
    employeeDeclarationAmount: finalAmount,
    tdsCategoryWiseData,
  };
}

function toCalculatesalaryMasterData(salaryMasterdata) {
  let salaryMasterGross = 0,
    ptAmount = 0,
    leaveEncash = 0,
    LTA = 0;

  salaryMasterdata.map((e) => {
    salaryMasterGross +=
      e.salaryData.find((s) => s.payheadMasterId == 50)?.EmployeeSalaryAmount ||
      0;
    ptAmount +=
      e.salaryData.find((s) => s.payheadMasterId == 15)?.EmployeeSalaryAmount ||
      0;

    // leave encashment

    leaveEncash +=
      +[...e.salaryData].find((s) => s.payheadMasterId == 67)
        ?.EmployeeSalaryAmount || 0;

    // leave travelling allowance

    LTA +=
      +[...e.salaryData].find((s) => s.payheadMasterId == 20)
        ?.EmployeeSalaryAmount || 0;
  });

  return {
    salaryMasterGross,
    ptAmount,
    leaveEncash,
    LTA,
  };
}

function toCalculateEmployeeSalaryData(salarydata) {
  let salaryGross = 0;
  let PtAmount = 0;
  let leaveEncash = 0;
  let LTA = 0;
  let pfAmount = 0;
  let ESIAmount = 0;
  salarydata.map((s) => {
    salaryGross +=
      +[...s.salaryData].find(
        (e) => e.payheadMasterId == payheadMasterIdsMapping.GROSS,
      )?.EmployeeSalaryAmount || 0;
    PtAmount +=
      +[...s.salaryData].find(
        (e) => e.payheadMasterId == payheadMasterIdsMapping.PTAX,
      )?.EmployeeSalaryAmount || 0;

    // leave encashment

    leaveEncash +=
      +[...s.salaryData].find(
        (e) => e.payheadMasterId == payheadMasterIdsMapping.LEAVE_ENCASHMENT,
      )?.EmployeeSalaryAmount || 0;

    // leave travelling allowance

    LTA +=
      +[...s.salaryData].find(
        (e) => e.payheadMasterId == payheadMasterIdsMapping.LTA,
      )?.EmployeeSalaryAmount || 0;

    pfAmount +=
      +[...s.salaryData].find(
        (e) => e.payheadMasterId == payheadMasterIdsMapping.PF,
      )?.EmployeeSalaryAmount || 0;

    ESIAmount +=
      +[...s.salaryData].find(
        (e) => e.payheadMasterId == payheadMasterIdsMapping.EMPLOYEE_ESIC,
      )?.EmployeeSalaryAmount || 0;
  });
  return { salaryGross, PtAmount, leaveEncash, LTA, pfAmount, ESIAmount };
}

function showAmount(amount) {
  return +amount > 0 ? (+amount % 1 === 0 ? +amount : +amount.toFixed(2)) : 0;
}

