// Hours beyond the set hours count as OT
async function coff_extraHrs_As_Overtime(
  attendanceData,
  attendancePolicy,
  totalMinutes,
  createBy,
  createByIp,
  transaction = null,
  otAdded,
  monthlyOtCalType,
  weekoffType = offDayCategoryEnum.WEEKOFF,
) {
  if (!attendanceData) return 0;

  // if overtime added monthly and monthly ot cal is on total working working hrs
  if (
    otAdded == overtimeAddedEnum.MONHTLY &&
    monthlyOtCalType == monthlyOTCalcuationType.TOTAL_WORKING
  )
    return 0;

  const userMasterID = attendanceData.userMasterID;
  const AttendanceDate = attendanceData.AttendanceDate;
  const punchOutTime = attendanceData.OutDateTime;
  const AttendanceTransID = attendanceData.AttendanceTransID;

  // Delete existing OT first

  await delete_Overtime_Attendance_Manual(
    userMasterID,
    AttendanceDate,
    transaction,
    OvertimeRequestTypeEnum.POST_SHIFT,
  );

  const isAddOvertime = await is_OvertimeAdd_otBasedOn_Company({
    userMasterID: userMasterID,
    date: AttendanceDate,
  });
  if (!isAddOvertime) {
    return;
  }
  // Mandatory validations
  if (!attendancePolicy || !punchOutTime || !createBy || +totalMinutes <= 0)
    return 0;

  const companyMasterID = attendancePolicy.companyMasterID || null;

  // Check OT eligibility
  if (+totalMinutes < +attendancePolicy.overtimeEntryAfterMin) return 0;

  let finalMinutes = Math.round(+totalMinutes);

  // SLOT / ROUND OFF handling
  if (
    [overtimeTypeEnum.ROUND_OFF, overtimeTypeEnum.SLOT_WISE].includes(
      attendancePolicy.overtimeType,
    ) &&
    attendancePolicy.typeValue
  ) {
    const typeValue = +attendancePolicy.typeValue;

    if (attendancePolicy.overtimeType === overtimeTypeEnum.SLOT_WISE) {
      finalMinutes = Math.floor(finalMinutes / typeValue) * typeValue;
    }

    if (attendancePolicy.overtimeType === overtimeTypeEnum.ROUND_OFF) {
      finalMinutes = +roundToNearestHour(finalMinutes, typeValue) * 60;
    }
  }

  if (finalMinutes <= 0) return 0;

  // Time calculations
  const otOutTime = new Date(punchOutTime);
  const otInTime = new Date(otOutTime);
  otInTime.setMinutes(otInTime.getMinutes() - finalMinutes);

  const inTime = formatAMPM(otInTime);
  const outTime = formatAMPM(otOutTime);

  if (
    otAdded == overtimeAddedEnum.MONHTLY &&
    monthlyOtCalType == monthlyOTCalcuationType.SHIFT_PLUS_OT
  ) {
    // calculate ratio

    const ratio = getOvertimeCalculationRatio(
      attendancePolicy,
      weekoffType == offDayCategoryEnum.WEEKOFF,
      weekoffType == offDayCategoryEnum.HOLIDAY,
      null,
      finalMinutes,
    );

    await addDailyOTRequestForMonthlyOT(
      AttendanceTransID,
      userMasterID,
      AttendanceDate,
      inTime,
      outTime,
      otInTime,
      otOutTime,
      finalMinutes,
      attendancePolicy.attendancePolicyID,
      companyMasterID,
      ratio,
      createBy,
      createByIp,
      transaction,
      OvertimeRequestTypeEnum.POST_SHIFT,
    );

    return finalMinutes;
  }

  // Auto approve
  if (
    attendancePolicy.autoApprove &&
    finalMinutes <= +attendancePolicy.autoApprove
  ) {
    const ratio = getOvertimeCalculationRatio(
      attendancePolicy,
      weekoffType == offDayCategoryEnum.WEEKOFF,
      weekoffType == offDayCategoryEnum.HOLIDAY,
      null,
      finalMinutes,
    );

    const approveFn = autoApproveOT_Manual;

    approveFn(
      AttendanceTransID,
      userMasterID,
      AttendanceDate,
      inTime,
      outTime,
      otInTime,
      otOutTime,
      finalMinutes,
      attendancePolicy.attendancePolicyID,
      companyMasterID,
      ratio,
      transaction,
      OvertimeRequestTypeEnum.POST_SHIFT,
    );

    return finalMinutes;
  }

  // Manual authorization
  const overtimeData = {
    AttendanceTransID,
    UserMasterID: userMasterID,
    OverTimeDate: AttendanceDate,
    OverTimeIn: inTime,
    OverTimeOut: outTime,
    OverTimeInDateTime: otInTime,
    OverTimeOutDateTime: otOutTime,
    OverTimeHourAndMin: finalMinutes,
    AttendancePolicyID: attendancePolicy.attendancePolicyID,
    CompanyMasterID: companyMasterID,
    otRequestType: OvertimeRequestTypeEnum.POST_SHIFT,
    createBy,
    createByIp,
  };

  await overtimeauthorization_Manual(overtimeData, transaction);

  return finalMinutes;
}

