function checkLeaveOnWH(leave = [], WH = [], isFilterOD = false) {
  const filterLeaveData = isFilterOD
    ? leave.filter((e) => e.hrLeaveType.LeaveID != 25)
    : leave;
  const leaveMap = new Map(
    filterLeaveData.map((item) => [item.date, item.days]),
  );

  const filteredArray = WH.filter((item) => {
    const daysInArray2 = leaveMap.get(item.date);
    return !(
      daysInArray2 === 1 ||
      (item.value === 1 && daysInArray2 !== undefined)
    );
  });

  return filteredArray;
}

