// ----------------- OD on weekoff Miss Punch Logic without transaction -------------------

async function OD_On_Weekoff_MissPunch_Without_Trans(
  attendanceData,
  userMasterID,
  AttendanceDate,
  whData,
  attendancePolicy,
  shiftTimeData,
  odData = [],
  companyMasterID,
  otAdded,
  monthlyOtCalType,
  weekoffType,
  holidayCoffRuleIn,
  holidayCompensationRules,
) {
  // if weekoff or holiday and attendance policy
  if (whData && shiftTimeData && odData.length) {
    // check OD is approved or not
    const odDays = odData.reduce((acc, obj) => acc + +obj.days, 0);

    if (odDays > 0) {
      let minutes = 0;

      // if half day weekoff
      if (whData.value == 0.5) {
        // check if OD is applied for Full Day or Second Half
        const checkSecondHalfOD = odData.find((e) =>
          ['Full Day', 'Second Half'].includes(e.userLeave.DayType),
        );

        if (checkSecondHalfOD) {
          minutes =
            Math.round(+shiftTimeData.totalhours * 60) -
            Math.round(+shiftTimeData.totalhourshalfday * 60);
        }
      } else {
        minutes =
          odDays == 0.5
            ? Math.round(+shiftTimeData.totalhourshalfday * 60)
            : Math.round(+shiftTimeData.totalhours * 60);
      }

      // if OD on weekOff add OT/ED/Coff
      await add_OD_On_weekOff_Coff_OT_ED_WithOut_Trans(
        attendancePolicy,
        attendanceData,
        companyMasterID,
        minutes,
        0,
        minutes,
        0,
        userMasterID,
        AttendanceDate,
        otAdded,
        monthlyOtCalType,
        weekoffType,
        holidayCoffRuleIn,
        holidayCompensationRules,
      );
    }
  }
}

// ------------------- Add Coff/OT/ED if OD on weekoff With out Transaction -------------------

async function add_OD_On_weekOff_Coff_OT_ED_WithOut_Trans(
  attendancePolicy,
  attendanceData,
  companyMasterID,
  weekOffMinutes,
  normalDayMinutes,
  totalHours,
  skipMinutes,
  userMasterID,
  AttendanceDate,
  otAdded,
  monthlyOtCalType,
  weekoffType = offDayCategoryEnum.WEEKOFF,
  holidayCoffRuleIn,
  holidayCompensationRules,
) {
  if (attendancePolicy) {
    const parameterData = {
      attendancePolicy,
      weekoffType,
      holidayCoffRuleIn,
      holidayCompensationRules,
    };

    const { minutesData, compensationType } = getCoffMinutes(parameterData);

    //If Overtime
    if (compensationType == compensationTypeEnum.Overtime) {
      await coffOvertimeMobile(
        attendanceData?.userMasterID || userMasterID,
        attendanceData?.AttendanceTransID || null,
        companyMasterID,
        attendancePolicy,
        skipMinutes,
        weekOffMinutes,
        normalDayMinutes,
        AttendanceDate,
        true,
        otAdded,
        monthlyOtCalType,
        weekoffType,
      );
    } else if (compensationType == compensationTypeEnum.AddLeave) {
      if (attendancePolicy.coffhalfday && attendancePolicy.cofffullday) {
        await addCoffMobile(
          attendanceData?.userMasterID || userMasterID,
          attendanceData?.AttendanceDate || AttendanceDate,
          companyMasterID,
          attendancePolicy,
          totalHours,
          attendanceData,
          otAdded,
          monthlyOtCalType,
          minutesData,
          weekoffType,
        );
      }
    } else if (compensationType == compensationTypeEnum.AddExtraDays) {
      await addExtraDaysMobile(
        attendancePolicy,
        attendanceData,
        totalHours,
        userMasterID,
        AttendanceDate,
        otAdded,
        monthlyOtCalType,
        minutesData,
        weekoffType,
      );
    }
  }
}

