// -------------------- get meal for log -----------------------

function getMealForLog(canteenMealsData = [], date, log) {
  if (canteenMealsData.length == 0 || !log) return null;

  const logTime = new Date(log.logDateTime);

  // Precalculate date objects once
  const meals = canteenMealsData
    .map((m) => ({
      ...m,
      start: new Date(`${date} ${m.startTime}`),
      end: new Date(`${date} ${m.endTime}`),
    }))
    .sort((a, b) => a.start - b.start);

  let previousMeal = null;
  let nextMeal = null;

  for (const meal of meals) {
    // 1. Inside current meal
    if (logTime >= meal.start && logTime < meal.end) {
      return meal;
    }

    // 2. Track previous meal (largest start < log)
    if (meal.start <= logTime) {
      previousMeal = meal;
    }

    // 3. First meal starting after log = next meal
    if (!nextMeal && meal.start > logTime) {
      nextMeal = meal;
    }
  }

  // priority: inside → previous → next
  return previousMeal || nextMeal || null;
}

async function addCanteenPenalty(
  canteenPenaltyType,
  canteenLogs = [],
  canteenMealsData = [],
  biometricIntegrationData = null,
  createBy,
  createByIp,
  transaction,
) {
  if (
    !canteenPenaltyType ||
    !canteenLogs.length ||
    !canteenMealsData.length ||
    !biometricIntegrationData
  )
    return;

  const bulkInsert = [];
  const bulkUpdate = [];
  const bulkDeletePenalty = [];

  const penaltyID = canteenPenaltyType.penaltyID;

  // ---------------- PREPARE LOOKUPS ---------------- //
  const mealsByCanteen = {};
  for (const m of canteenMealsData) {
    if (!mealsByCanteen[m.canteenDetailsId])
      mealsByCanteen[m.canteenDetailsId] = [];
    mealsByCanteen[m.canteenDetailsId].push(m);
  }

  const serialMap = {};
  (biometricIntegrationData.biometricSerialNo || []).forEach((sr, idx) => {
    serialMap[sr] = biometricIntegrationData.canteenDetailsId?.[idx] || null;
  });

  // ---------------- MAIN LOOP ---------------- //
  for (const [i, log] of canteenLogs.entries()) {
    const prevLog = i > 0 ? canteenLogs[i - 1] : null;

    // previous log time compare
    if (prevLog) {
      const diff =
        (new Date(log.logDateTime) - new Date(prevLog.logDateTime)) / 1000;
      if (diff <= 60) {
        if (log.empPenaltyID) bulkDeletePenalty.push(log.empPenaltyID);
        continue;
      }
    }

    const dateTime = asiaKolkataDateTime(log.logDateTime);
    const date = dateTime.slice(0, 10);

    const canteenDetailsId = serialMap[log.serialNumber] || null;
    if (!canteenDetailsId) continue;

    const mealsList = mealsByCanteen[canteenDetailsId] || [];

    const mealData = getMealForLog(mealsList, date, log);
    if (
      !mealData ||
      (+mealData.employeeShare <= 0 && +mealData.companyShare <= 0)
    )
      continue;

    let employeeShare = +mealData.employeeShare;
    let companyShare = +mealData.companyShare;

    // ---------------- FULL DAY CONDITION ---------------- //
    if (
      mealData.isApplicableOnFD &&
      mealData.mealType !== mealTypeEnum.BREAKFAST
    ) {
      const prevDate = new Date(date);
      prevDate.setDate(prevDate.getDate() - 1);
      const previousDate = asiaKolkataDateTime(prevDate).slice(0, 10);

      const attendanceData = await attendanceTransaction.findAll({
        where: {
          userMasterID: log.userMasterID,
          AttendanceDate: {
            [Sequelize.Op.in]: [previousDate, date],
          },
        },
        include: [{ model: shiftModel, attributes: ['shiftType'] }],
        attributes: ['AttendanceDate', 'fulldayhalfday'],
        transaction,
      });

      const currAtt = attendanceData.find((e) => e.AttendanceDate == date);
      const prevAtt = attendanceData.find(
        (e) => e.AttendanceDate == previousDate,
      );

      if (mealData.mealType === mealTypeEnum.LUNCH) {
        const lunchCondition =
          (!currAtt && !prevAtt) ||
          (prevAtt &&
            ((prevAtt.shift?.shiftType === ShiftTypeEnum.DAYSHIFT &&
              (!currAtt ||
                (currAtt &&
                  currAtt.shift?.shiftType !== ShiftTypeEnum.DAYSHIFT))) ||
              (prevAtt.shift?.shiftType === ShiftTypeEnum.NIGHTSHIFT &&
                prevAtt.fulldayhalfday != 1))) ||
          (currAtt && currAtt.shift?.shiftType !== ShiftTypeEnum.DAYSHIFT);

        if (lunchCondition) {
          employeeShare += companyShare;
          companyShare = 0;
        }
      }

      if (mealData.mealType === mealTypeEnum.DINNER) {
        const dinnerCondition =
          !currAtt ||
          (currAtt &&
            currAtt.shift?.shiftType === ShiftTypeEnum.DAYSHIFT &&
            currAtt.fulldayhalfday != 1);

        if (dinnerCondition) {
          employeeShare += companyShare;
          companyShare = 0;
        }
      }
    }

    // ---------------- Round Values ---------------- //
    const empAmount =
      employeeShare % 1 === 0 ? employeeShare : +employeeShare.toFixed(2);
    const cmpAmount =
      companyShare % 1 === 0 ? companyShare : +companyShare.toFixed(2);

    // ---------------- INSERT / UPDATE HANDLING ---------------- //
    if (!log.employeePenalty) {
      // NEW PENALTY
      bulkInsert.push({
        userMasterID: log.userMasterID,
        penaltyID,
        penaltyAmount: empAmount,
        companyShare: cmpAmount,
        penaltyDate: date,
        description: 'Biometric Punch : ' + dateTime,
        from: mealData.mealType,
        createBy,
        createByIp,

        // used for mapping later (NOT saved in DB)
        _canteenLogID: log.canteenLogsID,
      });
    } else {
      // UPDATE EXISTING PENALTY
      bulkUpdate.push({
        employeePenaltyID: log.empPenaltyID,
        penaltyAmount: empAmount,
        companyShare: cmpAmount,
        mealType: mealData.mealType,
        updateBy: createBy,
        updateByIp: createByIp,
        _canteenLogID: log.canteenLogsID,
      });
    }
  }

  // ---------------- EXECUTE BULK INSERT ---------------- //
  let inserted = [];
  if (bulkInsert.length > 0) {
    inserted = await EmployeePenalties.bulkCreate(bulkInsert, {
      returning: true,
      transaction,
    });
  }

  // ---------------- EXECUTE BULK UPDATE ---------------- //
  if (bulkUpdate.length > 0) {
    await Promise.all(
      bulkUpdate.map((u) =>
        EmployeePenalties.update(
          {
            penaltyAmount: u.penaltyAmount,
            companyShare: u.companyShare,
            mealType: u.mealType,
            updateBy: u.updateBy,
            updateByIp: u.updateByIp,
          },
          { where: { employeePenaltyID: u.employeePenaltyID }, transaction },
        ),
      ),
    );
  }

  // ---------- delete bulk penalty ------------ //

  if (bulkDeletePenalty.length > 0) {
    await EmployeePenalties.destroy({
      where: {
        employeePenaltyID: {
          [Sequelize.Op.in]: bulkDeletePenalty,
        },
      },
    });
  }

  // ---------------- MAP PENALTY IDs TO LOG IDs ---------------- //
  const penaltyMap = {};

  inserted.forEach((p, i) => {
    penaltyMap[bulkInsert[i]._canteenLogID] = p.employeePenaltyID;
  });

  bulkUpdate.forEach((u) => {
    penaltyMap[u._canteenLogID] = u.employeePenaltyID;
  });

  // ---------------- UPDATE CANTEEN LOGS TABLE ---------------- //
  const finalUpdates = Object.entries(penaltyMap).map(([logID, penaltyID]) => {
    return CanteenLogs.update(
      { empPenaltyID: penaltyID },
      { where: { canteenLogsID: logID }, transaction },
    );
  });

  if (finalUpdates.length > 0) {
    await Promise.all(finalUpdates);
  }

  return true;
}
function formatMemoryToShow() {
  const mem = process.memoryUsage();
  const toMB = (b) => (b / 1024 / 1024).toFixed(2) + ' MB';
  const toGB = (b) => (b / 1024 / 1024 / 1024).toFixed(2) + ' GB';

  return {
    rss: `${toMB(mem.rss)} | ${toGB(mem.rss)}`,
    heapTotal: `${toMB(mem.heapTotal)} | ${toGB(mem.heapTotal)}`,
    heapUsed: `${toMB(mem.heapUsed)} | ${toGB(mem.heapUsed)}`,
    external: `${toMB(mem.external)} | ${toGB(mem.external)}`,
    arrayBuffers: `${toMB(mem.arrayBuffers)} | ${toGB(mem.arrayBuffers)}`,
  };
}
