const fixAmount = (val) => {
  let num = Number(val);
  if (isNaN(num)) return 0;

  return num % 1 === 0 ? num : Number(num.toFixed(2));
};

async function applyTrackingFlags(userData = []) {
  try {
    if (!Array.isArray(userData) || userData.length === 0) return userData;

    return userData.map((user) => {
      const lastTrackingLog = user?.trackings?.[0];
      const tracking = user?.userTracking?.[0];
      const attendance = user?.attendanceTransactions?.[0];

      // Base defaults
      const hasAttendance = !!attendance;
      user.isTrackingUser = !!tracking;
      user.trackStatusLabel = '';

      if (hasAttendance) {
        if (attendance?.OutDateTime) {
          user.trackStatusLabel = trackStatusLabels.PUNCH_OUT;
        } else {
          if (!lastTrackingLog) {
            user.trackStatusLabel = trackStatusLabels.IN_OFFICE;
          } else {
            const geo = lastTrackingLog.geofence;
            if (geo == 'in') {
              user.trackStatusLabel = trackStatusLabels.IN_OFFICE;
            } else if (geo == 'out') {
              user.trackStatusLabel = trackStatusLabels.OUT_OFFICE;
            }
          }
        }
      } else {
        user.trackStatusLabel = trackStatusLabels.NOT_PUNCH_IN;
      }

      return user;
    });
  } catch (error) {
    throw new Error('Error in applyTrackingFlags: ' + error.message);
  }
}

