function getSafeSheetName(prefix, name) {
  const baseName = prefix ? `${prefix}_${name}` : name;

  return baseName
    .replace(/[\\\/\?\*\[\]:]/g, '') // Excel invalid chars
    .trim()
    .substring(0, 31);
}

function getUniqueSheetName(workbook, baseName, prefix = null) {
  let name = getSafeSheetName(prefix, baseName);
  let counter = 1;

  while (workbook.getWorksheet(name)) {
    const suffix = `_${counter}`;
    name = getSafeSheetName(
      prefix,
      baseName.substring(0, 31 - suffix.length) + suffix,
    );
    counter++;
  }

  return name;
}

function getEMIMonthByPayrollFrequency(
  payrollFrequency = PayrollFrequencyType.MONTHLY,
  EMIMonth,
  startDate = null,
  endDate = null,
) {
  // MONTHLY (YYYYMM)
  if (payrollFrequency === PayrollFrequencyType.MONTHLY && EMIMonth) {
    const monthStr = String(EMIMonth);
    const year = monthStr.slice(0, 4);
    const month = monthStr.slice(4, 6);

    return `${month_dict[month]} - ${year}`;
  }

  // NON-MONTHLY (Range based)
  if (!startDate || !endDate) return '';

  const year = String(endDate).slice(0, 4);
  const ranges = getDateRangesByType(payrollFrequency, year) || [];

  const range = ranges.find((r) => r.from === startDate && r.to === endDate);

  if (!range) return '';

  return `${range.title} (${moment(range.from).format('DD-MM-YYYY')} - ${moment(range.to).format('DD-MM-YYYY')})`;
}

