function getAllSingleDayLeaveForApproval(
  leave,
  createBy = null,
  createByIp = null,
  weekoffHoliday = [],
  attendancePolicy = null,
) {
  const leavetransaction = [];
  if (!leave) return leavetransaction;

  const weekoffSandwich =
    attendancePolicy?.sandwichLeave && attendancePolicy?.dataValues.w_sandwich;
  const holidaySandwich =
    attendancePolicy?.sandwichLeave && attendancePolicy?.dataValues.h_sandwich;

  const start = new Date(leave.FromDate);
  const end = new Date(leave.ToDate);

  while (start <= end) {
    const currentDate = start.toISOString().split('T')[0];

    const checkWeekoffHoliday = weekoffHoliday.find(
      (e) => e.date == currentDate,
    );

    // create NEW object each loop
    const obj = {
      ReferenceID: leave.UserLeaveApplicationID,
      LeaveTranId: leave.LeaveTranId,
      days: leave.LeaveDays >= 1 ? 1 : 0.5,
      date: currentDate,
      issandwichleave: 0,
      status: 1,
      createBy,
      createByIp,
    };

    if (checkWeekoffHoliday) {
      if (
        (weekoffSandwich && checkWeekoffHoliday.tableName === 'weekoff') ||
        (holidaySandwich && checkWeekoffHoliday.tableName === 'holiday')
      ) {
        obj.issandwichleave = 1;
        leavetransaction.push(obj);
      }

      start.setDate(start.getDate() + 1);
      continue;
    }

    leavetransaction.push(obj);

    start.setDate(start.getDate() + 1);
  }

  return leavetransaction;
}

// for auto approving leave
async function processAutoApproveLeave(
  leaveData = null,
  maxLimit,
  attendancePolicy = null,
  isCoffLeave = false,
  transaction,
  req,
) {
  if (!leaveData) return false;

  const weekoffHoliday = await weekoffHolidayTran.findAll({
    where: {
      userMasterID: leaveData.userMasterID,
      date: {
        [Sequelize.Op.between]: [leaveData.FromDate, leaveData.ToDate],
      },
      optionalHoliday: false,
    },
  });

  // date wise leave
  const leaveTransaction = getAllSingleDayLeaveForApproval(
    leaveData,
    leaveData.createBy,
    leaveData.createByIp,
    weekoffHoliday,
    attendancePolicy,
  );

  const daysSum = leaveTransaction.reduce((acc, obj) => acc + +obj.days, 0);

  // if days for leave is greater than the limit then not auto approve the leave
  if (maxLimit && daysSum > maxLimit) return false;

  // update leave
  leaveData.isAutoApproved = true;
  leaveData.authorizationStatus = 3;
  await leaveData.save({ transaction });

  // add approved leaves transanctions

  await UserLeaveTransaction.bulkCreate(leaveTransaction, { transaction });

  // execute only if coff type leave
  if (isCoffLeave) {
    let coffAvailableBalance = [];
    let allUsedCoffTrans = [];
    let coffTempAvailableBalance = [];

    for (const trans of leaveTransaction) {
      // check coff balance process
      const {
        allBalanceData: allBalanceDataTemp,
        remaining,
        usedTransactionLog,
      } = await checkCoffBalanceProcess(
        coffAvailableBalance,
        leaveData.userMasterID,
        trans.date,
        trans.days,
      );

      allUsedCoffTrans = [...allUsedCoffTrans, ...usedTransactionLog];

      coffTempAvailableBalance = [...allBalanceDataTemp];

      const filteredData = coffAvailableBalance.filter(
        (e) =>
          !coffTempAvailableBalance
            .map((c) => +c.LeaveBalTranId)
            .includes(+e.LeaveBalTranId),
      );

      // restore to allBalanceData
      coffAvailableBalance = [...filteredData, ...coffTempAvailableBalance];
    }

    // update coff available balance
    if (coffAvailableBalance.length > 0) {
      await Promise.all(
        coffAvailableBalance.map((data) =>
          HrLeaveBalance.update(
            {
              availBal: data.availBal,
            },
            {
              where: { LeaveBalTranId: data.LeaveBalTranId },
              transaction,
            },
          ),
        ),
      );
    }

    // add used coff transaction
    if (allUsedCoffTrans.length) {
      await UsedCoffTransaction.bulkCreate(allUsedCoffTrans, {
        user: req.userDetails,
        individualHooks: true,
        transaction,
      });
    }
  }

  // ---------------------------- send notification and E-mail------------------------------

  const notification = {
    title: 'Leave',
    body: 'Leave accepted successfully',
  };
  const data = {
    screen: 'leave',
  };

  sendNotification(leaveData.userMasterID, notification, data);

  const emailData = {
    NoOfDays: leaveData.LeaveDays,
    FromDate: leaveData.FromDate,
    ToDate: leaveData.ToDate,
    LeaveType: leaveTransaction.map((e) => e.LeaveTranId),
    acceptedUserList: [],
  };

  sendAcceptRejectMail(
    'Leave Accept Email Template',
    emailData,
    leaveData.userMasterID,
  );

  return true;
}

async function getParentChildCompany(companyID) {
  try {
    const currCompany = await companyMaster.findOne({
      where: { companyMasterID: companyID, status: 1 },
      attributes: ['companyMasterID', 'parentCompanyMasterID'],
      raw: true,
    });

    const companyMasterID = +currCompany.parentCompanyMasterID
      ? +currCompany.parentCompanyMasterID
      : +companyID;
    const allCompany = await companyMaster.findAll({
      raw: true,
      where: {
        [Sequelize.Op.or]: [
          { companyMasterID: companyMasterID },
          { parentCompanyMasterID: companyMasterID },
        ],
        status: 1,
      },
    });

    return allCompany;
  } catch (error) {
    throw error;
  }
}

// Paid leave hours calculation for salary
function calculatePaidLeaveHours(
  gross = 0,
  salaryStructureBaseoncal,
  dailyworkingminutes,
  salary_CalculationDays,
  paidLeaveMinutes,
) {
  let amount = 0;

  if (!dailyworkingminutes) return amount;

  if (salaryStructureBaseoncal == 'H')
    amount = (+gross / 60) * +paidLeaveMinutes;
  else if (salaryStructureBaseoncal == 'D')
    amount = (+gross / dailyworkingminutes) * +paidLeaveMinutes;
  else amount = (+gross / salary_CalculationDays) * +paidLeaveMinutes;

  return amount;
}

function getAmountByPresentDays(presentDays, slab) {
  if (!slab) return 0;

  if (presentDays <= slab.maxPresentDays) {
    return slab.amount;
  }

  if (
    presentDays > slab.maxPresentDays &&
    presentDays <= slab.maxPresentDays1
  ) {
    return slab.amount1;
  }

  return 0; // out of range
}

const stripHtml = (html) => {
  if (!html) return '';
  return html.replace(/<[^>]*>?/gm, '').trim();
};

function buildLeaveMap(arr, sumFields = []) {
  const map = new Map();

  for (const row of arr) {
    const leaveID = row?.hrLeaveType?.LeaveID || row?.LeaveID;
    if (!leaveID) continue;

    if (!map.has(leaveID)) {
      map.set(leaveID, Object.fromEntries(sumFields.map((f) => [f, 0])));
    }

    const bucket = map.get(leaveID);
    for (const field of sumFields) {
      bucket[field] += Number(row[field] || 0);
    }
  }

  return map;
}

async function getLeaveBalanceForSalarySlip(
  startDate,
  endDate,
  userMasterID,
  hrleaveTypes = [],
) {
  if (!userMasterID || !startDate || !endDate || !hrleaveTypes.length)
    return [];

  const start = new Date(startDate);
  const end = new Date(endDate);

  const startMonth = Number(
    `${start.getFullYear()}${String(start.getMonth() + 1).padStart(2, '0')}`,
  );
  const endMonth = Number(
    `${end.getFullYear()}${String(end.getMonth() + 1).padStart(2, '0')}`,
  );

  const sameMonth = startMonth === endMonth;

  /* ---------------- DB calls ---------------- */

  const [allAddedBalance, allLapseBalance, allEncashBalance, allUsedBalance] =
    await Promise.all([
      HrLeaveBalance.findAll({
        where: {
          userMasterID,
          YearMM: { [Sequelize.Op.lte]: endMonth },
        },
        include: [{ model: HrLeaveTypes, attributes: ['LeaveID'] }],
        attributes: [
          'YearMM',
          'LeaveAddNew',
          'OPBal',
          'expiryDate',
          'availBal',
        ],
      }),

      UserLeaveLapse.findAll({
        where: {
          userMasterID,
          LapseYearMonth: { [Sequelize.Op.lte]: endMonth },
        },
        include: [{ model: HrLeaveTypes, attributes: ['LeaveID'] }],
        attributes: ['LapseDays', 'LapseYearMonth'],
      }),

      LeaveEncashment.findAll({
        where: {
          userMasterID,
          status: 1,
          YYYYMM: { [Sequelize.Op.lte]: endMonth },
        },
        include: [{ model: HrLeaveTypes, attributes: ['LeaveID'] }],
        attributes: ['days', 'YYYYMM'],
      }),

      UserLeaveTransaction.findAll({
        where: {
          status: 1,
          date: { [Sequelize.Op.lte]: end },
        },
        include: [
          { model: UserLeave, where: { userMasterID }, attributes: [] },
          { model: HrLeaveTypes, attributes: ['LeaveID'] },
        ],
        attributes: ['days', 'date'],
      }),
    ]);

  /* ---------------- helpers ---------------- */

  const beforeMonthCheck = (val) =>
    sameMonth ? val < startMonth : val <= startMonth;

  const currentMonthCheck = (val) =>
    sameMonth ? val == startMonth : val == endMonth;

  //  ---------------- before split ----------------

  const before_addedBalance = allAddedBalance.filter((e) =>
    beforeMonthCheck(+e.YearMM),
  );
  const before_usedBalance = allUsedBalance.filter(
    (e) => new Date(e.date) < start,
  );
  const before_lapseBalance = allLapseBalance.filter((e) =>
    beforeMonthCheck(+e.LapseYearMonth),
  );
  const before_encashBalance = allEncashBalance.filter((e) =>
    beforeMonthCheck(+e.YYYYMM),
  );
  const before_expiredBalance = before_addedBalance.filter(
    (e) => e.expiryDate && new Date(e.expiryDate) < start,
  );

  // ------------------------ current split -------------

  const current_addedBalance = allAddedBalance.filter((e) =>
    currentMonthCheck(+e.YearMM),
  );
  const current_usedBalance = allUsedBalance.filter(
    (e) => new Date(e.date) >= start && new Date(e.date) <= end,
  );
  const current_lapseBalance = allLapseBalance.filter((e) =>
    currentMonthCheck(+e.LapseYearMonth),
  );
  const current_encashBalance = allEncashBalance.filter((e) =>
    currentMonthCheck(+e.YYYYMM),
  );
  const current_expiredBalance = allAddedBalance.filter(
    (e) =>
      e.expiryDate &&
      new Date(e.expiryDate) >= start &&
      new Date(e.expiryDate) <= end,
  );

  /* ---------------- maps ---------------- */

  const beforeAddMap = buildLeaveMap(before_addedBalance, [
    'LeaveAddNew',
    'OPBal',
  ]);
  const beforeUsedMap = buildLeaveMap(before_usedBalance, ['days']);
  const beforeLapseMap = buildLeaveMap(before_lapseBalance, ['LapseDays']);
  const beforeEncashMap = buildLeaveMap(before_encashBalance, ['days']);
  const beforeExpiredMap = buildLeaveMap(before_expiredBalance, ['availBal']);

  const currentAddMap = buildLeaveMap(current_addedBalance, [
    'LeaveAddNew',
    'OPBal',
  ]);
  const currentUsedMap = buildLeaveMap(current_usedBalance, ['days']);
  const currentLapseMap = buildLeaveMap(current_lapseBalance, ['LapseDays']);
  const currentEncashMap = buildLeaveMap(current_encashBalance, ['days']);
  const currentExpiredMap = buildLeaveMap(current_expiredBalance, ['availBal']);

  /* ---------------- final calc ---------------- */

  const finalData = [];

  for (const value of hrleaveTypes) {
    const leaveID = value.LeaveID;

    const beforeAdd =
      (beforeAddMap.get(leaveID)?.LeaveAddNew || 0) +
      (beforeAddMap.get(leaveID)?.OPBal || 0);

    const beforeUsed = beforeUsedMap.get(leaveID)?.days || 0;
    const beforeLapse = beforeLapseMap.get(leaveID)?.LapseDays || 0;
    const beforeEncash = beforeEncashMap.get(leaveID)?.days || 0;
    const beforeExpired = beforeExpiredMap.get(leaveID)?.availBal || 0;

    const finalOpening =
      beforeAdd - beforeUsed - beforeLapse - beforeEncash - beforeExpired;

    const currentAdded =
      (currentAddMap.get(leaveID)?.LeaveAddNew || 0) +
      (currentAddMap.get(leaveID)?.OPBal || 0);

    const currentUsed = currentUsedMap.get(leaveID)?.days || 0;
    const currentLapse = currentLapseMap.get(leaveID)?.LapseDays || 0;
    const currentEncash = currentEncashMap.get(leaveID)?.days || 0;
    const currentExpired = currentExpiredMap.get(leaveID)?.availBal || 0;

    const finalUtilise =
      currentUsed + currentLapse + currentEncash + currentExpired;

    const finalClosing = finalOpening + currentAdded - finalUtilise;

    finalData.push({
      leaveName: value.LeaveName,
      opening: roundOffLeaveBalance(finalOpening),
      earned: roundOffLeaveBalance(currentAdded),
      utilise: roundOffLeaveBalance(finalUtilise),
      closing: roundOffLeaveBalance(finalClosing),
    });
  }

  return finalData;
}
