function parseYearMonth(value) {
  if (!value) return '';

  // Already YYYYMM
  if (/^\d{6}$/.test(value)) {
    return value;
  }

  // "February 2026"
  const m = moment(value, 'MMMM YYYY', true);
  if (m.isValid()) {
    return m.format('YYYYMM');
  }

  return '';
}

function formatYearMonth(yearMonth) {
  if (!yearMonth || yearMonth.length !== 6) return yearMonth;

  const year = yearMonth.substring(0, 4);
  const month = yearMonth.substring(4, 6);

  const monthNames = [
    'January',
    'February',
    'March',
    'April',
    'May',
    'June',
    'July',
    'August',
    'September',
    'October',
    'November',
    'December',
  ];

  const monthIndex = Number(month) - 1;
  if (monthIndex < 0 || monthIndex > 11) return yearMonth;

  return `${monthNames[monthIndex]} ${year}`;
}

async function policy_Scope({
  model,
  primaryKey,
  column,
  newIDs = [],
  user,
  transaction,
}) {
  try {
    const existing = await model.findAll({
      where: primaryKey,
      attributes: [column],
      transaction,
    });

    const existingIDs = existing.map((e) => +e[column]);

    const toDelete = existingIDs.filter((id) => !newIDs.includes(id));
    const toAdd = newIDs.filter((id) => !existingIDs.includes(+id));

    if (toDelete.length) {
      await model.destroy({
        where: {
          ...primaryKey,
          [column]: toDelete,
        },
        individualHooks: true,
        user,
        transaction,
      });
    }

    if (toAdd.length) {
      await model.bulkCreate(
        toAdd.map((id) => ({
          ...primaryKey,
          [column]: id,
        })),
        { user, transaction },
      );
    }
  } catch (error) {
    error.message = `[${model?.name || 'PolicyScope'}] scope update failed: ${error.message}`;
    throw error; // ensures transaction rollback
  }
}

async function bulkCreatePolicyScope({
  scope,
  selectedScope,
  ids,
  model,
  policyIdKey,
  scopeIdKey,
  policyId,
  req,
  transaction,
}) {
  try {
    if (scope !== selectedScope || !ids?.length) return;

    const rows = ids.map((id) => ({
      [policyIdKey]: policyId,
      [scopeIdKey]: id,
    }));

    await model.bulkCreate(rows, {
      user: req.userDetails,
      transaction,
    });
  } catch (error) {
    // Add context for easier debugging/logging
    error.message = `[${model?.name || 'PolicyScope'}] bulkCreate failed: ${error.message}`;

    // Re-throw so caller / transaction handler can rollback
    throw error;
  }
}

