function get_Daily_Monthly_Hrs(
  user_salaryPolicy,
  monday,
  empjoining,
  substractWeekoff,
  weekoffCount,
  allWeekoff,
  allHoliday,
  attendanceData,
  shiftTime,
  weekoffCountForHourly = 0,
) {
  const obj = { monthly_Workingminutes: 0, daily_workingminutes: 0 };

  if (!user_salaryPolicy) return obj;

  // --- Helper: daily minutes when no dailyFixhours override ---
  const getDynamicDailyMinutes = () => {
    const lastAttendance =
      attendanceData?.length > 0
        ? attendanceData[attendanceData.length - 1]
        : null;
    const hrs = lastAttendance
      ? +lastAttendance.Shifthrs
      : +shiftTime?.totalhours || 8;
    return hrs * 60;
  };

  // --- Helper: daily minutes, respecting dailyFixhours if set ---
  const getDailyMinutes = () =>
    user_salaryPolicy.dailyFixhours
      ? Number(user_salaryPolicy.dailyFixhours) * 60
      : getDynamicDailyMinutes();

  if (user_salaryPolicy.monthlyFixhours) {
    // Monthly hours fixed by policy
    obj.monthly_Workingminutes = Number(user_salaryPolicy.monthlyFixhours) * 60;
    obj.daily_workingminutes = getDailyMinutes();
    return obj;
  }

  // Monthly hours derived from days * daily rate
  let tempMonthDays = monday;
  const calculationAct = empjoining.salaryCalculationAct;

  if (substractWeekoff && ['F', 'W'].includes(calculationAct)) {
    const finalWeekoffCount =
      +weekoffCount > 0
        ? +weekoffCount
        : weekoffCountForHourly > 0
          ? weekoffCountForHourly
          : allWeekoff.reduce((acc, o) => acc + +o.value, 0);

    tempMonthDays -= finalWeekoffCount;

    if (calculationAct === 'W') {
      const finalHolidayCount = allHoliday.reduce(
        (acc, o) => acc + +o.value,
        0,
      );
      tempMonthDays -= finalHolidayCount;
    }
  }

  obj.daily_workingminutes = getDailyMinutes();
  obj.monthly_Workingminutes = obj.daily_workingminutes * tempMonthDays;

  return obj;
}

function calculateAttendancePenalties(attendanceData) {
  const penalties = {
    penaltyDays: 0,
    penaltyMin: 0,
    penaltyAmount: 0,
    penaltyPercent: 0,
    penaltyMonthlyPercent: 0,
  };

  const validTypes = new Set([
    LCEGPenaltyTypeEnum.MINUTE,
    LCEGPenaltyTypeEnum.AMOUNT,
    LCEGPenaltyTypeEnum.DAY,
    LCEGPenaltyTypeEnum.PERCENT,
    LCEGPenaltyTypeEnum.MONTHLY_PERCENT,
  ]);

  const penaltyMap = {
    [LCEGPenaltyTypeEnum.MINUTE]: (v) => (penalties.penaltyMin += +v),
    [LCEGPenaltyTypeEnum.AMOUNT]: (v) => (penalties.penaltyAmount += +v),
    [LCEGPenaltyTypeEnum.DAY]: (v) => (penalties.penaltyDays += +v),
    [LCEGPenaltyTypeEnum.PERCENT]: (v) => (penalties.penaltyPercent += +v),
    [LCEGPenaltyTypeEnum.MONTHLY_PERCENT]: (v) =>
      (penalties.penaltyMonthlyPercent += +v),
  };

  const keys = ['Panalty', 'goEarlyPanalty'];

  for (let i = 0; i < attendanceData.length; i++) {
    const e = attendanceData[i];

    for (let j = 0; j < keys.length; j++) {
      const key = keys[j];

      const value = +e[key];
      const type = e[key + 'Deduction'];

      if (!value || !validTypes.has(type)) continue;

      if (penaltyMap[type]) {
        penaltyMap[type](value);
      }
    }
  }

  return penalties;
}

// ==============================
// HELPERS (GLOBAL / OUTSIDE)
// ==============================

const createSalaryStructure = () => ({
  earning: [],
  gross: [],
  employeeDeduction: [],
  extraEarning: [],
  netPay: [],
  employerDeduction: [],
  ctc: [],
  createBy: null,
  createdAt: null,
  salaryCalculationDays: null,
  otMinutes: null,
});

const getOrCreate = (map, userId) => {
  if (!map.has(userId)) {
    map.set(userId, createSalaryStructure());
  }
  return map.get(userId);
};

const pushItem = (arr, data) => arr.push(data);

const handleSpecialHeads = ({
  payheadMasterId,
  payheadName,
  salaryFieldSrNo,
  salaryFieldSide,
  considerIn,
  EmployeeSalaryAmount,
  actualAmount,
  master,
  actualName,
  salaryFieldId,
  transaction,
}) => {
  const mapping = {
    [payheadMasterIdsMapping.CTC]: 'ctc',
    [payheadMasterIdsMapping.GROSS]: 'gross',
    [payheadMasterIdsMapping.NETSALARY]: 'netPay',
  };

  const key = mapping[payheadMasterId];
  if (!key) return;

  transaction[key].push({
    payheadName,
    salaryFieldSrNo,
    salaryFieldSide,
    EmployeeSalaryAmount,
    considerIn,
    payheadMasterId,
    actualName,
    salaryFieldId,
  });

  if (master) {
    master[key].push({
      payheadName,
      salaryFieldSrNo,
      salaryFieldSide,
      EmployeeSalaryAmount: actualAmount,
      considerIn,
      payheadMasterId,
      actualName,
      salaryFieldId,
    });
  }
};

// ==============================
// MAIN FUNCTION
// ==============================

async function getSalary_SalaryMaster_DataMap(
  userIds = [],
  month,
  includeOt = false,
) {
  const salaryMasterMap = new Map();
  const salaryTransactionMap = new Map();

  // ✅ Early return
  if (!userIds.length) {
    return { salaryMasterMap, salaryTransactionMap };
  }

  const includeModel = [
    {
      model: HRSalaryMasterFields,
      as: 'HSM',
      include: [
        {
          model: GradeSalaryStructure,
          as: 'GSS',
          include: [
            { model: GradeStructure, attributes: ['baseOnCalculation'] },
            {
              model: HRSalaryFields,
              as: 'HSF',
              include: [
                {
                  model: Payheadmaster,
                  as: 'PHM',
                  attributes: ['payheadName'],
                },
              ],
              attributes: [
                'payheadMasterId',
                'salaryFieldSide',
                'salaryFieldSrNo',
                'considerIn',
                'payheadDisplayName',
              ],
            },
          ],
          attributes: ['salaryFieldID', 'gradeStructureID', 'salaryfieldindex'],
        },
      ],
      attributes: ['gradeSalaryStructureID', 'EmployeeSalaryAmount'],
    },
    {
      model: UserMaster,
      as: 'createByUser',
      attributes: ['displayName'],
    },
    {
      required: false,
      model: deposit,
      attributes: ['depositCategoryID', 'amount'],
      include: [
        {
          model: depositcategory,
          attributes: [['depositcategoryname', 'name']],
        },
      ],
    },
    {
      required: false,
      model: deposit,
      as: 'depositPay',
      attributes: ['depositCategoryID', 'amount'],
      include: [
        {
          model: depositcategory,
          attributes: [['depositcategoryname', 'name']],
        },
      ],
    },
    {
      required: false,
      model: EmployeePenalty,
      attributes: ['penaltyAmount', 'penaltyID'],
      include: [
        {
          model: Penalty,
          as: 'penalty',
          attributes: ['penaltyName'],
        },
      ],
    },
    {
      required: false,
      model: Employeeincentive,
      attributes: ['amount', 'IncentivetypeID'],
      include: [
        {
          model: Incentivetype,
          as: 'IncType',
          attributes: [
            ['incentivetypename', 'name'],
            ['inc_type_displayName', 'displayName'],
            ['IncentivetypeID', 'id'],
          ],
        },
      ],
    },
  ];

  if (includeOt) {
    includeModel.push({
      required: false,
      model: overTimeCalculationMain,
      attributes: ['overtimehrs', 'ratio'],
    });
  }

  const salaryData = await HRSalaryTrasaction.findAll({
    where: {
      userMasterID: {
        [Sequelize.Op.in]: userIds,
      },
      salaryYYYYMM: month,
    },
    include: includeModel,
    attributes: [
      'EmployeeSalaryAmount',
      'salaryYYYYMM',
      'userMasterID',
      'SalaryCalcOnDays',
      'createBy',
      'calculatedOn',
      'createdAt',
    ],
    order: [
      // Order by salaryfieldindex in GradeSalaryStructure
      [
        { model: HRSalaryMaster, as: 'HSM' },
        { model: GradeSalaryStructure, as: 'GSS' },
        'salaryfieldindex',
        'ASC',
      ],

      // Order by payheadName in Payheadmaster
      [
        { model: HRSalaryMaster, as: 'HSM' },
        { model: GradeSalaryStructure, as: 'GSS' },
        { model: HRSalaryFields, as: 'HSF' },
        { model: Payheadmaster, as: 'PHM' },
        'payheadName',
        'ASC',
      ],
    ],
  });

  const speacialHeads = [
    payheadMasterIdsMapping.CTC,
    payheadMasterIdsMapping.GROSS,
    payheadMasterIdsMapping.NETSALARY,
  ];

  const avoidIds = [
    payheadMasterIdsMapping.INCENTIVE,
    payheadMasterIdsMapping.PENALTY,
    payheadMasterIdsMapping.DEPOSIT_DEDUCTION,
    payheadMasterIdsMapping.DEPOSIT_PAY,
  ];

  for (const salary of salaryData) {
    const uid = +salary.userMasterID;

    const master = getOrCreate(salaryMasterMap, uid);
    const transaction = getOrCreate(salaryTransactionMap, uid);

    if (!transaction.createBy && salary.createByUser?.displayName) {
      transaction.createBy = salary.createByUser?.displayName || null;
    }

    if (!transaction.createdAt && salary.createdAt) {
      transaction.createdAt = moment(salary.createdAt).format(
        'DD-MM-YYYY hh:mm A',
      );
    }

    if (transaction.salaryCalculationDays == null) {
      transaction.salaryCalculationDays = salary.SalaryCalcOnDays || 0;
    }

    // Extract once (performance)
    const HSM = salary.HSM;
    const GSS = HSM?.GSS;
    const HSF = GSS?.HSF;

    const payheadMasterId = HSF?.payheadMasterId;
    const salaryFieldSrNo = HSF?.salaryFieldSrNo;
    const salaryFieldSide = HSF?.salaryFieldSide;
    const considerIn = HSF?.considerIn;
    const salaryFieldId = GSS.salaryFieldID;

    const EmployeeSalaryAmount = salary.EmployeeSalaryAmount || 0;
    const actualAmount = HSM?.EmployeeSalaryAmount || 0;

    const payheadName =
      HSF?.payheadDisplayName?.trim() || HSF?.PHM?.payheadName;

    const employeeIncentives = salary.employeeincentives || [];
    const employeePenalties = salary.employeePenalties || [];
    const employeeDeposites = salary.deposits || [];
    const employeeDepositPay = salary.depositPay || [];
    const otData = salary.OverTimeCalculationMains?.[0] || null;
    const actualName = HSF?.PHM?.payheadName || null;

    if (otData) transaction.otMinutes = otData.overtimehrs || 0;

    // ==============================
    // Special Heads
    // ==============================
    if (speacialHeads.includes(payheadMasterId)) {
      handleSpecialHeads({
        payheadMasterId,
        payheadName,
        salaryFieldSrNo,
        salaryFieldSide,
        considerIn,
        EmployeeSalaryAmount,
        actualAmount,
        master,
        transaction,
        actualName,
        salaryFieldId,
        transaction,
      });
      continue;
    }

    if (!avoidIds.includes(payheadMasterId)) {
      // ==============================
      // Earnings
      // ==============================
      if (salaryFieldSrNo === salaryFieldSrNoFields.EARNING) {
        const isNet = considerIn === salaryConsiderInEnum.NET_SALARY;

        if (!isNet) {
          if (
            !default_payheadMasterIds.includes(payheadMasterId) ||
            EmployeeSalaryAmount > 0
          ) {
            pushItem(transaction.earning, {
              payheadName,
              salaryFieldSrNo,
              salaryFieldSide,
              EmployeeSalaryAmount,
              considerIn,
              payheadMasterId,
              actualName,
              salaryFieldId,
            });

            if (!default_payheadMasterIds.includes(payheadMasterId)) {
              pushItem(master.earning, {
                payheadName,
                salaryFieldSrNo,
                salaryFieldSide,
                EmployeeSalaryAmount: actualAmount,
                considerIn,
                payheadMasterId,
                actualName,
                salaryFieldId,
              });
            }
          }
        } else {
          if (EmployeeSalaryAmount > 0) {
            pushItem(transaction.extraEarning, {
              payheadName,
              salaryFieldSrNo,
              salaryFieldSide,
              EmployeeSalaryAmount,
              considerIn,
              payheadMasterId,
              actualName,
              salaryFieldId,
            });
          }

          if (actualAmount > 0) {
            pushItem(master.extraEarning, {
              payheadName,
              salaryFieldSrNo,
              salaryFieldSide,
              EmployeeSalaryAmount: actualAmount,
              considerIn,
              payheadMasterId,
              actualName,
              salaryFieldId,
            });
          }
        }
      }

      // ==============================
      // Deductions
      // ==============================
      if (salaryFieldSrNo === salaryFieldSrNoFields.EMPLOYEE_DEDUCTION) {
        if (EmployeeSalaryAmount > 0) {
          pushItem(transaction.employeeDeduction, {
            payheadName,
            salaryFieldSrNo,
            salaryFieldSide,
            EmployeeSalaryAmount,
            considerIn,
            payheadMasterId,
            actualName,
            salaryFieldId,
          });
        }

        if (actualAmount > 0) {
          pushItem(master.employeeDeduction, {
            payheadName,
            salaryFieldSrNo,
            salaryFieldSide,
            EmployeeSalaryAmount: actualAmount,
            considerIn,
            payheadMasterId,
            actualName,
            salaryFieldId,
          });
        }
      }

      // Employer Deductions ---------------------

      if (salaryFieldSrNo === salaryFieldSrNoFields.EMPLOYER_DEDUCTION) {
        if (EmployeeSalaryAmount > 0) {
          pushItem(transaction.employerDeduction, {
            payheadName,
            salaryFieldSrNo,
            salaryFieldSide,
            EmployeeSalaryAmount,
            considerIn,
            payheadMasterId,
            actualName,
            salaryFieldId,
          });
        }

        if (actualAmount > 0) {
          pushItem(master.employerDeduction, {
            payheadName,
            salaryFieldSrNo,
            salaryFieldSide,
            EmployeeSalaryAmount: actualAmount,
            considerIn,
            payheadMasterId,
            actualName,
            salaryFieldId,
          });
        }
      }
    }

    // ==============================
    // Penalties
    // ==============================
    for (const penalty of employeePenalties) {
      const existing = transaction.employeeDeduction.find(
        (p) => p.penaltyID === penalty.penaltyID,
      );

      if (existing) {
        existing.EmployeeSalaryAmount += +penalty.penaltyAmount;
      } else {
        transaction.employeeDeduction.push({
          payheadName: penalty.penalty?.penaltyName || payheadName,
          EmployeeSalaryAmount: +penalty.penaltyAmount,
          penaltyID: penalty.penaltyID,
          salaryFieldId,
        });
      }
    }

    // ==============================
    // Incentives
    // ==============================
    for (const incentive of employeeIncentives) {
      const name =
        incentive.IncType?.dataValues?.displayName ||
        incentive.IncType?.dataValues?.name;

      const existing = transaction.earning.find(
        (i) => i.IncentivetypeID === incentive.IncentivetypeID,
      );

      if (existing) {
        existing.EmployeeSalaryAmount += +incentive.amount;
      } else {
        transaction.earning.push({
          payheadName: name,
          EmployeeSalaryAmount: +incentive.amount,
          IncentivetypeID: incentive.IncentivetypeID,
          salaryFieldId,
        });
      }
    }

    // ==============================
    // Deposits
    // ==============================
    for (const deposit of employeeDeposites) {
      const existing = transaction.employeeDeduction.find(
        (p) => p.depositCategoryID === deposit.depositCategoryID,
      );

      if (existing) {
        existing.EmployeeSalaryAmount += +deposit.amount;
      } else {
        transaction.employeeDeduction.push({
          payheadName: deposit.depositcategory?.dataValues?.name || payheadName,
          EmployeeSalaryAmount: +deposit.amount,
          depositCategoryID: deposit.depositCategoryID,
          salaryFieldId,
        });
      }
    }

    // Deposits PAY
    // ==============================
    for (const deposit of employeeDepositPay) {
      const existing = transaction.earning.find(
        (p) => p.depositCategoryID === deposit.depositCategoryID,
      );

      if (existing) {
        existing.EmployeeSalaryAmount += +deposit.amount;
      } else {
        transaction.earning.push({
          payheadName: deposit.depositcategory?.dataValues?.name || payheadName,
          EmployeeSalaryAmount: +deposit.amount,
          depositCategoryID: deposit.depositCategoryID,
          salaryFieldId,
        });
      }
    }
  }

  return { salaryMasterMap, salaryTransactionMap };
}

// Reusable helper: gets filtered/deduped AttendanceTransIDs efficiently,
// then hydrates full model instances (with associations) for just those IDs.
async function getOptimizedAttendanceTransactions({
  userIds,
  startDate,
  endDate,
  currentDate,
  includeArray = null, // pass null/undefined to skip includes (used for "before" query)
}) {
  if (!userIds?.length) return [];

  const matchingIds = await sequelize.query(
    `
    WITH ranked AS (
      SELECT
        "AttendanceTransID",
        "userMasterID",
        "AttendanceDate",
        "roundOffMinutes",
        "OutDateTime",
        MAX("roundOffMinutes") OVER (
          PARTITION BY "userMasterID", "AttendanceDate"
        ) AS max_round_off,
        COUNT("roundOffMinutes") OVER (
          PARTITION BY "userMasterID", "AttendanceDate"
        ) AS round_off_count,
        ROW_NUMBER() OVER (
          PARTITION BY "userMasterID", "AttendanceDate", "roundOffMinutes"
          ORDER BY "AttendanceTransID" ASC
        ) AS row_num
      FROM "attendanceTransactions"
      WHERE "userMasterID" IN (:userIds)
        AND "AttendanceDate" BETWEEN :startDate AND :endDate
    )
    SELECT "AttendanceTransID"
    FROM ranked
    WHERE row_num = 1
      AND (
        "roundOffMinutes" = max_round_off
        OR (round_off_count = 0 AND "roundOffMinutes" IS NULL)
      )
      AND (
        "AttendanceDate" = :currentDate
        OR ("AttendanceDate" != :currentDate AND "OutDateTime" IS NOT NULL)
      )
    `,
    {
      replacements: { userIds, startDate, endDate, currentDate },
      type: Sequelize.QueryTypes.SELECT,
    },
  );

  const idList = matchingIds.map((row) => row.AttendanceTransID);
  if (idList.length === 0) return [];

  return attendanceTransaction.findAll({
    where: {
      AttendanceTransID: { [Sequelize.Op.in]: idList },
    },
    include: includeArray,
    order: [
      ['userMasterID', 'ASC'],
      ['AttendanceDate', 'ASC'],
    ],
  });
}

// build nested map for coff and extra days
function buildNestedMap(rows, dateField, daysField) {
  const map = new Map();

  for (const row of rows) {
    const userMasterID = +row.userMasterID;
    const from = row.From ?? 'WH'; // null/undefined -> 'WH'
    const date = row[dateField];
    const days = +row[daysField] || 0;

    if (!map.has(userMasterID)) {
      map.set(userMasterID, new Map());
    }
    const fromMap = map.get(userMasterID);

    if (!fromMap.has(from)) {
      fromMap.set(from, new Map());
    }
    const dateMap = fromMap.get(from);

    if (dateMap.has(date)) {
      // Same user + from + date already exists -> add days, keep rest of row as-is
      const existing = dateMap.get(date);
      existing[daysField] = (+existing[daysField] || 0) + days;
    } else {
      // Store a shallow clone so we don't mutate the original Sequelize row in place
      dateMap.set(date, { ...(row.dataValues ?? row), [daysField]: days });
    }
  }

  return map;
}

async function attendanceCalculationLatest(
  users = [],
  month,
  AllHrLeaveTypes = [],
  req,
  returnType,
  isStream = false,
  res,
) {
  const allData = [];
  const onlyLeaveDataMapUserWise = new Map();

  if (!users || (Array.isArray(users) && !users.length) || !month)
    return { allData, onlyLeaveDataMapUserWise };

  try {
    const userMap = new Map();
    const dateRangeGroups = new Map();
    const whDateRangeGroups = new Map();
    const allShiftIds = new Set();
    const dateRangeGroupsForOT = new Map();
    const salaryCalculatedUserIds = new Set();
    const forCoffExtraDatesMap = new Map();

    const currentDate = moment().format('YYYY-MM-DD');

    const companyMasterId = users?.[0].companyMasterId;

    const salaryEligibilityDocList = await SalaryEligibilityDocument.findAll({
      where: {
        companyMasterID: companyMasterId,
      },
      attributes: ['documentListID'],
      include: [
        { model: DocumentList, as: 'document', attributes: ['documentName'] },
      ],
    });

    // ---------------------- Build employee-month pairs for check salary master ----------------
    const employeeMonthPairs = [];

    const beforeWeekoffDatesMap = new Map();

    for (const user of users) {
      const userMasterID = +user.userMasterID;
      const companyMasterID = user.companyMasterId;

      let left = false;
      let notJoin = false;
      let calculateFixMonthDays = true;
      let FNF = false;
      let joiningFlag = true;
      let start_date;
      let end_date;

      // Attendance calculation data
      const userAttnCalData = user.hrLeaveMonthlyTrans || [];

      const attendanceVerify = userAttnCalData?.[0]?.verified || null;
      const attendanceVerifyFlag = attendanceVerify == 1 ? true : false;

      const year = String(month).slice(0, 4);
      const Month = String(month).slice(4, 6);
      let monday = daysInMonth(Month, year);

      const monthName = month_dict[Month] + ' ' + year;

      //--------------------------Employee salary policy ----------------------

      const user_salaryPolicy =
        user.employeeSalaryPolicies?.[0]?.salaryPolicy || null;

      const calculationType =
        user_salaryPolicy?.salarycalculationBasedon || null;
      const overtimeAdded = user_salaryPolicy?.overtimeAdded || null;
      let salaryPolicyMonthDays = null;
      const employeeshiftIds = user.employeeShifts?.[0]?.shiftsID || [];

      const joining = user.employeeJoiningDetails?.[0];
      const joiningDate = joining?.joiningDate;
      const leavingDate = joining?.leavingDate;

      joiningFlag = Boolean(joining);

      if (
        calculationType == SalaryPolicyTypeEnum.HOUR_WISE &&
        !user_salaryPolicy.monthlyFixhours &&
        !user_salaryPolicy.dailyFixhours
      ) {
        employeeshiftIds.forEach((item) => {
          allShiftIds.add(+item);
        });
      }

      // set empty
      user.employeeSalaryPolicies = [];

      if (attendanceVerifyFlag) {
        const verifiedData = userAttnCalData?.[0];

        const salarySlips = user.hrSalarySlips?.[0] || null;

        if (salarySlips) {
          // add in salary calculation
          salaryCalculatedUserIds.add(userMasterID);
        } else {
          // for salary structure

          employeeMonthPairs.push({
            userMasterID: userMasterID,
            salaryMonth: month,
          });
        }

        const start = verifiedData?.monthstartdate;
        const end = verifiedData?.monthenddate;

        // for extra days and coff
        if (start && end) {
          const key = `${start}_${end}`;

          if (!forCoffExtraDatesMap.has(key)) {
            forCoffExtraDatesMap.set(key, {
              startDate: start,
              endDate: end,
              userIds: [],
            });
          }
          forCoffExtraDatesMap.get(key).userIds.push(userMasterID);
        }

        if (leavingDate && leavingDate >= start && leavingDate <= end) {
          FNF = true;
        }

        if (calculationType == SalaryPolicyTypeEnum.HOUR_WISE) {
          start_date = userAttnCalData?.[0]?.monthstartdate;
          end_date = userAttnCalData?.[0]?.monthenddate;

          // ---- only for weekoff/holiday ---------------

          if (start_date && end_date) {
            const key = `${start_date}_${end_date}`;

            if (!whDateRangeGroups.has(key)) {
              whDateRangeGroups.set(key, {
                startDate: start_date,
                endDate: end_date,
                userIds: [],
              });
            }
            whDateRangeGroups.get(key).userIds.push(userMasterID);
          }
        }

        const object = {
          userData: user,
          attendanceVerify: attendanceVerifyFlag,
          salaryPolicyMonthDays,
          left,
          notJoin,
          calculateFixMonthDays,
          FNF,
          joiningFlag,
          start_date: start,
          end_date: end,
          calculationType,
          overtimeAdded,
          monday: verifiedData?.MonDays,
          employeeshiftIds,
          monthName,
          user_salaryPolicy,
        };

        userMap.set(userMasterID, object);
        continue;
      }

      // SALARY POLICY MONTH DAYS
      if (
        calculationType != SalaryPolicyTypeEnum.HOUR_WISE &&
        user_salaryPolicy?.MonthDaysType == MonthDaysTypeEnum.FIX &&
        user_salaryPolicy?.fixDays
      ) {
        salaryPolicyMonthDays = user_salaryPolicy.fixDays;
      }

      // gete start date and end date form from salary policy
      const { start_date: startDate, end_date: endDate } =
        getSalaryCycleDateByMonth(user_salaryPolicy, month);

      start_date = startDate;
      end_date = endDate;

      monday = daysInMonth(start_date.slice(5, 7), start_date.slice(0, 4));

      // ---- Joining Logic ----
      if (joiningDate) {
        if (joiningDate > end_date) {
          notJoin = true;
        } else if (joiningDate > start_date) {
          start_date = joiningDate;
        }
      }

      // ---- Leaving Logic ----
      if (leavingDate) {
        if (leavingDate < start_date) {
          left = true;
        } else if (leavingDate <= end_date) {
          end_date = leavingDate;
          FNF = true;
          calculateFixMonthDays = false;
        }
      }

      // ---- Final Validation ----
      if (start_date > end_date || left || notJoin) {
        start_date = '';
        end_date = '';
        joiningFlag = false;
      }

      // set start date and enddate

      // ----------------------------- for fix weekoff ----------------------------
      const weekoffPolicy =
        (user.employeeWeekOffs || 0).find(
          (e) =>
            e.applicableDate <= end_date &&
            (e.endDate >= end_date || !e.endDate),
        )?.weekoff || null;

      if (start_date && end_date) {
        const key = `${start_date}_${end_date}`;
        if (!dateRangeGroups.has(key)) {
          dateRangeGroups.set(key, {
            startDate: start_date,
            endDate: end_date,
            userIds: [],
            beforeUserIds: [],
          });
        }
        dateRangeGroups.get(key).userIds.push(userMasterID);

        // ------------- for coff extra days ---------------

        if (!forCoffExtraDatesMap.has(key)) {
          forCoffExtraDatesMap.set(key, {
            startDate: start_date,
            endDate: end_date,
            userIds: [],
          });
        }
        forCoffExtraDatesMap.get(key).userIds.push(userMasterID);

        // ---- only for weekoff/holiday ---------------

        if (!whDateRangeGroups.has(key)) {
          whDateRangeGroups.set(key, {
            startDate: start_date,
            endDate: end_date,
            userIds: [],
            beforeUserIds: [],
          });
        }

        if (
          weekoffPolicy?.weekoffType == weekoffTypeEnum.FIX &&
          weekoffPolicy?.isMinDaysForFixWf
        ) {
          whDateRangeGroups.get(key)?.beforeUserIds?.push(userMasterID);
          dateRangeGroups.get(key)?.beforeUserIds?.push(userMasterID);
        }

        whDateRangeGroups.get(key).userIds.push(userMasterID);

        if (
          calculationType == SalaryPolicyTypeEnum.HOUR_WISE &&
          user_salaryPolicy?.monthly_ot_cal_type ==
            monthlyOTCalcuationType.SHIFT_PLUS_OT
        ) {
          if (!dateRangeGroupsForOT.has(key)) {
            dateRangeGroupsForOT.set(key, {
              startDate: start_date,
              endDate: end_date,
              userIds: [],
            });
          }
          dateRangeGroupsForOT.get(key).userIds.push(userMasterID);
        }
      }

      const object = {
        userData: user,
        attendanceVerify: attendanceVerify == 1 ? true : false,
        salaryPolicyMonthDays,
        left,
        notJoin,
        calculateFixMonthDays,
        FNF,
        joiningFlag,
        start_date,
        end_date,
        calculationType,
        overtimeAdded,
        monday,
        employeeshiftIds,
        monthName,
        user_salaryPolicy,
      };

      userMap.set(userMasterID, object);
    }

    // Query each date range group
    const allWeekoffHolidayData = [];
    const allAttendanceData = [];
    const allLeaveData = [];
    const allBeforeWH = [];
    const allBeforeAttendanceData = [];
    const allBeforeOutDutyData = [];

    const includeArray = [
      {
        model: Shift,
        attributes: ['shiftID'],
        include: [{ model: ShiftTIme }],
      },
      {
        required: false,
        model: overTimeCalculation,
        where: {
          AuthorizationRequired: 3,
        },
      },
    ];

    for (const [, group] of dateRangeGroups) {
      const startDate = group.startDate;
      const endDate = group.endDate;
      const userIds = group.userIds;

      const queryArray = [
        getOptimizedAttendanceTransactions({
          userIds,
          startDate,
          endDate,
          currentDate,
          includeArray,
        }),
        UserLeaveTransaction.findAll({
          where: {
            date: {
              [Sequelize.Op.between]: [startDate, endDate],
            },
            status: 1,
          },
          include: [
            {
              required: true,
              model: UserLeave,
              where: {
                userMasterID: {
                  [Sequelize.Op.in]: userIds,
                },
                status: 1,
              },
              attributes: ['DayType', 'userMasterID'],
            },
            {
              required: true,
              model: HrLeaveTypes,
              attributes: ['LeaveID'],
            },
          ],
        }),
      ];

      const beforeUserIds = group.beforeUserIds;

      if (beforeUserIds?.length) {
        const before_startdate = moment(startDate)
          .subtract(daysTogetBeforeData, 'days')
          .format('YYYY-MM-DD');

        const before_endDate = moment(startDate)
          .subtract(1, 'days')
          .format('YYYY-MM-DD');

        queryArray.push(
          getOptimizedAttendanceTransactions({
            userIds: beforeUserIds,
            startDate: before_startdate,
            endDate: before_endDate,
            currentDate,
            includeArray: null,
          }),
        );
        queryArray.push(
          UserLeaveTransaction.findAll({
            where: {
              status: 1,
              date: {
                [Sequelize.Op.between]: [before_startdate, before_endDate],
              },
            },
            include: [
              {
                model: HrLeaveTypes,
                where: {
                  LeaveID: 25,
                },
                attributes: ['LeaveID'],
                include: [{ model: HrLeaveMaster, as: 'LeaveMaster' }],
              },
              {
                model: UserLeave,
                where: {
                  userMasterID: { [Sequelize.Op.in]: beforeUserIds },
                },
              },
            ],
            attributes: ['LeaveTranId', 'days', 'date', 'status'],
          }),
        );
      }

      const [
        attendanceData,
        leaveData,
        beforeAttendanceData,
        beforeOutDutyData,
      ] = await Promise.all(queryArray);

      allAttendanceData.push(...attendanceData);
      allLeaveData.push(...leaveData);

      if (beforeAttendanceData?.length) {
        allBeforeAttendanceData.push(...beforeAttendanceData);
      }

      if (beforeOutDutyData?.length) {
        allBeforeOutDutyData.push(...beforeOutDutyData);
      }
    }

    for (const [, group] of whDateRangeGroups) {
      const startDate = group.startDate;
      const endDate = group.endDate;
      const userIds = group.userIds;

      const queryArray = [
        weekoffHolidayTran.findAll({
          raw: true,
          where: {
            userMasterID: { [Sequelize.Op.in]: userIds },
            date: { [Sequelize.Op.between]: [startDate, endDate] },
            [Sequelize.Op.or]: [
              { optionalHoliday: false },
              { optionalHoliday: { [Sequelize.Op.is]: null } },
            ],
          },
          attributes: [
            'userMasterID',
            'date',
            'value',
            'WHDayType',
            'tableName',
            'yearMonth',
          ],
        }),
      ];

      const beforeUserIds = group.beforeUserIds;

      if (beforeUserIds?.length) {
        const before_startdate = moment(startDate)
          .subtract(daysTogetBeforeData, 'days')
          .format('YYYY-MM-DD');

        const before_endDate = moment(startDate)
          .subtract(1, 'days')
          .format('YYYY-MM-DD');

        queryArray.push(
          weekoffHolidayTran.findAll({
            raw: true,
            where: {
              userMasterID: { [Sequelize.Op.in]: beforeUserIds },
              date: {
                [Sequelize.Op.between]: [before_startdate, before_endDate],
              },
              [Sequelize.Op.or]: [
                { optionalHoliday: false },
                { optionalHoliday: { [Sequelize.Op.is]: null } },
              ],
            },
            attributes: [
              'userMasterID',
              'date',
              'value',
              'WHDayType',
              'tableName',
              'yearMonth',
            ],
          }),
        );
      }

      const [whData, beforeWhData] = await Promise.all(queryArray);

      allWeekoffHolidayData.push(...whData);

      if (beforeWhData?.length) {
        allBeforeWH.push(...beforeWhData);
      }
    }

    // only for verified data
    const allExtraDaysData = [];
    const allCoffData = [];
    for (const [, group] of forCoffExtraDatesMap) {
      const startDate = group.startDate;
      const endDate = group.endDate;
      const userIds = group.userIds;

      const queryArray = [
        ExtraDays.findAll({
          where: {
            userMasterID: {
              [Sequelize.Op.in]: userIds,
            },
            authorizationStatus: 3,
            date: {
              [Sequelize.Op.between]: [startDate, endDate],
            },
          },
          attributes: ['userMasterID', 'date', 'days', 'From'],
        }),
        coffMaster.findAll({
          where: {
            userMasterID: {
              [Sequelize.Op.in]: userIds,
            },
            authorizationStatus: 3,
            LeaveCreatedDate: {
              [Sequelize.Op.between]: [startDate, endDate],
            },
          },
          attributes: [
            'userMasterID',
            'LeaveCreatedDate',
            'LeaveAddNew',
            'From',
          ],
        }),
      ];

      const [extraDays, coffData] = await Promise.all(queryArray);

      allExtraDaysData.push(...extraDays);
      allCoffData.push(...coffData);
    }

    // Create Map (userMasterID → tableName → date → data)
    const weekoffHolidayMap = new Map();
    allWeekoffHolidayData.forEach((item) => {
      if (!weekoffHolidayMap.has(+item.userMasterID)) {
        weekoffHolidayMap.set(+item.userMasterID, { holiday: {}, weekoff: {} });
      }
      const userMap = weekoffHolidayMap.get(+item.userMasterID);

      // Add to appropriate tableName (holiday or weekoff)
      if (item.tableName === offDayCategoryEnum.HOLIDAY) {
        userMap.holiday[item.date] = item;
      } else if (item.tableName === offDayCategoryEnum.WEEKOFF) {
        userMap.weekoff[item.date] = item;
      }
    });

    const beforeWeekoffHolidayMap = new Map();
    allBeforeWH.forEach((item) => {
      if (!beforeWeekoffHolidayMap.has(+item.userMasterID)) {
        beforeWeekoffHolidayMap.set(+item.userMasterID, {
          holiday: {},
          weekoff: {},
        });
      }
      const userMap = beforeWeekoffHolidayMap.get(+item.userMasterID);

      // Add to appropriate tableName (holiday or weekoff)
      if (item.tableName === offDayCategoryEnum.HOLIDAY) {
        userMap.holiday[item.date] = item;
      } else if (item.tableName === offDayCategoryEnum.WEEKOFF) {
        userMap.weekoff[item.date] = item;
      }
    });

    const allOTData = [];

    // ot Data

    for (const [, group] of dateRangeGroupsForOT) {
      const startDate = group.startDate;
      const endDate = group.endDate;
      const userIds = group.userIds;

      const data = await overTimeCalculation.findAll({
        attributes: [
          'UserMasterID',
          [
            Sequelize.fn('SUM', Sequelize.col('OverTimeHourAndMin')),
            'totalOverTime',
          ],
        ],
        where: {
          UserMasterID: {
            [Sequelize.Op.in]: userIds,
          },
          OverTimeDate: {
            [Sequelize.Op.between]: [startDate, endDate],
          },
        },
        group: ['UserMasterID'],
        raw: true,
      });

      allOTData.push(...data);
    }

    const oTDataMap = new Map();

    for (const ot of allOTData) {
      const key = +ot.UserMasterID;
      const value = +ot.totalOverTime;
      oTDataMap.set(key, value);
    }

    const attendanceDataMap = new Map();
    allAttendanceData.forEach((item) => {
      if (!attendanceDataMap.has(+item.userMasterID)) {
        attendanceDataMap.set(+item.userMasterID, []);
      }
      attendanceDataMap.get(+item.userMasterID).push(item);
    });

    const beforeAttendanceDataMap = new Map();
    allBeforeAttendanceData.forEach((item) => {
      if (!beforeAttendanceDataMap.has(+item.userMasterID)) {
        beforeAttendanceDataMap.set(+item.userMasterID, []);
      }
      beforeAttendanceDataMap.get(+item.userMasterID).push(item);
    });
    const beforeOutDutyDataMap = new Map();
    allBeforeOutDutyData.forEach((item) => {
      const userId = +item.userLeave?.userMasterID;

      if (!beforeOutDutyDataMap.has(+userId)) {
        beforeOutDutyDataMap.set(+userId, []);
      }
      beforeOutDutyDataMap.get(+userId).push(item);
    });
    const leaveDataMap = new Map();
    const odDataMap = new Map();
    allLeaveData.forEach((item) => {
      const userMasterID = item.userLeave?.userMasterID;
      if (userMasterID) {
        const leaveId = item.hrLeaveType?.LeaveID;

        if (leaveId == 25) {
          if (!odDataMap.has(+userMasterID)) {
            odDataMap.set(+userMasterID, []);
          }
          odDataMap.get(+userMasterID).push(item);
        } else {
          if (!leaveDataMap.has(+userMasterID)) {
            leaveDataMap.set(+userMasterID, []);
          }
          leaveDataMap.get(+userMasterID).push(item);
        }
      }
    });

    const extraDaysDataMap = buildNestedMap(allExtraDaysData, 'date', 'days');
    const coffDataMap = buildNestedMap(
      allCoffData,
      'LeaveCreatedDate',
      'LeaveAddNew',
    );

    // // extraDays Data map
    // const extraDaysDataMap = new Map();
    // for (const extraDays of allExtraDaysData) {
    //   const key = +extraDays.userMasterID;
    //   extraDaysDataMap.set(key, extraDays);
    // }

    // employee shift data

    const allShiftData = await Shift.findAll({
      where: {
        shiftID: {
          [Sequelize.Op.in]: [...allShiftIds],
        },
      },
      attributes: ['shiftID'],
      include: [{ model: ShiftTIme }],
    });

    const shiftMap = new Map();
    for (const shift of allShiftData) {
      const shiftId = +shift.shiftID;
      shiftMap.set(shiftId, shift.shiftTimes || []);
    }

    // ----------------- salary structure map ------------------

    const salaryStructureMap = await getSalaryMasterMap({
      employeeMonthPairs,
      payheadMasterIds: [payheadMasterIdsMapping.GROSS],
    });

    // salary maps
    const { salaryMasterMap, salaryTransactionMap } =
      await getSalary_SalaryMaster_DataMap([...salaryCalculatedUserIds], month);

    const handlers = {
      all: ({ attendancedataCal }) => {
        allData.push(attendancedataCal);
      },

      leave: ({ userMasterID, user_leave }) => {
        if (user_leave.length)
          onlyLeaveDataMapUserWise.set(userMasterID, user_leave);
      },
    };

    for (const [i, user] of Array.from(userMap.values()).entries()) {
      const userMasterID = +user.userData?.userMasterID;
      const leave = leaveDataMap.get(userMasterID);
      const odData = odDataMap.get(userMasterID);
      const attendanceData = attendanceDataMap.get(userMasterID);
      const end_date = user.end_date;
      const shiftIds = user.employeeshiftIds?.[0] || null;
      const shiftTime = shiftMap.get(+shiftIds)?.[0] || null;
      const extraDays = extraDaysDataMap.get(userMasterID);
      const coffData = coffDataMap.get(userMasterID);
      const salaryMasterData = user.attendanceVerify
        ? salaryMasterMap.get(userMasterID)
        : null;
      const salaryTransactionData = user.attendanceVerify
        ? salaryTransactionMap.get(userMasterID)
        : null;

      const user_attendancePolicy =
        (user.userData?.employeeAttendancePolicies || []).find(
          (e) =>
            new Date(e.startDate) <= new Date(end_date) &&
            (new Date(e.endDate) >= new Date(end_date) || !e.endDate),
        )?.attendancePolicy || null;

      const weekOffHolidayPriority =
        user_attendancePolicy?.WHPHPriority || null;

      const isAddlPaidDay = user_attendancePolicy?.isAddlPaidDay || false;

      const priority =
        weekOffHolidayPriority === 'PH'
          ? offDayCategoryEnum.HOLIDAY
          : offDayCategoryEnum.WEEKOFF;

      let temp_priority = priority;

      const userWiseWeekoffHoliday = weekoffHolidayMap.get(userMasterID);
      const calculationType = user.calculationType;
      const salaryCalAct =
        user?.userData?.employeeJoiningDetails?.[0]?.salaryCalculationAct ||
        null;

      // ----------------- Add extra days logic for holiday------------------

      let holidayExtraDays = 0;
      let weekoffCountForHourly = 0;

      if (calculationType != 'hourwise') {
        if (
          temp_priority == offDayCategoryEnum.HOLIDAY &&
          isAddlPaidDay &&
          salaryCalAct == salaryCalculationAct.FACTORYACT &&
          !user.attendanceVerify
        ) {
          temp_priority = offDayCategoryEnum.WEEKOFF;
          holidayExtraDays = getHolidaysOnWeekoffSum(
            userWiseWeekoffHoliday,
          ).sum;
        }
      } else {
        const ismonthlyFixhours =
          user?.user_salaryPolicy?.monthlyFixhours || null;

        if (
          salaryCalAct == salaryCalculationAct.FACTORYACT &&
          !ismonthlyFixhours
        ) {
          weekoffCountForHourly =
            Object.keys(userWiseWeekoffHoliday?.weekoff || {})?.length || 0;
        }
      }

      const weekoffHoliday = getAllWeekoffHolidayWithPriority(
        userWiseWeekoffHoliday,
        temp_priority,
      );
      // for before weekoff/holiday ----------------------
      const userWiseBeforeWH = beforeWeekoffHolidayMap.get(userMasterID);
      const beforeWeekoffHoliday = getAllWeekoffHolidayWithPriority(
        userWiseBeforeWH,
        priority,
      );

      // for before AttendanceData ----------------------

      const beforeAttendanceData = beforeAttendanceDataMap.get(userMasterID);

      const beforeOutDutyData = beforeOutDutyDataMap.get(userMasterID);

      const otMinutes = oTDataMap.get(userMasterID);

      let salaryAssign = true;

      if (user.attendanceVerify && !salaryTransactionData) {
        const salaryAssignData = salaryStructureMap.get(userMasterID) || null;

        salaryAssign = salaryAssignData ? true : false;
      }

      // set attendance policy empty array
      user.userData && (user.userData.employeeAttendancePolicies = []);

      const attendancedataCal = await optimiseAttendanceCalculation({
        user: user,
        month: month,
        Allleave_type: AllHrLeaveTypes,
        leave: leave,
        odData: odData,
        attendanceData: attendanceData,
        weekoffHoliday: weekoffHoliday,
        attendancePolicy: user_attendancePolicy,
        shiftTime: shiftTime,
        otMinutes: otMinutes,
        extraDays: extraDays,
        salaryMasterData: salaryMasterData,
        salaryTransactionData: salaryTransactionData,
        salaryAssign: salaryAssign,
        beforeWeekoffHoliday: beforeWeekoffHoliday,
        beforeAttendanceData: beforeAttendanceData,
        salaryEligibilityDocList: salaryEligibilityDocList,
        beforeOutDutyData: beforeOutDutyData,
        coffData,
        holidayExtraDays,
        weekoffCountForHourly,
      });

      if (isStream) {
        const baseProgress = 30;
        const calculationProgressRange = 70;
        const currentProgress =
          baseProgress +
          Math.round(((i + 1) / users.length) * calculationProgressRange);

        // Send progress update
        sendEvent(
          'progress',
          {
            phase: 'calculating',
            message: `Calculating: ${user.userData?.displayName}`,
            current: i + 1,
            total: users.length,
            progress: currentProgress,
            currentUser: {
              userMasterID: userMasterID,
              displayName: user.userData?.displayName,
            },
          },
          res,
        );

        // Send individual user data
        sendEvent(
          'user-data',
          {
            index: i,
            data: attendancedataCal,
          },
          res,
        );
      }

      const verify = attendancedataCal.verified;
      const user_leave = attendancedataCal.user_leave || [];

      handlers[returnType]?.({
        attendancedataCal,
        userMasterID,
        user_leave,
      });

      if (
        !verify &&
        ((attendancedataCal.user_leave &&
          attendancedataCal.user_leave?.length) ||
          attendancedataCal.notJoin ||
          attendancedataCal.left)
      ) {
        const toAddData = [];
        const toAddLCEGPenaltyData = [];

        const penaltyArray = attendancedataCal.penaltyArray || [];

        // for penalty

        for (const penalty of penaltyArray) {
          toAddLCEGPenaltyData.push({
            userMasterID: attendancedataCal.userMasterID,
            YYYYMM: +attendancedataCal.yearMonth,
            penaltyType: penalty.penaltyType,
            penaltyValue: penalty.values,
          });
        }

        for (let m = 0; m < user_leave.length; m++) {
          toAddData.push({
            userMasterID: attendancedataCal.userMasterID,
            LeaveTranId: user_leave[m].leavetranid,
            AttnYearMon: attendancedataCal.yearMonth,
            MonDays: attendancedataCal.MonDays,
            MonWorkDays: attendancedataCal.WorkingDays,
            AttnVal: user_leave[m].values,
            monthstartdate: attendancedataCal.start_date,
            monthenddate: attendancedataCal.end_date,
            createBy: req.userDetails?.userMasterId,
            createByIp: req.userDetails?.userIpAddress,
          });
        }

        //delete data

        await sequelize.transaction(async (t) => {
          await Promise.all([
            HrLeaveMonthlyTrans.destroy({
              where: {
                userMasterID: attendancedataCal.userMasterID,
                AttnYearMon: month,
              },
              transaction: t,
            }),
            LCEGPenalty.destroy({
              where: {
                userMasterID: attendancedataCal.userMasterID,
                YYYYMM: month,
              },
              transaction: t,
            }),
          ]);

          if (toAddData.length || toAddLCEGPenaltyData.length) {
            await Promise.all([
              HrLeaveMonthlyTrans.bulkCreate(toAddData, { transaction: t }),
              LCEGPenalty.bulkCreate(toAddLCEGPenaltyData, {
                individualHooks: true,
                user: req.userDetails,
                transaction: t,
              }),
            ]);
          }
        });
      }
    }

    return { allData, onlyLeaveDataMapUserWise };
  } catch (error) {
    throw new Error('Error in attendanceCalculationLatest :' + error);
  }
}

// ---- get salary master map of multiple users with multiple months --------
async function getSalaryMasterMap({
  employeeMonthPairs = [],
  payheadMasterIds = [], // optional
}) {
  if (!employeeMonthPairs.length) return new Map();

  // Dynamic payhead filter
  const payheadFilter =
    payheadMasterIds?.length > 0
      ? `AND hsf."payheadMasterId" IN (${payheadMasterIds.join(',')})`
      : '';

  // Dynamic VALUES binding
  const valuesClause = employeeMonthPairs
    .map((_, i) => `($${i * 2 + 1}::bigint, $${i * 2 + 2}::integer)`)
    .join(', ');

  const bindValues = employeeMonthPairs.flatMap((e) => [
    e.userMasterID,
    e.salaryMonth,
  ]);

  // if (payheadMasterIds?.length) {
  //   bindValues.push(payheadMasterIds);
  // }

  const salaryMasterData = await sequelize.query(
    `SELECT * FROM (
      SELECT 
        hsm."salaryMasterID",
        hsm."userMasterID",
        hsm."salaryFromYYYYMM",
        hsm."EmployeeSalaryAmount",
        gss."gradeSalaryStructureID",
        gs."baseOnCalculation",
        hsf."payheadMasterId",
        hsf."payheadDisplayName",
        emp."salaryMonth",
        ROW_NUMBER() OVER (
          PARTITION BY hsm."userMasterID", emp."salaryMonth", hsf."payheadMasterId"
          ORDER BY hsm."salaryFromYYYYMM" DESC
        ) as rn
      FROM "hrSalaryMasters" hsm
      INNER JOIN "gradeSalaryStructures" gss 
        ON hsm."gradeSalaryStructureID" = gss."gradeSalaryStructureID"
      INNER JOIN "gradeStructures" gs 
        ON gss."gradeStructureID" = gs."gradeStructureID"
      INNER JOIN "hrSalaryFields" hsf 
        ON gss."salaryFieldID" = hsf."salaryFieldID"
      INNER JOIN (
        VALUES ${valuesClause}
      ) AS emp("userMasterID", "salaryMonth") 
        ON hsm."userMasterID" = emp."userMasterID"
      WHERE hsm."salaryFromYYYYMM" <= emp."salaryMonth"
        AND hsm."status" = 1
        ${payheadFilter}
    ) ranked
    WHERE rn = 1`,
    {
      bind: bindValues,
      type: Sequelize.QueryTypes.SELECT,
    },
  );

  // Convert to nested Map
  const salaryMasterMap = new Map();

  for (const item of salaryMasterData) {
    const userID = +item.userMasterID;
    const month = +item.salaryMonth;
    const payheadID = +item.payheadMasterId;

    if (!salaryMasterMap.has(userID)) {
      salaryMasterMap.set(userID, new Map());
    }

    const userMonthMap = salaryMasterMap.get(userID);

    if (!userMonthMap.has(month)) {
      userMonthMap.set(month, new Map());
    }

    const monthPayheadMap = userMonthMap.get(month);

    monthPayheadMap.set(payheadID, item);
  }

  return salaryMasterMap;
}

// Helper function to send SSE events
const sendEvent = (eventType, data, res) => {
  res.write(`event: ${eventType}\n`);
  res.write(`data: ${JSON.stringify(data)}\n\n`);
};

