async function getDepartment_SkillCategoryWise(companyMasterID, skillCategory) {
  if (!companyMasterID) return [];

  const skillCategoryCondition = [
    { skillCategory: { [Sequelize.Op.is]: null } },
    { skillCategory: { [Sequelize.Op.eq]: [] } },
  ];

  if (skillCategory) {
    skillCategoryCondition.unshift({
      skillCategory: {
        [Sequelize.Op.contains]: [skillCategory],
      },
    });
  }

  const allData = await Designation.findAll({
    where: {
      companyMasterID,
      status: 1,
      [Sequelize.Op.or]: skillCategoryCondition,
    },
  });

  return allData;
}

