function getWeekOffBasedOnWeekoffAbsent({
  beforeWH = [],
  beforeAttendance = [],
  actualWeekoff = [],
  weekOffData = [],
  holidayData = [],
  attendanceData = [],
  startDate,
  weekoffPolicy,
  joiningDate,
  beforeOutDutyData = [],
  outDutyData = [],
}) {
  const object = { WeekoffAbsent: [], earningWeekoff: [] };

  if (!weekoffPolicy || !actualWeekoff.length) return object;

  const minPresentDaysForFixWF = weekoffPolicy.minPresentDaysForFixWF || 0;

  // Filter all before data to be greater than joining date
  const filteredBeforeWH = beforeWH.filter((e) => e.date >= joiningDate);
  const filteredBeforeAttendance = beforeAttendance.filter(
    (e) => e.AttendanceDate >= joiningDate,
  );

  const filteredBeforeOutDuty = beforeOutDutyData.filter(
    (e) => e.date >= joiningDate,
  );
  const allAttendanceData = [...filteredBeforeAttendance, ...attendanceData];

  const allOutDutyData = [...filteredBeforeOutDuty, ...outDutyData];

  // Separate weekoffs and holidays from beforeWH
  const beforeWeekoffs = filteredBeforeWH.filter(
    (e) => e.tableName === offDayCategoryEnum.WEEKOFF,
  );
  const allHolidayData = [
    ...filteredBeforeWH.filter(
      (e) => e.tableName === offDayCategoryEnum.HOLIDAY,
    ),
    ...holidayData,
  ];

  // Helper: Check if two dates are consecutive
  const isConsecutive = (date1, date2) => {
    return Math.abs(moment(date1).diff(moment(date2), 'days')) === 1;
  };

  // Helper: Find previous non-consecutive weekoff
  const findPreviousWeekoff = (currentWeekoffDate, beforeWHArray) => {
    if (!beforeWHArray.length) return null;

    let checkDate = currentWeekoffDate;

    // Traverse backwards through consecutive weekoffs
    for (let i = beforeWHArray.length - 1; i >= 0; i--) {
      const weekoff = beforeWHArray[i];

      if (isConsecutive(checkDate, weekoff.date)) {
        // Consecutive, continue checking backwards
        checkDate = weekoff.date;
      } else if (weekoff.date < checkDate) {
        // Not consecutive, found our previous weekoff
        return weekoff;
      }
    }

    // If all are consecutive, return null (will use joiningDate as start)
    return null;
  };

  // Helper: Calculate attendance + holidays in date range
  const calculateDaysInRange = (startDate, endDate) => {
    const attendanceDays = allAttendanceData
      .filter(
        (e) => e.AttendanceDate > startDate && e.AttendanceDate <= endDate,
      )
      .reduce((acc, obj) => acc + +obj.fulldayhalfday, 0);

    const holidayDays = allHolidayData
      .filter((e) => e.date > startDate && e.date <= endDate)
      .reduce((acc, obj) => acc + +obj.value, 0);
    const outDutyDays = allOutDutyData
      .filter((e) => e.date > startDate && e.date <= endDate)
      .reduce((acc, obj) => acc + +obj.days, 0);
    return attendanceDays + holidayDays + outDutyDays;
  };

  // Helper: Get attendance on specific weekoff day (max 0.5 for half-day, 0 for full-day)
  const getAttendanceOnWeekoff = (weekoffDate, weekoffValue) => {
    const attendance = allAttendanceData.find(
      (e) => e.AttendanceDate === weekoffDate,
    );
    const actualAttendance = attendance ? +attendance.fulldayhalfday : 0;

    // If half-day weekoff (value = 0.5), max attendance is 0.5
    // If full-day weekoff (value = 1.0), no attendance possible (0)
    if (+weekoffValue === 0.5) {
      return Math.min(actualAttendance, 0.5);
    }
    return 0;
  };

  const WeekoffAbsent = [];
  const allWeekoffs = [...beforeWeekoffs, ...actualWeekoff].sort((a, b) =>
    moment(a.date).diff(moment(b.date)),
  );

  // Process each weekoff in actualWeekoff
  for (let i = 0; i < actualWeekoff.length; i++) {
    const weekoff = actualWeekoff[i];
    const currentDate = weekoff.date;
    const currentValue = weekoff.value;

    // Find previous weekoff (handling consecutive chains)
    let previousWeekoff = null;

    if (i === 0) {
      // First weekoff in actualWeekoff, check beforeWeekoffs
      previousWeekoff = findPreviousWeekoff(currentDate, beforeWeekoffs);
    } else {
      // Check if consecutive with previous weekoff in actualWeekoff
      const prevActualWeekoff = actualWeekoff[i - 1];

      if (isConsecutive(currentDate, prevActualWeekoff.date)) {
        // Consecutive, find the previous non-consecutive weekoff
        const combinedBefore = [
          ...beforeWeekoffs,
          ...actualWeekoff.slice(0, i),
        ].sort((a, b) => moment(a.date).diff(moment(b.date)));
        previousWeekoff = findPreviousWeekoff(currentDate, combinedBefore);
      } else {
        // Not consecutive, use the previous actual weekoff
        previousWeekoff = prevActualWeekoff;
      }
    }

    // If no previous weekoff found, use joiningDate as the start
    const previousDate =
      previousWeekoff?.date ||
      moment(joiningDate).subtract(1, 'day').format('YYYY-MM-DD');

    // Calculate attendance and holidays in range
    let totalDays = 0;

    // Check if current weekoff is consecutive with any previous weekoffs
    const weekoffIndex = allWeekoffs.findIndex((w) => w.date === currentDate);
    let consecutiveStart = weekoffIndex;

    // Find the start of consecutive chain
    for (let j = weekoffIndex - 1; j >= 0; j--) {
      if (isConsecutive(allWeekoffs[j + 1].date, allWeekoffs[j].date)) {
        consecutiveStart = j;
      } else {
        break;
      }
    }

    const firstConsecutiveWeekoff = allWeekoffs[consecutiveStart];
    const rangeStartDate = previousDate;
    const rangeEndDate = moment(firstConsecutiveWeekoff.date)
      .subtract(1, 'days')
      .format('YYYY-MM-DD');

    // Add attendance + holidays in range
    totalDays += calculateDaysInRange(rangeStartDate, rangeEndDate);

    // Add attendance on consecutive weekoffs (from first consecutive to current)
    for (let j = consecutiveStart; j <= weekoffIndex; j++) {
      const wo = allWeekoffs[j];
      if (wo.date <= currentDate) {
        totalDays += getAttendanceOnWeekoff(wo.date, wo.value);
      }
    }

    // Check if minimum criteria met
    if (
      totalDays < minPresentDaysForFixWF &&
      weekOffData.some((e) => e.date == currentDate)
    ) {
      WeekoffAbsent.push(weekoff);
    }
  }

  // Filter out absent weekoffs
  const excludeDate = WeekoffAbsent.map((e) => e.date);
  const finalEarningWeekoff = weekOffData.filter(
    (e) => !excludeDate.includes(e.date),
  );

  object.WeekoffAbsent = WeekoffAbsent;
  object.earningWeekoff = finalEarningWeekoff;

  return object;
}

async function get7DaysBefore_WeekoffHoliday_Attendance_Map(
  userMasterID = [],
  startDate,
) {
  const result = {
    before_attendanceMap: new Map(),
    before_weekoffHolidayMap: new Map(),
    before_outDutyMap: new Map(),
  };

  if (!Array.isArray(userMasterID) || !userMasterID.length || !startDate) {
    return result;
  }

  const currentDate = moment().format('YYYY-MM-DD');

  const before_startdate = moment(startDate)
    .subtract(daysTogetBeforeData, 'days')
    .format('YYYY-MM-DD');

  const before_endDate = moment(startDate)
    .subtract(1, 'days')
    .format('YYYY-MM-DD');

  const [attendanceData, weekoffHolidayData, outDutyData] = await Promise.all([
    attendanceTransaction.findAll({
      where: {
        userMasterID: {
          [Sequelize.Op.in]: userMasterID,
        },
        AttendanceDate: {
          [Sequelize.Op.between]: [before_startdate, before_endDate],
        },
        [Sequelize.Op.or]: [
          {
            AttendanceDate: currentDate,
          },
          {
            AttendanceDate: {
              [Sequelize.Op.ne]: currentDate,
            },
            OutDateTime: {
              [Sequelize.Op.not]: null,
            },
          },
        ],
        roundOffMinutes: {
          [Sequelize.Op.or]: [
            {
              [Sequelize.Op.eq]: Sequelize.literal(`(
                SELECT MAX(at2."roundOffMinutes")
                FROM "attendanceTransactions" AS at2
                WHERE at2."AttendanceDate" = "attendanceTransaction"."AttendanceDate"
                  AND at2."userMasterID" = "attendanceTransaction"."userMasterID"
                  AND at2."roundOffMinutes" IS NOT NULL
              )`),
            },
            {
              [Sequelize.Op.and]: [
                Sequelize.literal(`
                  NOT EXISTS (
                    SELECT 1
                    FROM "attendanceTransactions" AS at2
                    WHERE at2."AttendanceDate" = "attendanceTransaction"."AttendanceDate"
                      AND at2."userMasterID" = "attendanceTransaction"."userMasterID"
                      AND at2."roundOffMinutes" IS NOT NULL
                  )
                `),
                { [Sequelize.Op.is]: null },
              ],
            },
          ],
        },
        AttendanceTransID: {
          [Sequelize.Op.notIn]: Sequelize.literal(`(
            WITH duplicate_records AS (
              SELECT
                "trans1"."AttendanceTransID",
                "trans1"."AttendanceDate",
                "trans1"."userMasterID",
                "trans1"."roundOffMinutes",
                ROW_NUMBER() OVER (
                  PARTITION BY "trans1"."userMasterID", "trans1"."AttendanceDate", "trans1"."roundOffMinutes"
                  ORDER BY "trans1"."AttendanceTransID" ASC
                ) AS row_num
              FROM "attendanceTransactions" AS "trans1"
              JOIN (
                SELECT "userMasterID", "AttendanceDate", "roundOffMinutes"
                FROM "attendanceTransactions"
                WHERE "userMasterID" IN (${userMasterID.join(',')})
                  AND "AttendanceDate" BETWEEN '${before_startdate}' AND '${before_endDate}'
                GROUP BY "userMasterID", "AttendanceDate", "roundOffMinutes"
                HAVING COUNT(*) > 1
              ) AS "trans"
                ON "trans1"."AttendanceDate" = "trans"."AttendanceDate"
                AND "trans1"."userMasterID" = "trans"."userMasterID"
                AND COALESCE(CAST("trans1"."roundOffMinutes" AS INTEGER), -1) =
                    COALESCE(CAST("trans"."roundOffMinutes" AS INTEGER), -1)
              WHERE "trans1"."userMasterID" IN (${userMasterID.join(',')})
                AND "trans1"."AttendanceDate" BETWEEN '${before_startdate}' AND '${before_endDate}'
            )
            SELECT "AttendanceTransID"
            FROM duplicate_records
            WHERE row_num > 1
          )`),
        },
      },
      order: [
        ['userMasterID', 'ASC'],
        ['AttendanceDate', 'ASC'],
      ],
    }),

    weekoffHolidayTran.findAll({
      raw: true,
      where: {
        userMasterID: { [Sequelize.Op.in]: userMasterID },
        date: { [Sequelize.Op.between]: [before_startdate, before_endDate] },
        [Sequelize.Op.or]: [
          { optionalHoliday: false },
          { optionalHoliday: { [Sequelize.Op.is]: null } },
        ],
      },
      attributes: [
        'userMasterID',
        'date',
        'value',
        'WHDayType',
        'tableName',
        'yearMonth',
      ],
    }),
    UserLeaveTransaction.findAll({
      where: {
        status: 1,
        date: {
          [Sequelize.Op.between]: [before_startdate, before_endDate],
        },
      },
      include: [
        {
          model: HrLeaveTypes,
          where: {
            LeaveID: 25,
          },
          attributes: ['LeaveID'],
          include: [{ model: HrLeaveMaster, as: 'LeaveMaster' }],
        },
        {
          model: UserLeave,
          userMasterID: {
            [Sequelize.Op.in]: userMasterID,
          },
        },
      ],
      attributes: ['LeaveTranId', 'days', 'date', 'status'],
    }),
  ]);

  // Attendance Map
  for (const attendance of attendanceData) {
    const userId = +attendance.userMasterID;

    if (!result.before_attendanceMap.has(userId)) {
      result.before_attendanceMap.set(userId, []);
    }

    result.before_attendanceMap.get(userId).push(attendance);
  }

  // Weekoff/Holiday Map
  for (const item of weekoffHolidayData) {
    const userId = +item.userMasterID;

    if (!result.before_weekoffHolidayMap.has(userId)) {
      result.before_weekoffHolidayMap.set(userId, {
        holiday: {},
        weekoff: {},
      });
    }

    const userMap = result.before_weekoffHolidayMap.get(userId);

    if (item.tableName === offDayCategoryEnum.HOLIDAY) {
      userMap.holiday[item.date] = item;
    } else if (item.tableName === offDayCategoryEnum.WEEKOFF) {
      userMap.weekoff[item.date] = item;
    }
  }

  //Outduty Map
  for (const outduty of outDutyData) {
    const userId = +outduty.userLeave?.userMasterID;

    if (!result.before_outDutyMap.has(userId)) {
      result.before_outDutyMap.set(userId, []);
    }

    result.before_outDutyMap.get(userId).push(outduty);
  }

  return result;
}
async function is_OvertimeAdd_otBasedOn_Company({ userMasterID, date }) {
  let isOvertimeAdd = false;
  if (!userMasterID || !date) {
    return isOvertimeAdd;
  }
  const findUserCompanyData = await UserMaster.findOne({
    where: { userMasterID, status: 1 },
    include: [{ model: companyMaster, attributes: ['otBasedOn'] }],
  });
  if (findUserCompanyData && findUserCompanyData.companyMaster) {
    if (
      findUserCompanyData.companyMaster?.otBasedOn === OTBasedOnEnum.PLANNING
    ) {
      const findDateWisePlanningData = await TeamOvertimePlanning.findOne({
        where: {
          date,
        },
        include: [
          {
            model: TeamOvertimePlanningDetails,
            as: 'details',
            where: { userMasterID },
            required: true,
          },
        ],
      });
      if (findDateWisePlanningData) {
        isOvertimeAdd = true;
      }
    } else {
      isOvertimeAdd = true;
    }
  }
  return isOvertimeAdd;
}

async function manage_WHConvertedToOT_TimeUnChange(
  attendancePolicy,
  updatedAttendance,
  createBy,
  createByIp,
  otAdded,
  monthlyOtCalType,
  companyMasterId,
  transaction,
) {
  if (!updatedAttendance || !attendancePolicy) return;

  const {
    fulldayhalfday,
    roundOffMinutes,
    OutDateTime,
    AttendanceDate,
    Shifthrs,
    ShiftoutTime,
    ShiftIntime,
    AttendanceTransID,
  } = updatedAttendance;

  let otMinutes = roundOffMinutes;
  let attendanceStatus = 0;
  const shiftMinutes = Math.round(+Shifthrs * 60);
  let preShiftOTMinutes = 0;

  // Only full-day attendance is eligible for OT recalculation
  if (fulldayhalfday == 1) {
    attendanceStatus = 1;

    const otConsiderAfter =
      attendancePolicy.considerOvertimeAfter ||
      considerOvertimeAfterEnum.AFTER_WORKING_HOURS;

    const overtimeEntryAfterMin = +attendancePolicy.overtimeEntryAfterMin || 0;
    const skipMinutesInOvertime = +attendancePolicy.skipMinutesInOvertime || 0;
    const extraOTEnabled = attendancePolicy.extraOt || false;
    const minExtraOtMinutes = +attendancePolicy.min_extra_ot_mins;
    const extraOtMinutes = +attendancePolicy.extra_ot_mins || 0;
    const overtimeMinutesCalType = attendancePolicy.overtimeType || null;
    const calculationValue = +attendancePolicy.typeValue || 0;

    if (otConsiderAfter === considerOvertimeAfterEnum.AFTER_SHIFT_OUTTIME) {
      preShiftOTMinutes = preShiftOvertimeRequest(
        attendancePolicy,
        updatedAttendance,
        otAdded,
        monthlyOtCalType,
        companyMasterId,
        transaction,
      );

      const isNextDay = moment(ShiftoutTime, 'h:mm A').isBefore(
        moment(ShiftIntime, 'h:mm A'),
      );

      const attendanceDate = moment(AttendanceDate)
        .add(isNextDay ? 1 : 0, 'day')
        .format('YYYY-MM-DD');

      const shiftOutDateTime = new Date(`${attendanceDate} ${ShiftoutTime}`);
      const outDateTime = new Date(OutDateTime);

      otMinutes =
        outDateTime > shiftOutDateTime
          ? Math.round(
              (outDateTime.getTime() - shiftOutDateTime.getTime()) / 60000,
            )
          : 0;
    } else {
      otMinutes -= shiftMinutes;
    }

    if (otMinutes > 0 && otMinutes > overtimeEntryAfterMin) {
      if (skipMinutesInOvertime > 0) otMinutes -= skipMinutesInOvertime;

      if (
        extraOTEnabled &&
        minExtraOtMinutes &&
        otMinutes >= minExtraOtMinutes
      ) {
        otMinutes += extraOtMinutes;
      }

      if (
        overtimeMinutesCalType === overtimeTypeEnum.SLOT_WISE &&
        calculationValue > 0
      ) {
        otMinutes = Math.floor(otMinutes / calculationValue) * calculationValue;
      } else if (
        overtimeMinutesCalType === overtimeTypeEnum.ROUND_OFF &&
        calculationValue > 0
      ) {
        const roundOffHours = roundToNearestHour(otMinutes, calculationValue);
        otMinutes = Math.round(roundOffHours * 60);
      }
    }
  }

  // update without ot minutes

  const withoutOtMinutes = Math.max(
    Math.min(roundOffMinutes - preShiftOTMinutes, shiftMinutes),
    0,
  );

  await attendanceTransaction.update(
    {
      withoutOtMinutes,
    },
    {
      where: {
        AttendanceTransID,
      },
      transaction,
    },
  );

  if (otMinutes <= 0) return;

  await convertWorkingHrstoOT_IfNotPresent(
    attendancePolicy,
    updatedAttendance,
    createBy,
    createByIp,
    otMinutes,
    otAdded,
    monthlyOtCalType,
    companyMasterId,
    transaction,
    attendanceStatus,
  );

  return;
}

function getNotAddedDocForSalary(
  salaryCalculated,
  salaryEligibilityDocList,
  userDocument,
  end_date = null,
) {
  let notAddedDocForSalary = '';

  if (!salaryCalculated && salaryEligibilityDocList?.length) {
    const userDocumentMap = new Map();

    for (const userdoc of userDocument) {
      const key = +userdoc.documentListID;
      if (!userDocumentMap.has(key)) userDocumentMap.set(key, []);
      userDocumentMap.get(key).push(userdoc);
    }

    const docName = [];

    for (const doc of salaryEligibilityDocList) {
      const key = +doc.documentListID;

      const matchingDocs = userDocumentMap.get(key);
      const hasValidDoc = matchingDocs?.some(
        (e) => !e.expiryDate || (end_date && e.expiryDate >= end_date),
      );

      if (!hasValidDoc) docName.push(doc.document?.documentName);
    }

    notAddedDocForSalary = docName.join(', ');
  }

  return notAddedDocForSalary;
}

async function preShiftOvertimeRequest(
  attendancePolicy,
  attendance,
  otAdded,
  monthlyOtCalType,
  companyMasterId,
  transaction = null,
) {
  let preShiftOTMinutes = 0;

  try {
    if (!attendancePolicy || !attendance) return preShiftOTMinutes;

    const {
      preShiftHrsConsideration,
      preShiftMin,
      attendancePolicyID,
      preShiftOT,
      considerOvertimeAfter,
      autoApprove,
    } = attendancePolicy;

    const {
      AttendanceTransID,
      userMasterID,
      InDatetime,
      AttendanceDate,
      Shift,
      Shifthrs,
      ShiftIntime,
      roundOffMinutes,
      createBy,
      createByIp,
      updateBy,
      updateByIp,
    } = attendance;

    await delete_Overtime_Attendance_Manual(
      userMasterID,
      AttendanceDate,
      transaction,
      OvertimeRequestTypeEnum.PRE_SHIFT,
    );

    // Pre-shift OT not applicable for this policy
    if (
      !preShiftOT ||
      considerOvertimeAfter == considerOvertimeAfterEnum.AFTER_WORKING_HOURS ||
      preShiftHrsConsideration != 1
    ) {
      return preShiftOTMinutes;
    }

    const shiftInDateTime = new Date(`${AttendanceDate} ${ShiftIntime}`);
    const punchInTime = new Date(InDatetime);

    // Punched in after shift start — no pre-shift OT
    if (punchInTime >= shiftInDateTime) return preShiftOTMinutes;

    const totalPreShiftMinutes = Math.round(
      (shiftInDateTime.getTime() - punchInTime.getTime()) / 60000,
    );

    // Doesn't meet minimum pre-shift threshold
    if (preShiftMin > 0 && preShiftMin > totalPreShiftMinutes) {
      return preShiftOTMinutes;
    }

    preShiftOTMinutes = totalPreShiftMinutes;

    if (+preShiftOTMinutes <= 0) return preShiftOTMinutes;

    const otInTimeAMPM = formatAMPM(punchInTime);
    const createdBy = updateBy || createBy;
    const createdByIp = updateByIp || createByIp;
    const shiftMinutes = Math.round(Shifthrs * 60);
    const withoutOtMinutes = Math.min(
      roundOffMinutes - totalPreShiftMinutes,
      shiftMinutes,
    );

    // Shared args used by both the monthly-OT and auto-approve paths
    const commonOtArgs = [
      AttendanceTransID,
      userMasterID,
      AttendanceDate,
      otInTimeAMPM,
      ShiftIntime,
      punchInTime,
      shiftInDateTime,
      preShiftOTMinutes,
      attendancePolicyID,
      companyMasterId,
    ];

    // Persist the "worked without OT" portion of the shift once, from either path
    const updateWithoutOtMinutes = () =>
      attendanceTransaction.update(
        {
          withoutOtMinutes:
            +withoutOtMinutes > 0 ? Math.round(+withoutOtMinutes) : 0,
        },
        { where: { AttendanceTransID }, ...(transaction && { transaction }) },
      );

    // Case 1: Monthly OT with SHIFT_PLUS_OT calculation type
    if (
      otAdded == overtimeAddedEnum.MONHTLY &&
      monthlyOtCalType == monthlyOTCalcuationType.SHIFT_PLUS_OT
    ) {
      const ratio = getOvertimeCalculationRatio(
        attendancePolicy,
        false,
        false,
        Shift,
        preShiftOTMinutes,
      );

      await addDailyOTRequestForMonthlyOT(
        ...commonOtArgs,
        ratio,
        createdBy,
        createByIp,
        transaction,
        OvertimeRequestTypeEnum.PRE_SHIFT,
      );

      await updateWithoutOtMinutes();

      return preShiftOTMinutes;
    }

    // Case 2: Auto-approve OT (within auto-approve threshold)
    if (autoApprove && +preShiftOTMinutes <= +autoApprove) {
      const ratio = getOvertimeCalculationRatio(
        attendancePolicy,
        false,
        false,
        Shift,
        preShiftOTMinutes,
      );

      await autoApproveOT_Manual(
        ...commonOtArgs,
        ratio,
        transaction,
        OvertimeRequestTypeEnum.PRE_SHIFT,
      );

      await updateWithoutOtMinutes();

      return preShiftOTMinutes;
    }

    // Case 3: Falls through to manual authorization workflow
    const overtimeRequestData = {
      AttendanceTransID,
      UserMasterID: userMasterID,
      OverTimeDate: AttendanceDate,
      OverTimeIn: otInTimeAMPM,
      OverTimeOut: ShiftIntime,
      OverTimeInDateTime: punchInTime,
      OverTimeOutDateTime: shiftInDateTime,
      OverTimeHourAndMin: preShiftOTMinutes,
      AttendancePolicyID: attendancePolicyID,
      CompanyMasterID: companyMasterId,
      otRequestType: OvertimeRequestTypeEnum.PRE_SHIFT,
      createBy: createdBy,
      createByIp: createdByIp,
    };

    await overtimeauthorization_Manual(overtimeRequestData, transaction);

    return preShiftOTMinutes;
  } catch (error) {
    console.error('Error in preShiftOvertimeRequest:', error);
    throw error;
  }
}

// -------------------------Payroll statutory calculation --------------------
function calculateSalaryMatch(
  earnedSalary,
  unpaidDays,
  dailyRate,
  monthlyRate,
) {
  const requiredDeduction = monthlyRate - earnedSalary;
  const rawDays = requiredDeduction / dailyRate;

  let matchedDays = Math.ceil(rawDays * 2) / 2;

  // Floor at 0 — this is what prevents diffDays from exceeding unpaidDays.
  // (diffDays = unpaidDays - matchedDays; that only exceeds unpaidDays when matchedDays < 0)
  if (matchedDays < 0) {
    matchedDays = 0;
  }

  let matchedSalary = monthlyRate - dailyRate * matchedDays;

  // Safety net for floating point / edge cases
  if (matchedSalary > earnedSalary) {
    matchedDays += 0.5;
    matchedSalary = monthlyRate - dailyRate * matchedDays;
  }

  const diffAmount = earnedSalary - matchedSalary; // negative only if matchedDays was floored to 0
  const diffDays = unpaidDays - matchedDays; // always <= unpaidDays, can be negative

  return { matchedSalary, diffAmount, diffDays };
}

function settleExtraDaysIntoPresent(presentData, unpaidData, extraDays) {
  const leaveOrder = [
    HrLeaveTypesIds.ABSENT,
    HrLeaveTypesIds.LWP,
    HrLeaveTypesIds.ATTENDANCE_PENALTY,
    HrLeaveTypesIds.ABSENT_DUE_TO_SANDWICH,
    HrLeaveTypesIds.WA,
  ];

  const presentDays = Number(presentData?.AttnVal) || 0;

  const updatedUnpaidData = unpaidData.map((e) => ({ ...e }));
  const updatedPresentData = { ...presentData };

  let remainingExtra = Number(extraDays) || 0;

  // Positive extra days -> convert unpaid to present
  if (remainingExtra > 0) {
    let totalSettled = 0;

    for (const leaveId of leaveOrder) {
      if (remainingExtra <= 0) break;

      const entry = updatedUnpaidData.find(
        (e) => e['hrLeaveType.LeaveID'] == leaveId,
      );
      if (!entry) continue;

      const currentVal = Number(entry.AttnVal) || 0;
      if (currentVal <= 0) continue;

      const settleAmount = Math.min(currentVal, remainingExtra);

      entry.AttnVal = currentVal - settleAmount;
      remainingExtra -= settleAmount;
      totalSettled += settleAmount;
    }

    updatedPresentData.AttnVal = presentDays + totalSettled;
  }

  // Negative extra days -> convert present to unpaid
  else if (remainingExtra < 0) {
    let deduction = Math.min(Math.abs(remainingExtra), presentDays);

    updatedPresentData.AttnVal = presentDays - deduction;

    for (const leaveId of leaveOrder) {
      if (deduction <= 0) break;

      let entry = updatedUnpaidData.find(
        (e) => e['hrLeaveType.LeaveID'] == leaveId,
      );

      // Create entry if it doesn't exist
      if (!entry) {
        entry = {
          'hrLeaveType.LeaveID': leaveId,
          AttnVal: 0,
        };
        updatedUnpaidData.push(entry);
      }

      entry.AttnVal = (Number(entry.AttnVal) || 0) + deduction;
      deduction = 0;
    }
  }

  return {
    updatedPresentData,
    updatedUnpaidData,
  };
}

function getOTMinutesFromExtraAmount(
  extraAmount,
  attendancePolicy,
  payrollStatutoryDetails,
  toDividedSalary,
) {
  if (!attendancePolicy) return 0;

  const { payType, overtimeHrs, payAmount } = attendancePolicy;

  let perMinuteSalary;

  if (payType === OTPayTypeEnum.FIXED_AMOUNT) {
    perMinuteSalary = (+payAmount || 0) / 60;
  } else {
    const payheadIdMap = {
      [OTPayTypeEnum.BASIC_SALARY]: payheadMasterIdsMapping.BASIC,
      [OTPayTypeEnum.CTC_SALARY]: payheadMasterIdsMapping.CTC,
      [OTPayTypeEnum.GROSS_SALARY]: payheadMasterIdsMapping.GROSS,
    };

    const payheadId = payheadIdMap[payType];
    const salary =
      payrollStatutoryDetails?.get(payheadId)?.EmployeeSalaryAmount ?? 0;
    const dailyAmount = toDividedSalary ? salary / toDividedSalary : salary;

    perMinuteSalary = dailyAmount / (+overtimeHrs || 480);
  }

  if (!perMinuteSalary) return 0;

  return Math.round((+extraAmount || 0) / perMinuteSalary);
}

function calculatePaidDays(
  earnedSalary,
  actualPaidDays,
  govDailyRate,
  roundTo = 0.5,
  maxDays,
) {
  // Exact days based on government daily rate
  const exactDays = earnedSalary / govDailyRate;

  // Round to nearest allowed unit (0.5 by default)
  let govPaidDays = Math.floor(exactDays / roundTo) * roundTo;

  // Cap at maxDays, if provided
  if (maxDays !== undefined && govPaidDays > maxDays) {
    govPaidDays = maxDays;
  }

  const govSalary = govPaidDays * govDailyRate;

  return {
    govPaidDays,
    govSalary,
    diffSalary: earnedSalary - govSalary,
    diffDays: govPaidDays - actualPaidDays,
  };
}

const savePdfBuffer = (buffer, fileName, outputDir) => {
  if (!Buffer.isBuffer(buffer)) {
    throw new Error('Invalid PDF buffer');
  }

  // Create directory if it doesn't exist
  fs.mkdirSync(outputDir, { recursive: true });

  const filePath = path.join(outputDir, fileName);

  fs.writeFileSync(filePath, buffer);

  return filePath;
};

function getMonthsFromPreviousMonth(previousMonth, count) {
  if (!previousMonth) return [];

  const pmStr = previousMonth.toString(); // works whether previousMonth is number or string
  const baseMonth = moment(pmStr, 'YYYYMM'); // parse previousMonth as a moment

  const months = [];
  for (let i = 0; i < count; i++) {
    months.push(baseMonth.clone().subtract(i, 'months').format('YYYYMM'));
  }
  return months;
}
async function getEmployeeCodeCompanyWise({
  allCompanies,
  companyMasterID,
  employeeCode,
  joiningDate,
}) {
  // const allCompanies = await getParentChildCompany(companyMasterID);
  const currentCompany = allCompanies?.find(
    (company) => company.companyMasterID == companyMasterID,
  );

  if (!currentCompany) {
    throw new Error('Company not found');
  }

  const employeeCodeType = currentCompany.employeeCodeType;

  // Determine if uniqueEmpCode applies across all companies
  let uniqueEmpCodeInAllCompany = false;
  if (currentCompany.parentCompanyMasterID == 0) {
    uniqueEmpCodeInAllCompany = currentCompany.uniqueEmpCode;
  } else {
    const parentCompany = allCompanies.find(
      (company) =>
        company.companyMasterID == currentCompany.parentCompanyMasterID,
    );
    uniqueEmpCodeInAllCompany = parentCompany?.uniqueEmpCode || false;
  }

  // Get company IDs for uniqueness check
  let allCompanyIds = [companyMasterID];
  if (uniqueEmpCodeInAllCompany) {
    allCompanyIds = allCompanies.map((c) => c.companyMasterID);
  }

  // Manual type - return the passed employeeCode
  if (employeeCodeType === employeeCodeTypes.MANUAL) {
    if (!employeeCode) {
      return {
        status: 200,
        message: '',
        employeeCode: null,
      };
    }
    const isCodeExist = await checkAlreayExistEmployeeCode(
      employeeCode,
      allCompanyIds,
    );
    if (isCodeExist.status != 200) {
      return {
        status: isCodeExist.status,
        message: isCodeExist.message,
        employeeCode: null,
      };
    }
    return {
      status: 200,
      message: '',
      employeeCode: employeeCode,
    };
  }

  // Auto type - find max numeric code and increment
  if (employeeCodeType === employeeCodeTypes.AUTO_INCREMENT) {
    const empCodeAutoStartsFromNumber = +currentCompany.empCodeAutoStartsFrom;
    let employees = await executeQuery(
      `select * from "employeeJoiningDetails" as empj left OUTER join "userMasters" as um on empj."userMasterID" = um."userMasterID" where um."companyMasterId" in (:allCompanyIds)` +
        ` and um.status in (0,1) and empj."employeeCode"~ '^[0-9]+$' ORDER BY (empj."employeeCode" :: BIGINT) DESC LIMIT 1`,
      {
        replacements: { allCompanyIds: allCompanyIds },
      },
    );

    let code = employees[0] ? Number(employees[0].employeeCode) + 1 : 1;
    if (empCodeAutoStartsFromNumber > code) {
      code = empCodeAutoStartsFromNumber;
    }
    return {
      status: 200,
      message: '',
      employeeCode: code.toString(),
    };
  }

  // Pattern type - use pattern + YYYYMM + sequential number
  if (employeeCodeType === employeeCodeTypes.PATTERN) {
    const pattern = currentCompany.employeeCodePattern || '';
    const joiningMonth = `${joiningDate.slice(0, 4)}${joiningDate.slice(5, 7)}`;
    const codePrefix = `${pattern}${joiningMonth}`;

    // PostgreSQL SUBSTRING position starts from 1.
    const sequenceStartPosition = codePrefix.length + 1;

    const employees = await executeQuery(
      `
    SELECT MAX(
      CAST(
        SUBSTRING("employeeCode" FROM :sequenceStartPosition)
        AS INTEGER
      )
    ) AS maxindex
    FROM "employeeJoiningDetails" AS empj
    LEFT JOIN "userMasters" AS um
      ON empj."userMasterID" = um."userMasterID"
    WHERE um."companyMasterId" IN (:allCompanyIds)
      AND um.status IN (0, 1)
      AND "employeeCode" ~ CONCAT('^', :codePrefix, '[0-9]+$')
  `,
      {
        replacements: {
          sequenceStartPosition: sequenceStartPosition,
          allCompanyIds: allCompanyIds,
          codePrefix: codePrefix,
        },
      },
    );

    const currentSequence = Number(employees?.[0]?.maxindex || 0);
    const nextSequence = currentSequence + 1;

    // Minimum 2 digits, but allows the sequence to continue after 99.
    const formattedSequence = String(nextSequence).padStart(2, '0');

    return {
      status: 200,
      message: '',
      employeeCode: `${codePrefix}${formattedSequence}`,
    };
  }
  // Pattern type - use pattern + YYYYMM + sequential number
  if (employeeCodeType === employeeCodeTypes.PATTERN_PLUS_AUTO_INCREMENT) {
    const pattern = currentCompany.employeeCodePattern || '';
    const sequenceLength = +currentCompany?.empCodeSeqLen || 2;
    const startPosition = pattern.length + 1; // PostgreSQL is 1-based
    const employees = await executeQuery(
      `
  SELECT MAX(
    CAST(SUBSTRING("employeeCode" FROM :startPosition) AS INTEGER)
  ) AS maxindex
  FROM "employeeJoiningDetails" AS empj
  LEFT JOIN "userMasters" AS um
    ON empj."userMasterID" = um."userMasterID"
  WHERE um."companyMasterId" IN (:allCompanyIds)
    AND um.status IN (0,1)
    AND "employeeCode" ~ ('^' || :pattern || '[0-9]+$')
  `,
      {
        replacements: {
          startPosition: startPosition,
          allCompanyIds: allCompanyIds,
          pattern: pattern,
        },
      },
    );
    const uniquePart = employees?.[0]?.maxindex || 0;

    const nextSequence = String(Number(uniquePart) + 1).padStart(
      sequenceLength,
      '0',
    );

    return {
      status: 200,
      message: '',
      employeeCode: pattern + nextSequence,
    };
  }
  return null;
}

async function checkAlreayExistEmployeeCode(employeeCode, companyMasterID) {
  try {
    const findUserWithEmployeecode = await EmployeeJoiningDetails.findOne({
      where: {
        employeeCode,
      },
      include: [
        {
          required: true,
          model: UserMaster,
          where: {
            companyMasterId: companyMasterID,
            status: [0, 1],
          },
        },
      ],
    });
    return {
      status: findUserWithEmployeecode ? 401 : 200,
      message: findUserWithEmployeecode
        ? message.usermessage.alreadyExists('Employee Code')
        : '',
    };
  } catch (error) {
    throw new Error('Error in Check Already Exist User ' + error.message);
  }
}

