function isStrongPassword(password) {
  if (!password || typeof password !== 'string' || password.length < 8) {
    return false;
  }

  const hasUpper = /[A-Z]/.test(password);
  const hasLower = /[a-z]/.test(password);
  const hasDigit = /[0-9]/.test(password);
  const hasSpecial = /[!@#$%^&*()_+\-=\[\]{}|;:'",.<>/?`~\\]/.test(password);

  return hasUpper && hasLower && hasDigit && hasSpecial;
}

function getVisitProductNames(data) {
  return (
    data?.vp
      ?.map((e) => e.product?.productName)
      .filter(Boolean)
      .join(', ') || ''
  );
}
function getPurposeOfVisitNames(data) {
  return (
    data?.pov
      ?.map((e) => e.visitPurpose?.visitPurpose)
      .filter(Boolean)
      .join(', ') || ''
  );
}
function getHolidaysOnWeekoffSum(data) {
  const { holiday, weekoff } = data;
  let sum = 0;
  const matchedDates = [];

  for (const date in holiday) {
    if (weekoff.hasOwnProperty(date)) {
      sum += holiday[date].value;
      matchedDates.push(date);
    }
  }

  return { sum, matchedDates };
}

function transformToKeyedObject(data) {
  const result = { holiday: {}, weekoff: {} };

  for (const entry of data) {
    if (
      entry.tableName === offDayCategoryEnum.HOLIDAY ||
      entry.tableName === offDayCategoryEnum.WEEKOFF
    ) {
      result[entry.tableName][entry.date] = entry;
    }
  }

  return result;
}

// helper: first day of month from YearMM (handles 'YYYY-MM' or 'YYYYMM')
function firstDateOfYearMM(yearMM) {
  if (!yearMM) return null;

  const parsed = moment(String(yearMM), 'YYYYMM', true);

  return parsed.isValid() ? parsed.startOf('month').format('YYYY-MM-DD') : null;
}
async function calculateFullDayHalfDay({ shiftID, dayName, totalWorkMin }) {
  try {
    if (!shiftID || !dayName || totalWorkMin == null) {
      return 0;
    }
    const dayWiseShiftTime = await shiftTime.findOne({
      where: {
        shiftID,
        day: dayName?.trim(),
      },
      attributes: ['totalhours', 'totalhourshalfday'],
      raw: true,
    });
    if (!dayWiseShiftTime) {
      return 0;
    }

    const shittothr = Number(dayWiseShiftTime?.totalhours || 0);
    const TEMPNUM = Number(dayWiseShiftTime?.totalhourshalfday || 0);

    // Convert configured decimal hours to minutes and round to integer
    const ShiftTotalMin = Math.round(shittothr * 60);
    const TempHalfDayMin = Math.round(TEMPNUM * 60);

    // Actual worked minutes
    const TotalWorkMin = Math.round(Number(totalWorkMin));

    let attcalculation = 0;

    if (TotalWorkMin !== 0) {
      if (TotalWorkMin >= ShiftTotalMin) {
        attcalculation = 1;
      } else if (TotalWorkMin >= TempHalfDayMin) {
        attcalculation = 0.5;
      } else {
        attcalculation = 0;
      }
    }
    return attcalculation;
  } catch (error) {
    throw new Error('Error in Calculate FullDay Half Day: ' + error.message);
  }
}

// Pf calculation for sept-2026 according to both rule old and new rule --------------

function pfCalculationForSep2026({
  companyPFConfig,
  payheadMasterId,
  maxRange,
  yearmonth,
  amount,
  actualAmount,
  salaryCalType,
  structureType,
  salaryDivideBy,
  paidDays,
  totalExtraAmount,
  start_date,
  pfjoiningDate,
  // add hourly inputs here
}) {
  if (
    !companyPFConfig ||
    !maxRange ||
    !PFCalculationMonth.includes(+yearmonth) ||
    !Object.hasOwn(NewRuleCapping, payheadMasterId)
  ) {
    return amount;
  }

  const { oldRuleDays, newRuleDays } = companyPFConfig;
  const totalRuleDays = oldRuleDays + newRuleDays;
  if (!totalRuleDays) return amount;

  const caps = {
    old: (maxRange * oldRuleDays) / totalRuleDays,
    new: (NewRuleCapping[payheadMasterId] * newRuleDays) / totalRuleDays,
  };

  const percentage = pfPercentage.get(payheadMasterId) || 0;

  const extraAmount = (totalExtraAmount * percentage) / 100;

  if (salaryCalType === 'hourly') {
    return calcHourlyPF({
      amount,
      actualAmount,
      caps,
      companyPFConfig /*, ...hourly inputs */,
    });
  }

  return calcDailyPF({
    actualAmount,
    caps,
    companyPFConfig,
    structureType,
    salaryDivideBy,
    paidDays,
    extraAmount,
    start_date,
    pfjoiningDate,
  });
}

/** Hourly salary — TODO: implement. Currently returns the original amount. */
function calcHourlyPF({ amount, actualAmount, caps, companyPFConfig }) {
  // Example skeleton for later:
  // const { oldRuleDays, newRuleDays } = companyPFConfig;
  // const oldHours = Math.min(paidHours, oldRuleDays * hoursPerDay);
  // const newHours = paidHours - oldHours;
  // return Math.min(oldHours * hourlyRate, caps.old) +
  //        Math.min(newHours * hourlyRate, caps.new);
  return amount;
}

/** Daily / monthly salary structures */
function calcDailyPF({
  actualAmount,
  caps,
  companyPFConfig,
  structureType,
  salaryDivideBy,
  paidDays,
  extraAmount,
  start_date,
  pfjoiningDate,
}) {
  let calOldDays = companyPFConfig.oldRuleDays;
  const isRoundOff = companyPFConfig?.isRoundOff || false;

  if (start_date) {
    const daysDifference =
      moment(OldPFRuleEndDate, 'YYYY-MM-DD').diff(
        moment(start_date, 'YYYY-MM-DD'),
        'days',
      ) + 1;

    calOldDays = daysDifference > 0 ? daysDifference : 0;
  }

  let perDayRate = actualAmount;
  calOldDays = (calOldDays * salaryDivideBy) / 30;

  if (isRoundOff) {
    calOldDays = Math.round(calOldDays);
  }

  if (structureType === SalaryStructureTypeEnum.MONTHLY) {
    perDayRate = actualAmount / salaryDivideBy;
  }

  let oldDays = Math.min(paidDays, calOldDays);
  const newDays = Math.max(paidDays - oldDays, 0);

  // only for brisk
  if (pfjoiningDate == '2026-09-17') {
    oldDays = 0;
  }

  return Math.min(
    Math.min(oldDays * perDayRate, caps.old) +
      Math.min(newDays * perDayRate, caps.new) +
      extraAmount,
    caps.old + caps.new,
  );
}

